// ============================================================
// FUNCIÓN DE CONSULTA
// ============================================================

function getObjetosRecomendados(pokemon) {
    if (!pokemon) return [];

    // 1) Por nombre concreto
    if (OBJETOS_RECOMENDADOS[pokemon.nombre]) {
        return OBJETOS_RECOMENDADOS[pokemon.nombre];
    }

    // 2) No está listado → [] (la IA cae al comportamiento genérico)
    return [];
}

