// ============================================================
// NAVEGACIÓN ENTRE VISTAS
// ============================================================
function abrirSeleccion(modo) {
    modoMenuSeleccionado = modo;
    window._iniciarTutorial1j = false;

    const btnTutorialSeleccion = document.getElementById('btnTutorial1j');
    if (btnTutorialSeleccion) {
        btnTutorialSeleccion.style.display = (modo === '1j') ? 'inline-flex' : 'none';
    }

    const titulo = document.getElementById('selTituloModo');
    const subtitulo = document.getElementById('selSubtituloModo');
    const panelJ2 = document.getElementById('panelJ2');
    const vsCenter = document.getElementById('vsCenter');

    if (modo === '1j') {
        titulo.textContent = '1 JUGADOR';
        subtitulo.textContent = 'Selecciona tu avatar y tu nombre';
        if (panelJ2) panelJ2.classList.add('oculto');
        if (vsCenter) vsCenter.classList.add('oculto');
    } else {
        titulo.textContent = '1 JUGADOR VS 2 JUGADORES';
        subtitulo.textContent = 'Selecciona tu avatar y tu nombre';
        if (panelJ2) panelJ2.classList.remove('oculto');
        if (vsCenter) vsCenter.classList.remove('oculto');
    }

    document.getElementById('vistaMenu').classList.remove('activa');
    document.getElementById('vistaSeleccion').classList.add('activa');

    if (typeof playButtonSound === 'function') playButtonSound();
}

function volverAlMenu() {
    document.getElementById('vistaSeleccion').classList.remove('activa');
    document.getElementById('vistaMenu').classList.add('activa');

    // 🗺️ El menú principal siempre muestra un mapa desbloqueado
    // (el elegido o Pradera), nunca el último terreno de una partida.
    if (window.LogrosUI && typeof LogrosUI.actualizarMapSelector === 'function') {
        LogrosUI.actualizarMapSelector();
    }

    if (typeof playButtonSound === 'function') playButtonSound();
}

// ============================================================
// CONSTRUIR GRID DE AVATARES
// ============================================================
function construirAvatarGridEn(containerId, avatarSeleccionado, onSelect) {
    const grid = document.getElementById(containerId);
    if (!grid) return;
    grid.innerHTML = '';

    for (let avatar of AVATARES_JUGADOR) {
        const option = document.createElement('div');
        option.className = 'menu-avatar-option';
        option.dataset.avatarId = avatar.id;
        option.title = avatar.nombre;

        if (avatar.id === avatarSeleccionado) option.classList.add('selected');

        const img = document.createElement('img');
        img.src = `assets/avatars/jugador/${avatar.archivo}`;
        img.alt = avatar.nombre;
        img.draggable = false;
        img.onerror = function () {
            this.style.display = 'none';
            if (!option.querySelector('.avatar-emoji')) {
                const emoji = document.createElement('span');
                emoji.className = 'avatar-emoji';
                emoji.textContent = avatar.emoji;
                option.appendChild(emoji);
            }
        };
        option.appendChild(img);

        option.addEventListener('click', function () {
            grid.querySelectorAll('.menu-avatar-option').forEach(o => o.classList.remove('selected'));
            this.classList.add('selected');
            onSelect(avatar.id);

            const displayId = containerId === 'menuAvatarGrid' ? 'avatarDisplay1' : 'avatarDisplay2';
            const display = document.getElementById(displayId);
            if (display) {
                display.src = `assets/avatars/jugador/${avatar.archivo}`;
                display.style.display = 'block';
            }

            const esJugador1 = (containerId === 'menuAvatarGrid');
            const characterImgId = esJugador1 ? 'characterImage1' : 'characterImage2';
            const characterImg = document.getElementById(characterImgId);
            if (characterImg) {
                const nombreSinExtension = avatar.archivo.replace('.png', '');
                characterImg.src = `assets/avatars/personajes/${nombreSinExtension}full.webp`;
                characterImg.alt = avatar.nombre;
            }

            if (esJugador1) {
                const footerAvatar = document.getElementById('footerAvatar');
                if (footerAvatar) {
                    footerAvatar.innerHTML = '';
                    const footerImg = document.createElement('img');
                    footerImg.src = `assets/avatars/jugador/${avatar.archivo}`;
                    footerImg.alt = avatar.nombre;
                    footerImg.style.width = '100%';
                    footerImg.style.height = '100%';
                    footerImg.style.objectFit = 'cover';
                    footerImg.style.borderRadius = '50%';
                    footerImg.onerror = function() {
                        this.style.display = 'none';
                        footerAvatar.textContent = avatar.emoji;
                    };
                    footerAvatar.appendChild(footerImg);
                }
            }

            if (typeof playButtonSound === 'function') playButtonSound();
        });

        grid.appendChild(option);
    }
}

function construirAvatarGrid(avatarSeleccionado) {
    construirAvatarGridEn('menuAvatarGrid', avatarSeleccionado, function (id) {
        avatarJugador = id;
        window.avatarJugador = avatarJugador;
        try { localStorage.setItem('avatarJugador', avatarJugador); } catch (e) {}
    });
}

function construirAvatarGrid2(avatarSeleccionado) {
    construirAvatarGridEn('menuAvatarGrid2', avatarSeleccionado, function (id) {
        avatarJugador2 = id;
        window.avatarJugador2 = avatarJugador2;
        try { localStorage.setItem('avatarJugador2', avatarJugador2); } catch (e) {}
    });
}

// ============================================================
// 🎨 COLOR DE BORDE (selector de jugadores)
// ============================================================
function hexToRgbTriplet(hex) {
    if (typeof hex !== 'string') return '77, 212, 247';
    let h = hex.replace('#', '').trim();
    if (h.length === 3) h = h.split('').map(c => c + c).join('');
    if (h.length !== 6) return '77, 212, 247';
    const n = parseInt(h, 16);
    if (Number.isNaN(n)) return '77, 212, 247';
    return `${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}`;
}
window.hexToRgbTriplet = hexToRgbTriplet;

function aplicarColoresBorde() {
    const c1 = (typeof colorBordeJ1 === 'string' ? colorBordeJ1 : '#4dd4f7');
    const c2 = (typeof colorBordeJ2 === 'string' ? colorBordeJ2 : '#ff4d8d');
    const root = document.documentElement;
    if (root) {
        root.style.setProperty('--borde-j1-rgb', hexToRgbTriplet(c1));
        root.style.setProperty('--borde-j2-rgb', hexToRgbTriplet(c2));
    }
}
window.aplicarColoresBorde = aplicarColoresBorde;

function construirColorGrid(containerId, colorSeleccionado, onSelect) {
    const grid = document.getElementById(containerId);
    if (!grid) return;
    grid.innerHTML = '';
    for (let c of COLORES_BORDE) {
        const opt = document.createElement('div');
        opt.className = 'menu-color-option';
        opt.style.background = c.valor;
        opt.title = c.nombre;
        if (c.valor.toLowerCase() === String(colorSeleccionado).toLowerCase()) opt.classList.add('selected');
        opt.addEventListener('click', function () {
            grid.querySelectorAll('.menu-color-option').forEach(o => o.classList.remove('selected'));
            this.classList.add('selected');
            onSelect(c.valor);
            if (typeof playButtonSound === 'function') playButtonSound();
        });
        grid.appendChild(opt);
    }
}

function construirColorGrid1(sel) {
    construirColorGrid('menuColorGrid', sel, function (valor) {
        colorBordeJ1 = valor;
        window.colorBordeJ1 = valor;
        try { localStorage.setItem('colorBordeJ1', valor); } catch (e) {}
        aplicarColoresBorde();
    });
}

function construirColorGrid2(sel) {
    construirColorGrid('menuColorGrid2', sel, function (valor) {
        colorBordeJ2 = valor;
        window.colorBordeJ2 = valor;
        try { localStorage.setItem('colorBordeJ2', valor); } catch (e) {}
        aplicarColoresBorde();
    });
}

// ============================================================
// 🆕 FIX: conecta los botones del header de la Pokédex
// (📖 Pokédex y ⚙️ Ajustes) de forma idempotente.
// - Si los botones ya existen en el HTML, solo engancha listeners
//   si no los tenían ya (dataset.wired).
// - Si no existen, los crea.
// ============================================================
function conectarBotonesHeaderPokedex(overlay) {
    if (!overlay) return;

    const headerPokedex = overlay.querySelector('.menu-header');
    if (!headerPokedex) return;

    // 1) Si no hay .top-actions, lo creamos
    let topActions = headerPokedex.querySelector('.top-actions');
    if (!topActions) {
        topActions = document.createElement('div');
        topActions.className = 'top-actions';
        topActions.innerHTML = `
            <button class="menu-icon-btn" title="Perfil">👤</button>
            <button class="menu-icon-btn" title="Pokédex" id="btnCompendioPokedex">📖</button>
            <button class="menu-icon-btn" title="Ajustes" id="btnAjustesMenuPokedex">⚙️</button>
        `;
        headerPokedex.appendChild(topActions);
    }

    // 2) Perfil (sin acción por ahora)
    const btnPerfil = topActions.querySelector('button[title="Perfil"]');
    if (btnPerfil && btnPerfil.dataset.wired !== '1') {
        btnPerfil.dataset.wired = '1';
        btnPerfil.addEventListener('click', (e) => {
            e.preventDefault();
        });
    }

    // 3) 📖 Pokédex (refresca la lista si ya estamos dentro)
    const btnCompendio = topActions.querySelector('#btnCompendioPokedex')
        || topActions.querySelector('button[title="Pokédex"]');
    if (btnCompendio && btnCompendio.dataset.wired !== '1') {
        btnCompendio.dataset.wired = '1';
        btnCompendio.addEventListener('click', (e) => {
            e.preventDefault();
            if (typeof renderizarPokedex === 'function') renderizarPokedex();
        });
    }

    // 4) ⚙️ Ajustes
    const btnAjustes = topActions.querySelector('#btnAjustesMenuPokedex')
        || topActions.querySelector('button[title="Ajustes"]');
    if (btnAjustes && btnAjustes.dataset.wired !== '1') {
        btnAjustes.dataset.wired = '1';
        btnAjustes.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            if (typeof window.abrirAjustes === 'function') {
                window.abrirAjustes();
            } else {
                console.warn('⚠️ window.abrirAjustes no está definida (¿ajustes.js no cargó?)');
            }
        });
    }
}

// ============================================================
// 🏷️ VERSIÓN DESPLEGADA (para saber si se ha actualizado)
// ============================================================
function initVersionBadge() {
    const el = document.getElementById('appVersion');
    if (!el) return;
    let yaIniciado = false;
    if (el.dataset.iniciado === '1') yaIniciado = true;
    el.dataset.iniciado = '1';

    async function refrescar() {
        // Abriendo index.html con doble clic (file://) no hay servidor: el fetch
        // a /api/version provocaba errores CORS en consola. Ahí no se consulta.
        if (location.protocol === 'file:') {
            el.textContent = 'v0.2.0 · local';
            el.title = 'Abierto como archivo local: la versión del servidor no está disponible.';
            return;
        }
        try {
            const r = await fetch('/api/version', { cache: 'no-store' });
            const d = await r.json();
            const clave = (d.commit || '') + '|' + (d.version || '');
            let prev = null;
            try { prev = localStorage.getItem('pktft_version'); } catch (e) { }
            const nueva = !!(prev && prev !== clave);
            try { localStorage.setItem('pktft_version', clave); } catch (e) { }

            const arranque = d.bootedAt ? new Date(d.bootedAt).toLocaleString('es-ES') : '—';
            el.textContent = `v${d.version || '?'} · ${d.commit || 'dev'}${nueva ? ' · 🆕 ACTUALIZADO' : ''}`;
            el.title =
                `Versión: ${d.version || '?'}\n` +
                `Commit: ${d.commit || 'dev'}${d.branch ? ' (' + d.branch + ')' : ''}\n` +
                `Servidor arrancado: ${arranque}\n` +
                `Entorno: ${d.env || '?'}\n\n` +
                'Pulsa para comprobar si hay una versión nueva.';
            el.classList.toggle('nueva', nueva);
            if (nueva) console.log(`🆕 Nueva versión desplegada: v${d.version} (${d.commit})`);
        } catch (e) {
            el.textContent = 'versión no disponible (servidor apagado)';
            el.title = String(e && e.message || e);
        }
    }

    el.addEventListener('click', async () => {
        const txt = el.textContent;
        el.textContent = 'comprobando…';
        await refrescar();
        setTimeout(() => { if (el.textContent === 'comprobando…') el.textContent = txt; }, 1500);
    });

    refrescar();
    // Re-comprobar al volver a la pestaña (útil tras desplegar)
    if (!yaIniciado) {
        document.addEventListener('visibilitychange', () => {
            if (document.visibilityState === 'visible') refrescar();
        });
    }
}

// ============================================================
// INICIALIZAR MENÚ
// ============================================================
function initMenu() {
    console.log("📋 Inicializando menú principal...");
    try { initVersionBadge(); } catch (e) { console.warn('No se pudo iniciar el badge de versión', e); }

    const menu = document.getElementById('menuPrincipal');
    const juego = document.getElementById('juegoContainer');

    if (menu) menu.style.display = 'flex';
    if (juego) juego.style.display = 'none';

    // Botones de modo
    document.getElementById('btnModo1j')?.addEventListener('click', () => abrirSeleccion('1j'));
    document.getElementById('btnModo2j')?.addEventListener('click', () => {
        if (typeof window.mostrarEleccion2J === 'function') window.mostrarEleccion2J();
        else abrirSeleccion('2j');
    });
    document.getElementById('btnVolverMenu')?.addEventListener('click', volverAlMenu);

    document.getElementById('btnModoCreativo')?.addEventListener('click', () => {
        // ⛶ Pantalla completa (dentro del gesto de usuario)
        if (typeof window.activarPantallaCompleta === 'function') window.activarPantallaCompleta();
        window.modoDosJugadores = false;
        window.turnoJugador = 1;
        if (typeof window.actualizarInterfazTurno === 'function') window.actualizarInterfazTurno();
        if (menu) menu.style.display = 'none';
        if (juego) juego.style.display = 'block';
        // 🔆 Evitar que la pantalla del móvil se apague durante la partida
        if (typeof window.activarPantallaSiempre === 'function') window.activarPantallaSiempre();
        if (typeof init === 'function') init();
        setTimeout(() => { if (typeof initModoCreativo === 'function') initModoCreativo(); }, 500);
    });

    // Inputs
    const inputNombre = document.getElementById('inputNombreJugador');
    const inputNombre2 = document.getElementById('inputNombreJugador2');
    const charCount1 = document.getElementById('charCount1');
    const charCount2 = document.getElementById('charCount2');

    try {
        const nombreGuardado = localStorage.getItem('nombreJugador');
        if (nombreGuardado && nombreGuardado.trim() !== '') nombreJugador = nombreGuardado.trim();
        const nombreGuardado2 = localStorage.getItem('nombreJugador2');
        if (nombreGuardado2 && nombreGuardado2.trim() !== '') nombreJugador2 = nombreGuardado2.trim();
    } catch (e) {}

    if (inputNombre) {
        inputNombre.value = nombreJugador;
        if (charCount1) charCount1.textContent = `${nombreJugador.length} / 16`;
        inputNombre.addEventListener('input', function () {
            const valor = this.value.trim();
            nombreJugador = valor !== '' ? valor : "Entrenador";
            window.nombreJugador = nombreJugador;
            if (charCount1) charCount1.textContent = `${this.value.length} / 16`;
            try { localStorage.setItem('nombreJugador', nombreJugador); } catch (e) {}
            const footerName = document.getElementById('footerName');
            if (footerName) footerName.textContent = nombreJugador;
        });
    }

    if (inputNombre2) {
        inputNombre2.value = nombreJugador2;
        if (charCount2) charCount2.textContent = `${nombreJugador2.length} / 16`;
        inputNombre2.addEventListener('input', function () {
            const valor = this.value.trim();
            nombreJugador2 = valor !== '' ? valor : "Jugador 2";
            window.nombreJugador2 = nombreJugador2;
            if (charCount2) charCount2.textContent = `${this.value.length} / 16`;
            try { localStorage.setItem('nombreJugador2', nombreJugador2); } catch (e) {}
        });
    }

    window.nombreJugador = nombreJugador;
    window.nombreJugador2 = nombreJugador2;

    // Avatares
    try {
        const avatarGuardado = localStorage.getItem('avatarJugador');
        if (avatarGuardado && AVATARES_JUGADOR.some(a => a.id === avatarGuardado)) avatarJugador = avatarGuardado;
        const avatarGuardado2 = localStorage.getItem('avatarJugador2');
        if (avatarGuardado2 && AVATARES_JUGADOR.some(a => a.id === avatarGuardado2)) avatarJugador2 = avatarGuardado2;
    } catch (e) {}

    window.avatarJugador = avatarJugador;
    window.avatarJugador2 = avatarJugador2;
    construirAvatarGrid(avatarJugador);
    construirAvatarGrid2(avatarJugador2);

    // 🎨 Colores de borde
    try {
        const c1 = localStorage.getItem('colorBordeJ1');
        if (c1) colorBordeJ1 = c1;
        const c2 = localStorage.getItem('colorBordeJ2');
        if (c2) colorBordeJ2 = c2;
    } catch (e) {}
    window.colorBordeJ1 = colorBordeJ1;
    window.colorBordeJ2 = colorBordeJ2;
    construirColorGrid1(colorBordeJ1);
    construirColorGrid2(colorBordeJ2);
    aplicarColoresBorde();

    // Avatar grande inicial y Footer
    const display1 = document.getElementById('avatarDisplay1');
    const footerAvatar = document.getElementById('footerAvatar');

    if (display1) {
        const av = AVATARES_JUGADOR.find(a => a.id === avatarJugador);
        if (av) display1.src = `assets/avatars/jugador/${av.archivo}`;
    }

    if (footerAvatar) {
        const av = AVATARES_JUGADOR.find(a => a.id === avatarJugador);
        if (av) {
            footerAvatar.innerHTML = '';
            const footerImg = document.createElement('img');
            footerImg.src = `assets/avatars/jugador/${av.archivo}`;
            footerImg.alt = av.nombre;
            footerImg.style.width = '100%';
            footerImg.style.height = '100%';
            footerImg.style.objectFit = 'cover';
            footerImg.style.borderRadius = '50%';
            footerImg.onerror = function() {
                this.style.display = 'none';
                footerAvatar.textContent = av.emoji;
            };
            footerAvatar.appendChild(footerImg);
        }
    }

    const display2 = document.getElementById('avatarDisplay2');
    if (display2) {
        const av = AVATARES_JUGADOR.find(a => a.id === avatarJugador2);
        if (av) display2.src = `assets/avatars/jugador/${av.archivo}`;
    }

    const footerName = document.getElementById('footerName');
    if (footerName) footerName.textContent = nombreJugador;

    // Botón ¡LISTO!
    const btnJugar = document.getElementById('btnJugar');
    if (btnJugar) {
        btnJugar.addEventListener('click', function (e) {
            e.preventDefault();

            // ⛶ Pantalla completa (debe pedirse dentro del gesto de usuario)
            if (typeof window.activarPantallaCompleta === 'function') window.activarPantallaCompleta();

            const esTutorial1j = (window._iniciarTutorial1j === true && modoMenuSeleccionado === '1j');
            window._iniciarTutorial1j = false;

            if (inputNombre) {
                const valor = inputNombre.value.trim();
                nombreJugador = valor !== '' ? valor : "Entrenador";
                window.nombreJugador = nombreJugador;
            }
            if (inputNombre2) {
                const valor2 = inputNombre2.value.trim();
                nombreJugador2 = valor2 !== '' ? valor2 : "Jugador 2";
                window.nombreJugador2 = nombreJugador2;
            }

            window.avatarJugador = avatarJugador;
            window.avatarJugador2 = avatarJugador2;

            const es2P = (modoMenuSeleccionado === '2j');
            console.log(`🎮 Iniciando partida (modo ${es2P ? '2 JUGADORES' : '1 JUGADOR'})`);

            if (menu) menu.style.display = 'none';
            if (juego) juego.style.display = 'block';

            // 🔆 Evitar que la pantalla del móvil se apague durante la partida
            if (typeof window.activarPantallaSiempre === 'function') window.activarPantallaSiempre();

            if (es2P) {
                window.modoDosJugadores = true;
                if (typeof init === 'function') init();
                setTimeout(() => {
                    if (typeof window.iniciarModoDosJugadores === 'function') window.iniciarModoDosJugadores();
                }, 300);
            } else {
                window.modoDosJugadores = false;
                window.turnoJugador = 1;
                if (typeof window.actualizarInterfazTurno === 'function') window.actualizarInterfazTurno();
                if (typeof init === 'function') init();

                if (esTutorial1j) {
                    setTimeout(function () {
                        if (typeof window.iniciarTutorial1j === 'function') {
                            window.iniciarTutorial1j();
                        }
                    }, 600);
                }
            }

            if (typeof playButtonSound === 'function') playButtonSound();
        });
    }

    // 🎓 Botón Tutorial (solo 1 jugador)
    const btnTutorial1j = document.getElementById('btnTutorial1j');
    if (btnTutorial1j) {
        btnTutorial1j.addEventListener('click', function (e) {
            e.preventDefault();
            window._iniciarTutorial1j = true;
            const btn = document.getElementById('btnJugar');
            if (btn) btn.click();
        });
    }

    // Pokédex
    const btnPokedex = document.getElementById('btnCompendio');
    if (btnPokedex) btnPokedex.addEventListener('click', function (e) { e.preventDefault(); abrirPokedex(); });

    // 🆕 Ajustes del menú principal
    const btnAjustesMenu = document.getElementById('btnAjustesMenu');
    if (btnAjustesMenu) {
        btnAjustesMenu.addEventListener('click', function (e) {
            e.preventDefault();
            e.stopPropagation();
            if (typeof window.abrirAjustes === 'function') {
                window.abrirAjustes();
            }
        });
    }

    // 🆕 Botones del header de la vista de selección
    const btnPokedexSeleccion = document.getElementById('btnCompendioSeleccion');
    if (btnPokedexSeleccion) {
        btnPokedexSeleccion.addEventListener('click', function (e) {
            e.preventDefault();
            abrirPokedex();
        });
    }

    const btnAjustesSeleccion = document.getElementById('btnAjustesMenuSeleccion');
    if (btnAjustesSeleccion) {
        btnAjustesSeleccion.addEventListener('click', function (e) {
            e.preventDefault();
            e.stopPropagation();
            if (typeof window.abrirAjustes === 'function') {
                window.abrirAjustes();
            }
        });
    }
    document.getElementById('btnCerrarPokedex')?.addEventListener('click', cerrarPokedex);
    document.getElementById('pokedexOverlay')?.addEventListener('click', function (e) { if (e.target === this) cerrarPokedex(); });

    const btnVolverDetalle = document.getElementById('btnPokedexDetalleVolver');
    if (btnVolverDetalle) btnVolverDetalle.addEventListener('click', cerrarPokedexDetalle);
    const btnCerrarDetalle = document.getElementById('btnPokedexDetalleCerrar');
    if (btnCerrarDetalle) btnCerrarDetalle.addEventListener('click', function() { cerrarPokedexDetalle(); cerrarPokedex(); });
    document.getElementById('pokedexDetalleOverlay')?.addEventListener('click', function(e) { if (e.target === this) cerrarPokedexDetalle(); });

    document.getElementById('pokedexFiltroTexto')?.addEventListener('input', renderizarPokedex);
    document.getElementById('pokedexFiltroTipo')?.addEventListener('change', renderizarPokedex);
    document.getElementById('pokedexFiltroCoste')?.addEventListener('change', renderizarPokedex);

    console.log("✅ Menú inicializado correctamente");
}

// ============================================================
// POKÉDEX (Restaurada)
// ============================================================
function abrirPokedex() {
    const overlay = document.getElementById('pokedexOverlay');
    if (!overlay) return;

    // Ocultar menú principal y selección
    const vistaMenu = document.getElementById('vistaMenu');
    const vistaSeleccion = document.getElementById('vistaSeleccion');
    if (vistaMenu) vistaMenu.classList.remove('activa');
    if (vistaSeleccion) vistaSeleccion.classList.remove('activa');

    // 🆕 FIX: conectar SIEMPRE los botones del header de la Pokédex
    conectarBotonesHeaderPokedex(overlay);

    // Mostrar Pokédex
    overlay.classList.add('visible');
    pokedexAbierta = true;
    renderizarPokedex();
    document.body.style.overflow = 'hidden';
}

function cerrarPokedex() {
    const overlay = document.getElementById('pokedexOverlay');
    if (!overlay) return;
    pokedexAbierta = false;
    overlay.classList.remove('visible');
    document.body.style.overflow = '';

    // Volver al menú principal
    const vistaMenu = document.getElementById('vistaMenu');
    const vistaSeleccion = document.getElementById('vistaSeleccion');
    if (vistaMenu) vistaMenu.classList.add('activa');
    if (vistaSeleccion) vistaSeleccion.classList.remove('activa');
}

function normalizarTexto(texto) {
    if (!texto) return '';
    return texto.normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
}

function renderizarPokedex() {
    const grid = document.getElementById('pokedexGrid');
    const contador = document.getElementById('pokedexContador');
    const filtroTexto = document.getElementById('pokedexFiltroTexto');
    const filtroTipo = document.getElementById('pokedexFiltroTipo');
    const filtroCoste = document.getElementById('pokedexFiltroCoste');

    if (!grid) return;

    const texto = filtroTexto ? filtroTexto.value.toLowerCase() : '';
    const tipoSeleccionado = filtroTipo ? filtroTipo.value : 'todos';
    const costeSeleccionado = filtroCoste ? filtroCoste.value : 'todos';

    let pokemons = (typeof POKEMONS !== 'undefined') ? [...POKEMONS] : [];

    if (pokemons.length === 0) {
        grid.innerHTML = `<div class="pokedex-vacio">⚠️ Los datos de Pokémon no están disponibles</div>`;
        return;
    }

    const tipoNormalizado = normalizarTexto(tipoSeleccionado);

    pokemons = pokemons.filter(p => {
        if (texto && !p.nombre.toLowerCase().includes(texto)) return false;
        if (tipoSeleccionado !== 'todos') {
            let coincide = false;
            if (p.tipos && Array.isArray(p.tipos)) {
                for (let t of p.tipos) if (normalizarTexto(t) === tipoNormalizado) { coincide = true; break; }
            }
            if (!coincide && p.clase && normalizarTexto(p.clase) === tipoNormalizado) coincide = true;
            if (!coincide) return false;
        }
        if (costeSeleccionado !== 'todos' && p.coste !== parseInt(costeSeleccionado)) return false;
        return true;
    });

    if (pokemons.length === 0) {
        grid.innerHTML = `<div class="pokedex-vacio">🔍 No se encontraron Pokémon con esos filtros</div>`;
        if (contador) contador.textContent = '0 Pokémon';
        return;
    }

    pokemons.sort((a, b) => {
        if (a.coste !== b.coste) return a.coste - b.coste;
        return a.nombre.localeCompare(b.nombre);
    });

    if (contador) contador.textContent = `${pokemons.length} Pokémon`;
    grid.innerHTML = '';

    pokemons.forEach(p => {
        const card = document.createElement('div');
        const coste = p.coste || 1;
        card.className = `pokedex-card cost-${coste}`;

        const spriteUrl = typeof getSpriteUrl === 'function' ? getSpriteUrl(p.spriteId, p.nombre) : '';
        const escalaSprite = typeof getSpriteScale === 'function' ? getSpriteScale(p.spriteId) : 1;
        const offsetXSprite = typeof getSpriteOffsetX === 'function' ? getSpriteOffsetX(p.spriteId) : '0px';

        let tiposHtml = '';
        if (p.tipos) {
            tiposHtml = p.tipos.map(t => {
                const icon = typeof getIconoTipo === 'function' ? getIconoTipo(t) : t;
                return `<span class="pokedex-tipo-icon" title="${t}">${icon}</span>`;
            }).join('');
        }
        if (p.clase) {
            const icon = typeof getIconoClase === 'function' ? getIconoClase(p.clase) : p.clase;
            tiposHtml += `<span class="pokedex-tipo-icon" title="${p.clase}">${icon}</span>`;
        }

        const costeHtml = `
            <div class="pokedex-card-coste">
                <img src="assets/icons/moneda.png" alt="💰" draggable="false">
                ${coste}
            </div>
        `;

        const estrellasHtml = typeof getEstrellasUrl === 'function'
            ? `<img class="pokedex-card-stars" src="${getEstrellasUrl(1)}" alt="1★" draggable="false">`
            : '';

        let evolucionHtml = '';
        if (p.evolucion) evolucionHtml = `<div class="pokedex-card-evolucion">➜ ${p.evolucion}</div>`;

        card.innerHTML = `
            <div class="pokedex-card-tipos">${tiposHtml}</div>
            ${costeHtml}
            <img class="pokedex-card-sprite" src="${spriteUrl}" alt="${p.nombre}" draggable="false" style="--sprite-scale: ${escalaSprite}; --sprite-offset-x: ${offsetXSprite}" onerror="this.style.display='none';">
            <div class="pokedex-card-nombre">${p.nombre}</div>
            ${estrellasHtml}
            ${evolucionHtml}
        `;

        card.title = `${p.nombre} (Coste ${coste})`;
        card.addEventListener('click', function () {
            abrirPokedexDetalle(p);
            if (typeof playButtonSound === 'function') playButtonSound();
        });

        grid.appendChild(card);
    });
}

function cerrarPokedexDetalle() {
    const overlay = document.getElementById('pokedexDetalleOverlay');
    if (overlay) overlay.classList.remove('visible');
    pokedexDetalleAbierto = false;
}

function abrirPokedexDetalle(pokemon) {
    if (!pokemon) return;
    const overlay = document.getElementById('pokedexDetalleOverlay');
    const body = document.getElementById('pokedexDetalleBody');
    if (!overlay || !body) return;

    let formaBase = pokemon;
    if (typeof TODOS_POKEMONS !== 'undefined') {
        let iteraciones = 0;
        while (iteraciones < 10) {
            iteraciones++;
            let padre = TODOS_POKEMONS.find(p => p.evolucion === formaBase.nombre);
            if (!padre) break;
            formaBase = padre;
        }
    }
    body.innerHTML = construirPokedexDetalleHtml(formaBase, 1);
    overlay.classList.add('visible');
    pokedexDetalleAbierto = true;
    engacharEventosDetalle(formaBase);
}

function engacharEventosDetalle(pokemonBase) {
    const body = document.getElementById('pokedexDetalleBody');
    if (!body) return;
    body.querySelectorAll('.pokedex-detalle-star-btn').forEach(btn => {
        btn.addEventListener('click', function () {
            const nivel = parseInt(this.dataset.nivel);
            if (isNaN(nivel)) return;
            const base = window._pokedexDetalleBase || pokemonBase;
            body.innerHTML = construirPokedexDetalleHtml(base, nivel);
            engacharEventosDetalle(base);
            if (typeof playButtonSound === 'function') playButtonSound();
        });
    });
}

function construirPokedexDetalleHtml(p, nivelSeleccionado = 1) {
    function resolverFormaParaNivel(formaBase, nivel) {
        if (!formaBase) return formaBase;
        if (nivel <= 1) return formaBase;
        let actual = formaBase;
        for (let i = 1; i < nivel; i++) {
            if (!actual.evolucion) break;
            const siguiente = (typeof getPokemonPorNombre === 'function')
                ? getPokemonPorNombre(actual.evolucion)
                : (typeof TODOS_POKEMONS !== 'undefined' ? TODOS_POKEMONS.find(x => x.nombre === actual.evolucion) : null);
            if (!siguiente) break;
            actual = siguiente;
        }
        return actual;
    }

    const formaMostrada = resolverFormaParaNivel(p, nivelSeleccionado);
    const coste = formaMostrada.coste || p.coste || 1;
    const nivel = nivelSeleccionado;

    const spriteId = formaMostrada.spriteId || formaMostrada.id;
    const spriteUrl = typeof getSpriteUrl === 'function' ? getSpriteUrl(spriteId, formaMostrada.nombre) : '';

    function getStatValue(stat, nivel) {
        if (stat === null || stat === undefined) return 0;
        if (Array.isArray(stat)) {
            const idx = Math.min(nivel - 1, stat.length - 1);
            const val = stat[idx];
            return (typeof val === 'number' && !isNaN(val)) ? val : 0;
        }
        if (typeof stat === 'object') {
            if (stat[nivel] !== undefined) return stat[nivel];
            const keys = Object.keys(stat).map(Number).sort((a, b) => a - b);
            for (let k of keys) { if (k >= nivel) return stat[k]; }
            return stat[keys[keys.length - 1]] || 0;
        }
        return (typeof stat === 'number' && !isNaN(stat)) ? stat : 0;
    }

    const hp = getStatValue(formaMostrada.hp, nivel);
    const ataque = getStatValue(formaMostrada.ataque, nivel);
    const spAttack = getStatValue(formaMostrada.spAttack, nivel);
    const defensa = formaMostrada.defense || 0;
    const spDefensa = formaMostrada.spDefense || 0;
    const velocidad = formaMostrada.attackSpeed || 0.8;

    let tiposHtml = '';
    if (formaMostrada.tipos) {
        tiposHtml = formaMostrada.tipos.map(t => {
            const icon = typeof getIconoTipo === 'function' ? getIconoTipo(t) : t;
            return `<div class="pokedex-detalle-badge-tipo">${icon} ${t}</div>`;
        }).join('');
    }

    let claseHtml = '';
    if (formaMostrada.clase) {
        const icon = typeof getIconoClase === 'function' ? getIconoClase(formaMostrada.clase) : formaMostrada.clase;
        claseHtml = `<div class="pokedex-detalle-badge-clase">${icon} ${formaMostrada.clase}</div>`;
    }

    let evolucionHtml = '';
    if (formaMostrada.evolucion) evolucionHtml = `<div class="pokedex-detalle-evolucion">🔄 Evoluciona a ${formaMostrada.evolucion}</div>`;
    else evolucionHtml = `<div class="pokedex-detalle-evolucion" style="color:#6b8aaa;border-color:rgba(107,138,170,0.3);">✦ Forma final</div>`;

    let starsSelectorHtml = `<div class="pokedex-detalle-stars-selector"><span class="pokedex-detalle-stars-label">Nivel</span>`;
    [1, 2, 3].forEach(n => {
        const activo = (n === nivel) ? 'active' : '';
        const estrellasUrl = typeof getEstrellasUrl === 'function' ? getEstrellasUrl(n) : '';
        starsSelectorHtml += `
            <button class="pokedex-detalle-star-btn ${activo}" data-nivel="${n}">
                ${estrellasUrl ? `<img src="${estrellasUrl}" alt="${n}★" draggable="false">` : ''}
                ${n}★
            </button>
        `;
    });
    starsSelectorHtml += `</div>`;

        const movimientos = typeof getMovimientosPokemon === 'function' ? getMovimientosPokemon(formaMostrada.nombre) : [];
    let movPrincipal = movimientos[0] || null;
    let movSecundario = (typeof MOVIMIENTOS_SECUNDARIOS !== 'undefined' && MOVIMIENTOS_SECUNDARIOS[formaMostrada.nombre]) ? MOVIMIENTOS_SECUNDARIOS[formaMostrada.nombre] : null;
    let movimientosHtml = '';

    if (movPrincipal) {
        const iconoHtml = typeof getIconoMovimientoHtml === 'function' ? getIconoMovimientoHtml(movPrincipal.iconoKey || movPrincipal.nombre, 36) : '⚔️';
        const tipoIcon = typeof getIconoTipo === 'function' ? getIconoTipo(movPrincipal.tipo) : '';

        // 🆕 Descripción del movimiento
        const nombreLimpio = typeof limpiarNombreMovimiento === 'function' ? limpiarNombreMovimiento(movPrincipal.nombre) : movPrincipal.nombre;
        const descData = typeof getDescripcionMovimiento === 'function' ? getDescripcionMovimiento(nombreLimpio, movPrincipal.iconoKey) : null;
        const descripcionHtml = descData && descData.descripcion
            ? `<div class="mov-desc">${descData.descripcion}</div>`
            : `<div class="mov-desc mov-desc-vacia">Sin descripción disponible.</div>`;
        const alcanceHtml = descData && descData.alcance
            ? `<div class="mov-alcance">📏 ${descData.alcance}</div>`
            : '';

        movimientosHtml += `
            <div class="pokedex-detalle-movimiento principal" data-mov-nombre="${movPrincipal.nombre}" data-mov-id="${movPrincipal.iconoKey || movPrincipal.nombre}">
                <div class="mov-icono">${iconoHtml}</div>
                <div class="mov-info">
                    <div class="mov-nombre">${movPrincipal.nombre}</div>
                    <div class="mov-tipo">${tipoIcon} ${movPrincipal.tipo || ''}</div>
                    ${descripcionHtml}
                    ${alcanceHtml}
                </div>
                <div class="mov-badge">PRINCIPAL</div>
            </div>
        `;
    }
    if (movSecundario) {
        const iconoHtml = typeof getIconoMovimientoHtml === 'function' ? getIconoMovimientoHtml(movSecundario.iconoKey || movSecundario.nombre, 36) : '⚔️';
        const tipoIcon = typeof getIconoTipo === 'function' ? getIconoTipo(movSecundario.tipo) : '';

        // 🆕 Descripción del movimiento
        const nombreLimpio = typeof limpiarNombreMovimiento === 'function' ? limpiarNombreMovimiento(movSecundario.nombre) : movSecundario.nombre;
        const descData = typeof getDescripcionMovimiento === 'function' ? getDescripcionMovimiento(nombreLimpio, movSecundario.iconoKey) : null;
        const descripcionHtml = descData && descData.descripcion
            ? `<div class="mov-desc">${descData.descripcion}</div>`
            : `<div class="mov-desc mov-desc-vacia">Sin descripción disponible.</div>`;
        const alcanceHtml = descData && descData.alcance
            ? `<div class="mov-alcance">📏 ${descData.alcance}</div>`
            : '';

        movimientosHtml += `
            <div class="pokedex-detalle-movimiento secundario" data-mov-nombre="${movSecundario.nombre}" data-mov-id="${movSecundario.iconoKey || movSecundario.nombre}">
                <div class="mov-icono">${iconoHtml}</div>
                <div class="mov-info">
                    <div class="mov-nombre">${movSecundario.nombre}</div>
                    <div class="mov-tipo">${tipoIcon} ${movSecundario.tipo || ''}</div>
                    ${descripcionHtml}
                    ${alcanceHtml}
                </div>
                <div class="mov-badge">2★</div>
            </div>
        `;
    }
    if (!movimientosHtml) movimientosHtml = `<div class="pokedex-vacio" style="grid-column:1/-1;">Sin movimientos registrados</div>`;

    const ulti = (typeof ULTIS_POKEMON !== 'undefined' && ULTIS_POKEMON[formaMostrada.nombre]) ? ULTIS_POKEMON[formaMostrada.nombre] : null;
    let ultiHtml = '';
    if (ulti) {
        const iconoUlti = typeof getIconoMovimientoHtml === 'function' ? getIconoMovimientoHtml(ulti.iconoKey || ulti.nombre, 48) : '⚡';
        let metaHtml = '';
        if (ulti.carga) metaHtml += `<span class="item">⚡ ${ulti.carga} ataques</span>`;
        if (ulti.alcance) metaHtml += `<span class="item">📏 ${ulti.alcance} casillas</span>`;
        if (ulti.esDeInicio) metaHtml += `<span class="item">🚀 Al inicio</span>`;
        ultiHtml = `<div class="pokedex-detalle-seccion-titulo">⚡ ULTIMATE</div><div class="pokedex-detalle-ulti"><div class="ulti-icono">${iconoUlti}</div><div class="ulti-info"><div class="ulti-nombre">${ulti.nombre}</div><div class="ulti-desc">${ulti.descripcion || 'Sin descripción'}</div><div class="ulti-meta">${metaHtml}</div></div></div>`;
    } else {
        ultiHtml = `<div class="pokedex-detalle-seccion-titulo">⚡ ULTIMATE</div><div class="pokedex-detalle-ulti" style="opacity:0.5;"><div class="ulti-icono">⚡</div><div class="ulti-info"><div class="ulti-nombre">Sin ulti registrada</div></div></div>`;
    }

    const estrellasUrl = typeof getEstrellasUrl === 'function' ? getEstrellasUrl(nivel) : '';
    const escalaSprite = typeof getSpriteScale === 'function' ? getSpriteScale(spriteId) : 1;
    const offsetXSprite = typeof getSpriteOffsetX === 'function' ? getSpriteOffsetX(spriteId) : '0px';

    return `
        <div class="pokedex-detalle-cabecera cost-${coste}">
            <div class="pokedex-detalle-sprite-wrapper"><img class="pokedex-detalle-sprite" src="${spriteUrl}" alt="${formaMostrada.nombre}" draggable="false" style="--sprite-scale: ${escalaSprite}; --sprite-offset-x: ${offsetXSprite}" onerror="this.style.display='none';"></div>
            <div class="pokedex-detalle-info">
                <div class="pokedex-detalle-nombre">${formaMostrada.nombre}</div>
                <div class="pokedex-detalle-subinfo"><span class="item"><img src="assets/icons/moneda.png" alt="💰" draggable="false"> Coste ${coste}</span>${estrellasUrl ? `<span class="item"><img src="${estrellasUrl}" alt="${nivel}★" draggable="false"> Nivel ${nivel}★</span>` : ''}</div>
                <div class="pokedex-detalle-badges">${tiposHtml}${claseHtml}</div>
            </div>
            ${evolucionHtml}
        </div>
        ${starsSelectorHtml}
        <div class="pokedex-detalle-stats">
            <div class="pokedex-detalle-stat"><span class="stat-label">❤️ HP</span><span class="stat-value">${Math.round(hp || 0)}</span></div>
            <div class="pokedex-detalle-stat"><span class="stat-label">⚔️ Ataque</span><span class="stat-value">${Math.round(ataque || 0)}</span></div>
            <div class="pokedex-detalle-stat"><span class="stat-label">🔮 Atq. Esp</span><span class="stat-value">${Math.round(spAttack || 0)}</span></div>
            <div class="pokedex-detalle-stat"><span class="stat-label">🛡️ Defensa</span><span class="stat-value">${Math.round(defensa)}</span></div>
            <div class="pokedex-detalle-stat"><span class="stat-label">🛡️ Def. Esp</span><span class="stat-value">${Math.round(spDefensa)}</span></div>
            <div class="pokedex-detalle-stat"><span class="stat-label">💨 Vel. Ataque</span><span class="stat-value">${Math.round(velocidad * 10) / 10}</span></div>
        </div>
        <div class="pokedex-detalle-seccion-titulo">🎯 MOVIMIENTOS</div>
        <div class="pokedex-detalle-movimientos">${movimientosHtml}</div>
        ${ultiHtml}
    `;
}

// ============================================================
// INICIALIZACIÓN
// ============================================================
if (document.readyState === 'complete' || document.readyState === 'interactive') {
    initMenu();
} else {
    document.addEventListener('DOMContentLoaded', function () {
        setTimeout(initMenu, 50);
    });
}

// ===== EXPONER GLOBALMENTE =====
window.RIVALES_INFO = RIVALES_INFO;
window.AVATARES_JUGADOR = AVATARES_JUGADOR;
window.abrirPokedex = abrirPokedex;
window.cerrarPokedex = cerrarPokedex;
window.renderizarPokedex = renderizarPokedex;
window.abrirPokedexDetalle = abrirPokedexDetalle;
window.cerrarPokedexDetalle = cerrarPokedexDetalle;
window.abrirSeleccion = abrirSeleccion;
window.volverAlMenu = volverAlMenu;
window.conectarBotonesHeaderPokedex = conectarBotonesHeaderPokedex;
;

/* ==================== js/ui/logrosPanel.js ==================== */
// ============================================================
// UI DE LOGROS + SELECTOR DE MAPAS
// ------------------------------------------------------------
// Panel de logros (🏆), selector de mapas (🗺️), toasts de
// desbloqueo y barra de XP del perfil.
// ============================================================
(function () {
    'use strict';

    if (!window.Logros) return;

    const $ = id => document.getElementById(id);
    let categoriaActiva = 'todos';
    let overlayLogros = null;
    let overlayMapas = null;

    // ------------------------------------------------------------
    // PERFIL / XP
    // ------------------------------------------------------------
    function actualizarPerfilUI() {
        const info = Logros.xpInfo();
        document.querySelectorAll('#menuPrincipal .profile-level').forEach(el => {
            el.textContent = 'Nv. ' + info.nivel;
        });
        const fill = document.querySelector('#menuPrincipal .profile-capsule .xp-bar-fill');
        if (fill) fill.style.width = info.pct.toFixed(1) + '%';
        const txt = document.querySelector('#menuPrincipal .profile-capsule .xp-text');
        if (txt) txt.textContent = Math.round(info.enNivel) + ' / ' + Math.round(info.necesario) + ' XP';
    }

    // ------------------------------------------------------------
    // MAPA SELECCIONADO
    // ------------------------------------------------------------
    function aplicarFondoMapa() {
        // El MENÚ PRINCIPAL conserva siempre su fondo original (Pradera).
        // El mapa elegido se aplica solo dentro de la partida, desde
        // aplicarTerrenoActual(); así un desbloqueo a mitad de combate
        // tampoco cambia el terreno de la arena.
        const juego = document.getElementById('juegoContainer');
        if (juego && getComputedStyle(juego).display !== 'none') return;

        // OJO: la variable se usa dentro de css/base.css, así que la URL
        // relativa debe ser ../assets (igual que el valor por defecto).
        // Con 'assets/...' el navegador la resolvía como /css/assets/... (404).
        document.body.style.setProperty('--terreno-actual', "url('../assets/backgrounds/terreno.webp')");
    }

    function actualizarMapSelector() {
        const id = Logros.mapaSeleccionado();
        const m = Logros.getMapa(id) || Logros.getMapa('auto');
        const thumb = $('mapSelectorThumb');
        if (thumb) thumb.style.backgroundImage = "url('assets/backgrounds/" + m.archivo + "')";
        const nombre = $('mapSelectorName');
        if (nombre) {
            const alt = Logros.mapaAlternando() && id !== 'auto';
            nombre.textContent = m.nombre + (alt ? ' 🔁' : '');
        }
        aplicarFondoMapa();
    }

    function refrescar() {
        actualizarPerfilUI();
        actualizarMapSelector();
        if (overlayLogros) renderLogrosPanel();
        if (overlayMapas) renderMapasPanel();
    }

    // ------------------------------------------------------------
    // HELPERS DE OVERLAY
    // ------------------------------------------------------------
    function crearOverlay(id) {
        let ov = document.getElementById(id);
        if (!ov) {
            ov = document.createElement('div');
            ov.id = id;
            ov.className = 'logros-overlay';
            document.body.appendChild(ov);
        }
        return ov;
    }

    function cerrar(ov) {
        if (!ov) return;
        ov.remove();
        if (ov === overlayLogros) overlayLogros = null;
        if (ov === overlayMapas) overlayMapas = null;
    }

    function esc(s) {
        return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({
            '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
        }[c]));
    }

    // ------------------------------------------------------------
    // PANEL DE LOGROS
    // ------------------------------------------------------------
    function abrirLogrosPanel() {
        if (overlayLogros) return;
        overlayLogros = crearOverlay('logrosOverlay');
        renderLogrosPanel();
        overlayLogros.addEventListener('click', e => {
            if (e.target === overlayLogros || e.target.closest('[data-cerrar-logros]')) {
                cerrar(overlayLogros);
                return;
            }
            const tab = e.target.closest('[data-cat]');
            if (tab) {
                categoriaActiva = tab.getAttribute('data-cat');
                renderLogrosPanel();
            }
        });
    }

    function renderLogrosPanel() {
        if (!overlayLogros) return;
        const total = Logros.LOGROS.length;
        const hechos = Logros.totalDesbloqueados();
        const pct = total > 0 ? (hechos / total) * 100 : 0;
        const info = Logros.xpInfo();

        const tabs = Logros.CATEGORIAS.map(c => {
            const activa = c.id === categoriaActiva ? ' activa' : '';
            return '<button type="button" class="logros-tab' + activa + '" data-cat="' + c.id + '">' +
                c.icono + ' ' + esc(c.nombre) + '</button>';
        }).join('');

        const lista = Logros.LOGROS.filter(l => categoriaActiva === 'todos' || l.cat === categoriaActiva);

        const cards = lista.map(l => {
            const ok = Logros.desbloqueado(l.id);
            const objetivo = Math.max(1, Number(l.objetivo) || 1);
            const valor = Math.min(objetivo, Logros.valor(l));
            const p = ok ? 100 : Math.min(100, (valor / objetivo) * 100);
            const mapa = l.mapa ? Logros.getMapa(l.mapa) : null;
            const progresoTexto = ok
                ? 'Conseguido'
                : (l.tipo === 'evento' ? 'Pendiente' : valor + ' / ' + objetivo);
            return '' +
                '<div class="logro-card ' + (ok ? 'desbloqueado' : 'bloqueado') + '">' +
                    '<div class="logro-card-top">' +
                        '<span class="logro-card-icon">' + l.icono + '</span>' +
                        '<span class="logro-card-nombre">' + esc(l.nombre) + '</span>' +
                        (ok ? '<span class="logro-card-check">✓</span>' : '') +
                    '</div>' +
                    '<div class="logro-card-desc">' + esc(l.desc) + '</div>' +
                    '<div class="logro-card-progress"><div class="logro-card-progress-fill" style="width:' + p.toFixed(1) + '%"></div></div>' +
                    '<div class="logro-card-foot">' +
                        '<span>' + progresoTexto + '</span>' +
                        '<span class="logro-card-xp">+' + l.xp + ' XP</span>' +
                    '</div>' +
                    (mapa ? '<div class="logro-card-mapa ' + (Logros.mapaDesbloqueado(mapa.id) ? 'ok' : '') + '">🗺️ ' + esc(mapa.nombre) + '</div>' : '') +
                '</div>';
        }).join('');

        overlayLogros.innerHTML = '' +
            '<div class="logros-modal">' +
                '<div class="logros-header">' +
                    '<div>' +
                        '<div class="logros-titulo">🏆 LOGROS</div>' +
                        '<div class="logros-subtitulo">' + hechos + ' / ' + total + ' desbloqueados · Nv. ' + info.nivel + '</div>' +
                    '</div>' +
                    '<button type="button" class="logros-cerrar" data-cerrar-logros aria-label="Cerrar">✕</button>' +
                '</div>' +
                '<div class="logros-barra"><div class="logros-barra-fill" style="width:' + pct.toFixed(1) + '%"></div></div>' +
                '<div class="logros-tabs">' + tabs + '</div>' +
                '<div class="logros-grid">' + cards + '</div>' +
            '</div>';
    }

    // ------------------------------------------------------------
    // SELECTOR DE MAPAS
    // ------------------------------------------------------------
    function abrirMapasPanel() {
        if (overlayMapas) return;
        overlayMapas = crearOverlay('mapasOverlay');
        renderMapasPanel();
        overlayMapas.addEventListener('click', e => {
            if (e.target === overlayMapas || e.target.closest('[data-cerrar-mapas]')) {
                cerrar(overlayMapas);
                return;
            }
            const card = e.target.closest('[data-mapa]');
            if (!card) return;
            const id = card.getAttribute('data-mapa');
            if (card.classList.contains('bloqueado')) return;
            if (Logros.seleccionarMapa(id)) {
                actualizarMapSelector();
                // Si estamos dentro de una partida, aplicar el cambio al instante.
                const juego = document.getElementById('juegoContainer');
                if (juego && getComputedStyle(juego).display !== 'none' && typeof aplicarTerrenoActual === 'function') {
                    aplicarTerrenoActual(window.rivalActual);
                }
                cerrar(overlayMapas);
            }
        });
    }

    function renderMapasPanel() {
        if (!overlayMapas) return;
        const sel = Logros.mapaSeleccionado();
        const cards = Logros.MAPAS.map(m => {
            const ok = Logros.mapaDesbloqueado(m.id);
            const activo = sel === m.id;
            const logro = m.logro ? Logros.getLogro(m.logro) : null;
            const objetivo = logro ? Math.max(1, Number(logro.objetivo) || 1) : 0;
            const valor = logro ? Math.min(objetivo, Logros.valor(logro)) : 0;
            const req = logro
                ? (ok ? '✓ Desbloqueado' : '🔒 ' + esc(logro.nombre) + ' · ' + valor + '/' + objetivo)
                : ((m.desc ? esc(m.desc) + ' · ' : '') + (m.siempreDesbloqueado ? '✓ Siempre disponible' : '✓ Disponible'));
            return '' +
                '<div class="mapa-card ' + (ok ? 'disponible' : 'bloqueado') + (activo ? ' seleccionado' : '') + '" data-mapa="' + m.id + '">' +
                    '<div class="mapa-thumb" style="background-image:url(\'assets/backgrounds/' + m.archivo + '\')">' +
                        (m.auto ? '<span class="mapa-emoji">🎲</span>' : '') +
                        (ok ? '' : '<span class="mapa-candado">🔒</span>') +
                        (activo ? '<span class="mapa-actual">✓</span>' : '') +
                    '</div>' +
                    '<div class="mapa-nombre">' + m.icono + ' ' + esc(m.nombre) + '</div>' +
                    '<div class="mapa-req">' + req + '</div>' +
                '</div>';
        }).join('');

        const desbloqueados = Logros.MAPAS.filter(m => Logros.mapaDesbloqueado(m.id)).length;
        const esAuto = sel === 'auto';
        const alternar = Logros.mapaAlternando() && !esAuto;

        overlayMapas.innerHTML = '' +
            '<div class="logros-modal mapas-modal">' +
                '<div class="logros-header">' +
                    '<div>' +
                        '<div class="logros-titulo">🗺️ MAPAS</div>' +
                        '<div class="logros-subtitulo">' + desbloqueados + ' / ' + Logros.MAPAS.length + ' disponibles · Elige el escenario de tus partidas</div>' +
                    '</div>' +
                    '<button type="button" class="logros-cerrar" data-cerrar-mapas aria-label="Cerrar">✕</button>' +
                '</div>' +
                '<label class="mapa-alternar' + (esAuto ? ' deshabilitado' : '') + '" title="Tu mapa en las rondas impares; el del rival en las pares">' +
                    '<input type="checkbox" id="mapaAlternarToggle"' + (alternar ? ' checked' : '') + (esAuto ? ' disabled' : '') + '>' +
                    '<span class="mapa-alternar-txt">🔁 Alternar con el mapa del rival</span>' +
                    '<span class="mapa-alternar-hint">' + (esAuto ? 'Automático ya usa el del rival' : 'Tu mapa en rondas impares · rival en pares') + '</span>' +
                '</label>' +
                '<div class="mapas-grid">' + cards + '</div>' +
            '</div>';

        const toggle = document.getElementById('mapaAlternarToggle');
        if (toggle) {
            toggle.addEventListener('change', () => {
                Logros.setAlternarMapa(toggle.checked);
                const juego = document.getElementById('juegoContainer');
                if (juego && getComputedStyle(juego).display !== 'none' && typeof aplicarTerrenoActual === 'function') {
                    aplicarTerrenoActual(window.rivalActual);
                }
            });
        }
    }

    // ------------------------------------------------------------
    // TOASTS
    // ------------------------------------------------------------
    const colaToasts = [];
    let toastActivo = false;

    function encolarToast(logro) {
        colaToasts.push(logro);
        procesarToasts();
    }

    function procesarToasts() {
        if (toastActivo || colaToasts.length === 0) return;
        const logro = colaToasts.shift();
        toastActivo = true;

        const mapa = logro.mapa ? Logros.getMapa(logro.mapa) : null;
        const el = document.createElement('div');
        el.className = 'logro-toast';
        el.innerHTML = '' +
            '<div class="logro-toast-icono">' + logro.icono + '</div>' +
            '<div class="logro-toast-texto">' +
                '<div class="logro-toast-eyebrow">¡LOGRO DESBLOQUEADO!</div>' +
                '<div class="logro-toast-nombre">' + esc(logro.nombre) + '</div>' +
                '<div class="logro-toast-xp">+' + logro.xp + ' XP</div>' +
                (mapa ? '<div class="logro-toast-mapa">🗺️ Nuevo mapa: ' + esc(mapa.nombre) + '</div>' : '') +
            '</div>';
        document.body.appendChild(el);

        try { if (typeof playUISound === 'function') playUISound('levelup.mp3', 0.35); } catch (e) { }

        setTimeout(() => {
            if (el && el.parentNode) el.remove();
            toastActivo = false;
            setTimeout(procesarToasts, 250);
        }, 3400);
    }

    function onDesbloqueo(nuevos) {
        actualizarPerfilUI();
        actualizarMapSelector();
        if (overlayLogros) renderLogrosPanel();
        if (overlayMapas) renderMapasPanel();
        for (const l of nuevos) encolarToast(l);
    }

    // ------------------------------------------------------------
    // BOTONES / INIT
    // ------------------------------------------------------------
    function bind(id, fn) {
        const el = $(id);
        if (el && !el.__logrosBound) {
            el.__logrosBound = true;
            el.addEventListener('click', e => { e.preventDefault(); fn(); });
        }
    }

    function init() {
        if (!window.Logros) return;
        Logros.init();
        actualizarPerfilUI();
        actualizarMapSelector();

        bind('btnLogros', abrirLogrosPanel);
        bind('btnLogrosSeleccion', abrirLogrosPanel);
        bind('btnPerfilMenu', abrirLogrosPanel);
        bind('btnPerfilSeleccion', abrirLogrosPanel);
        bind('profileCapsuleBtn', abrirLogrosPanel);
        bind('btnElegirMapa', abrirMapasPanel);
        bind('mapSelectorBar', abrirMapasPanel);
        bind('btnMapaJuego', abrirMapasPanel);

        // Accesibilidad: Enter/Espacio en los elementos con role="button"
        ['mapSelectorBar', 'profileCapsuleBtn'].forEach(id => {
            const el = $(id);
            if (!el || el.__logrosKeyBound) return;
            el.__logrosKeyBound = true;
            el.addEventListener('keydown', e => {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    if (id === 'mapSelectorBar') abrirMapasPanel();
                    else abrirLogrosPanel();
                }
            });
        });

        document.addEventListener('keydown', e => {
            if (e.key !== 'Escape') return;
            if (overlayMapas) cerrar(overlayMapas);
            else if (overlayLogros) cerrar(overlayLogros);
        });
    }

    window.LogrosUI = {
        init,
        refrescar,
        onDesbloqueo,
        abrirLogrosPanel,
        abrirMapasPanel,
        actualizarPerfilUI,
        actualizarMapSelector,
        aplicarFondoMapa
    };

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();

;

/* ==================== js/ui/render.js ==================== */
// ============================================================
// UI - RENDERIZADO COMPLETO DEL JUEGO
// v8.7 - DOBLE CLICK PARA ABRIR CARTA
// ============================================================

const SPRITES_MIRAN_DERECHA = new Set([282, 150]);
function _spriteMiraDerecha(spriteId) { return SPRITES_MIRAN_DERECHA.has(Number(spriteId)); }
window.SPRITES_MIRAN_DERECHA = SPRITES_MIRAN_DERECHA;
window._spriteMiraDerecha = _spriteMiraDerecha;

function obtenerRangoAtaque(unidad) {
    if (!unidad || !unidad.pokemon) return 1;
    if (unidad.esZacian) return 1;
    if (typeof unidad.pokemon.rangoAtaque === 'number' && unidad.pokemon.rangoAtaque > 0) return unidad.pokemon.rangoAtaque;
    const movimientos = getMovimientosPokemon(unidad.pokemon.nombre);
    if (!movimientos || movimientos.length === 0) return 1;
    const movPrincipal = movimientos[0];
    const nombreLimpio = limpiarNombreMovimiento(movPrincipal.nombre);
    const info = getDescripcionMovimiento(nombreLimpio, movPrincipal.iconoKey);
    if (!info || !info.alcance) return 1;
    const match = String(info.alcance).match(/(\d+)/);
    if (!match) return 1;
    return parseInt(match[1], 10);
}

function calcularDistanciaCasillas(idxA, idxB) {
    const cols = 4;
    return Math.abs(Math.floor(idxA / cols) - Math.floor(idxB / cols)) + Math.abs((idxA % cols) - (idxB % cols));
}

function estaEnRango(idxA, idxB, rango) {
    const cols = 4;
    const df = Math.abs(Math.floor(idxA / cols) - Math.floor(idxB / cols));
    const dc = Math.abs((idxA % cols) - (idxB % cols));
    if (rango <= 1) return Math.max(df, dc) <= 1;
    return (df + dc) <= rango;
}

function calcularDistanciaEntreTableros(indiceJugador, indiceEnemigo) {
    const cols = 4;
    const filaJugador = Math.floor(indiceJugador / cols);
    const colJugadorLocal = indiceJugador % cols;
    const filaEnemigo = Math.floor(indiceEnemigo / cols);
    const colEnemigoLocal = indiceEnemigo % cols;
    const colGlobalJugador = colJugadorLocal;
    const colGlobalEnemigo = 4 + colEnemigoLocal;
    return Math.abs(colGlobalJugador - colGlobalEnemigo) + Math.abs(filaJugador - filaEnemigo);
}

function estaEnRangoEntreTableros(indiceJugador, indiceEnemigo, rango) {
    const cols = 4;
    const filaJugador = Math.floor(indiceJugador / cols);
    const colJugadorLocal = indiceJugador % cols;
    const filaEnemigo = Math.floor(indiceEnemigo / cols);
    const colEnemigoLocal = indiceEnemigo % cols;
    const colGlobalJugador = colJugadorLocal;
    const colGlobalEnemigo = 4 + colEnemigoLocal;
    const df = Math.abs(filaJugador - filaEnemigo);
    const dc = Math.abs(colGlobalJugador - colGlobalEnemigo);
    if (rango <= 1) return Math.max(df, dc) <= 1;
    return (df + dc) <= rango;
}

// ✨ HOVER: resaltar las casillas EXACTAMENTE igual que al arrastrar el Pokémon,
//    reutilizando la misma lógica de colores de dragDrop.js.
function resaltarRangoHover(tipo, indice) {
    if (typeof combatiendo !== 'undefined' && combatiendo) return;
    if (typeof window.estaArrastrando === 'function' && window.estaArrastrando()) return;
    let unidad = null;
    if (tipo === 'tablero') unidad = tablero[indice];
    else if (tipo === 'enemigo') unidad = enemyBoard[indice];
    if (!unidad) return;
    if (typeof window.aplicarColoresDeSeleccion === 'function') {
        window.aplicarColoresDeSeleccion(tipo, indice, unidad, null, true);
    }
}

function limpiarResaltadoRango() {
    if (typeof window.estaArrastrando === 'function' && window.estaArrastrando()) return;
    if (typeof window.limpiarColoresDeSeleccion === 'function') {
        window.limpiarColoresDeSeleccion();
    }
}

// ============================================================
// 🎯 TOOLTIP DE OBJETOS (hover)
// ============================================================
// Tooltip flotante único que muestra el nombre + descripción de cualquier
// objeto con `data-objeto-nombre` (objetos equipados y del baúl).
(function initTooltipObjetos() {
    if (document.getElementById('tooltipObjetoFlotante')) return;
    const tip = document.createElement('div');
    tip.id = 'tooltipObjetoFlotante';
    tip.style.cssText = 'position:fixed;z-index:100000;pointer-events:none;display:none;background:#1a2236;border:1px solid #fbbf24;border-radius:8px;padding:8px 12px;max-width:240px;box-shadow:0 8px 25px rgba(0,0,0,0.5);';
    document.body.appendChild(tip);

    function posicionar(e) {
        const pad = 14;
        let x = e.clientX + pad;
        let y = e.clientY + pad;
        const w = tip.offsetWidth || 160;
        const h = tip.offsetHeight || 60;
        if (x + w > window.innerWidth) x = e.clientX - w - pad;
        if (y + h > window.innerHeight) y = e.clientY - h - pad;
        tip.style.left = x + 'px';
        tip.style.top = y + 'px';
    }

    document.addEventListener('mouseover', function (e) {
        const el = e.target && e.target.closest ? e.target.closest('[data-objeto-nombre]') : null;
        if (!el || !window.OBJETOS) return;
        const nombre = el.getAttribute('data-objeto-nombre');
        const obj = window.OBJETOS[nombre];
        if (!obj) return;
        tip.innerHTML =
            `<div style="font-size:0.72rem;font-weight:700;color:#fbbf24;margin-bottom:3px;">${nombre}</div>` +
            `<div style="font-size:0.62rem;color:#93c5fd;line-height:1.4;">${obj.descripcion || ''}</div>` +
            (obj.requerido ? `<div style="font-size:0.58rem;color:#f87171;margin-top:3px;">🔒 Requiere: ${obj.requerido}</div>` : '');
        tip.style.display = 'block';
        posicionar(e);
    });

    document.addEventListener('mousemove', function (e) {
        if (tip.style.display === 'block') posicionar(e);
    });

    document.addEventListener('mouseout', function (e) {
        const el = e.target && e.target.closest ? e.target.closest('[data-objeto-nombre]') : null;
        if (el && e.relatedTarget && el.contains(e.relatedTarget)) return;
        tip.style.display = 'none';
    });
})();

function renderSpriteHtml(unidad, clasesExtra = '', ladoTablero = 'player') {
    const spriteId = unidad.spriteIdAlternativo || unidad.pokemon.spriteId;
    const esShiny = unidad.esShiny === true;
    const url = getSpriteUrl(spriteId, unidad.pokemon.nombre, esShiny);
    const urlFallbackShiny = getSpriteUrlFallback(spriteId, unidad.pokemon.nombre, true);
    const urlFallbackNormal = getSpriteUrlFallback(spriteId, unidad.pokemon.nombre, false);
    const urlFallback = getSpriteUrlOriginal(unidad);
    const escala = getSpriteScale(spriteId);
    const offsetX = getSpriteOffsetX(spriteId);
    const clases = `unit-sprite ${clasesExtra} ${esShiny ? 'shiny' : ''}`.trim();
    const miraDerecha = _spriteMiraDerecha(spriteId);
    let flip = ladoTablero === 'player' ? (miraDerecha ? 1 : -1) : (miraDerecha ? -1 : 1);
    // 👥 2P: con turno de J2 el tablero está espejado (J2 a la derecha),
    // así que invertimos la orientación del sprite para que mire al rival.
    if (window.modoDosJugadores && window.turnoJugador === 2) flip = -flip;

    // 🚫 FIX parpadeo: si ya conocemos el formato real del sprite (GIF o PNG),
    // emitimos la URL definitiva sin la cadena onerror que alternaba GIF→PNG en
    // cada re-render del tablero. Solo aplica a no-shiny (los shiny mantienen su
    // cadena de 4 pasos original para no romper el fallback shiny).
    const formato = (!esShiny && typeof formatoSpriteResuelto === 'function')
        ? formatoSpriteResuelto(spriteId, false)
        : null;

    let src = url;
    let onerrorAttr = '';

    if (formato === 'png') {
        // El sprite solo existe como PNG → URL directa, sin cadena de fallback.
        src = urlFallback;
    } else if (formato === 'gif') {
        // El sprite existe como GIF → URL directa, sin cadena de fallback.
        src = url;
    } else {
        // Formato aún no resuelto (o shiny) → mantener la cadena onerror original.
        const onerrorChain = esShiny
            ? `if(this.dataset.fb!=='1'){this.dataset.fb='1';this.src='${urlFallbackShiny}';}
               else if(this.dataset.fb!=='2'){this.dataset.fb='2';this.src='${getSpriteUrl(spriteId, unidad.pokemon.nombre, false)}';}
               else if(this.dataset.fb!=='3'){this.dataset.fb='3';this.src='${urlFallback}';}
               else{this.style.display='none';}`
            : `if(this.dataset.fb!=='1'){this.dataset.fb='1';this.src='${urlFallback}';}else{this.style.display='none';}`;
        onerrorAttr = ` onerror="${onerrorChain}"`;
    }

    return `<img decoding="async" class="${clases}" src="${src}" alt="${unidad.pokemon.nombre}${esShiny ? ' ✨' : ''}" draggable="false" style="--sprite-scale: ${escala}; --sprite-offset-x: ${offsetX}; --sprite-flip: ${flip}"${onerrorAttr}>`;
}

function renderEstrellasHtml(nivel) {
    if (!nivel || nivel < 1) return '';
    return `<span class="unit-stars-right"><img class="estrellas-img" src="${getEstrellasUrl(nivel)}" alt="${nivel}★" draggable="false"></span>`;
}

function renderTraitsHtml(pokemon) {
    if (pokemon && pokemon.id === 999) return '';
    let html = '';
    if (pokemon.tipos && pokemon.tipos.length > 0) html += pokemon.tipos.map(t => `<span class="trait-icon">${getIconoTipo(t)}</span>`).join('');
    if (pokemon.clase) html += `<span class="trait-icon">${getIconoClase(pokemon.clase)}</span>`;
    return html;
}

function renderBadgeFrontBack(unidad) { return ''; }
function renderBadgeInvasor(unidad, ladoTablero) { return ''; }

function frostStacksHtml(stacks) {
    let html = '';
    for (let i = 0; i < 6; i++) {
        html += `<span class="frost-dot${i < stacks ? ' filled' : ''}"></span>`;
    }
    return html;
}

function renderFrostStacks(unidad) {
    const stacks = (unidad && unidad.frostStacks) ? Math.min(unidad.frostStacks, 6) : 0;
    if (stacks <= 0) return '';
    return `<div class="frost-stacks">${frostStacksHtml(stacks)}</div>`;
}

function shockStacksHtml(stacks) {
    let html = '';
    for (let i = 0; i < 6; i++) {
        html += `<span class="shock-dot${i < stacks ? ' filled' : ''}"></span>`;
    }
    return html;
}

function renderShockStacks(unidad) {
    const stacks = (unidad && unidad.shockStacks) ? Math.min(unidad.shockStacks, 6) : 0;
    if (stacks <= 0) return '';
    return `<div class="shock-stacks">${shockStacksHtml(stacks)}</div>`;
}

function actualizarFrostStacksVisual(elemento, unidad) {
    if (!elemento || !unidad) return;
    const stacks = Math.min(unidad.frostStacks || 0, 6);
    let container = elemento.querySelector('.frost-stacks');
    if (stacks <= 0) { if (container) container.remove(); return; }
    if (!container) { container = document.createElement('div'); container.className = 'frost-stacks'; elemento.appendChild(container); }
    container.innerHTML = frostStacksHtml(stacks);
}

function actualizarShockStacksVisual(elemento, unidad) {
    if (!elemento || !unidad) return;
    const stacks = Math.min(unidad.shockStacks || 0, 6);
    let container = elemento.querySelector('.shock-stacks');
    if (stacks <= 0) { if (container) container.remove(); return; }
    if (!container) { container = document.createElement('div'); container.className = 'shock-stacks'; elemento.appendChild(container); }
    container.innerHTML = shockStacksHtml(stacks);
}

function renderHPBar(unidad) {
    const hpPercent = unidad.maxHp > 0 ? (unidad.hp / unidad.maxHp) * 100 : 0;
    const hpClamped = Math.max(0, Math.min(100, hpPercent));
    let hpFillClass = 'hp-fill';
    if (hpPercent > 50) hpFillClass = 'hp-fill';
    else if (hpPercent > 25) hpFillClass = 'hp-fill medium';
    else if (hpPercent > 10) hpFillClass = 'hp-fill low';
    else hpFillClass = 'hp-fill critical';

    let escudoHtml = '';
    if (unidad.escudoActual > 0 && unidad.maxHp > 0) {
        const escudoPercent = Math.min(100 - hpPercent, (unidad.escudoActual / unidad.maxHp) * 100);
        if (escudoPercent > 0) escudoHtml = `<div class="hp-shield" style="left:${hpPercent}%;width:${escudoPercent}%;"></div>`;
    }

    const numSegments = Math.min(Math.max(4, Math.ceil(unidad.maxHp / 100)), 20);
    let segmentsHtml = '';
    for (let s = 0; s < numSegments; s++) segmentsHtml += `<div class="segment"></div>`;

    const teamClass = unidad.equipo === 'player' ? 'team-player' : 'team-enemy';
    return `<div class="unit-hp-container"><div class="unit-hp-bar tft-style ${teamClass}"><div class="${hpFillClass}" style="width:${hpClamped}%;"></div>${escudoHtml}<div class="hp-segments">${segmentsHtml}</div></div></div>`;
}

function renderEnergyBar(unidad) {
    const energyPercent = unidad.energyGauge > 0 ? (unidad.energy / unidad.energyGauge) * 100 : 0;
    const clamped = Math.max(0, Math.min(100, energyPercent));
    return `<div class="energy-bar"><div class="energy-fill" style="width:${clamped}%;"></div></div>`;
}

function renderUltiBar(unidad) {
    if (!unidad.tieneDiscoUlti) return '';
    const ultiData = window.ULTIS_POKEMON && window.ULTIS_POKEMON[unidad.pokemon.nombre];
    if (!ultiData || !ultiData.carga) return '';
    const cargaActual = unidad.ultiCarga || 0;
    const cargaMax = ultiData.carga;
    const porcentaje = Math.min(100, (cargaActual / cargaMax) * 100);
    const ultiLista = unidad.ultiLista || false;
    const colorFondo = ultiLista ? 'linear-gradient(90deg, #fbbf24, #fde68a, #fbbf24)' : 'linear-gradient(90deg, #facc15, #fde047, #facc15)';
    const glow = ultiLista ? 'box-shadow: 0 0 12px rgba(251, 191, 36, 0.9), 0 0 20px rgba(251, 191, 36, 0.5); animation: pulseUlti 1s ease-in-out infinite;' : '';
    return `<div class="ulti-bar" title="ULTI: ${ultiData.nombre} (${cargaActual}/${cargaMax})"><div class="ulti-fill" style="width:${porcentaje}%; background:${colorFondo}; ${glow}"></div></div>`;
}

function _renderSlotObjeto(obj, idx, data, tipoUnidad, indiceUnidad, claseSpan, claseImg, tamano, tamanoImg, esDisco) {
    const iconoHtml = (data.emoji && data.emoji.includes('.png'))
        ? `<img src="${data.emoji}" class="${claseImg}" alt="${obj}" draggable="false" style="width:${tamanoImg}px;height:${tamanoImg}px;object-fit:contain;display:block;">`
        : `<span style="font-size:${esDisco ? '0.9' : '0.7'}rem;">${data.emoji || (esDisco ? '💿' : '📦')}</span>`;
    const onclickStr = `event.stopPropagation(); if(!combatiendo && typeof desequiparObjeto === 'function') desequiparObjeto('${tipoUnidad}', ${indiceUnidad}, ${idx})`;
    const borderColor = esDisco ? 'rgba(251,191,36,0.6)' : 'rgba(251,191,36,0.3)';
    const bg = esDisco ? 'rgba(251,191,36,0.2)' : 'rgba(0,0,0,0.5)';
    return `<span class="${claseSpan}" data-objeto-index="${idx}" data-objeto-nombre="${obj}" onclick="${onclickStr}" style="display:inline-flex;align-items:center;justify-content:center;width:${tamano}px;height:${tamano}px;background:${bg};border:2px solid ${borderColor};border-radius:6px;cursor:grab;padding:2px;box-sizing:border-box;">${iconoHtml}</span>`;
}

function renderObjetosEquipados(unidad, tipoUnidad, indiceUnidad, esBanquillo = false) {
    if (unidad.esZacian && esBanquillo) return '';
    const tamano = esBanquillo ? 22 : 26;
    const tamanoImg = esBanquillo ? 16 : 20;
    const claseSpan = esBanquillo ? 'objeto-equipado-banquillo' : 'objeto-equipado-tablero';
    const claseImg = esBanquillo ? 'objeto-icon-banquillo' : 'objeto-icon-tablero';
    const normales = [];
    let discoIdx = -1;
    if (unidad.objetos) {
        unidad.objetos.forEach((obj, idx) => {
            const data = OBJETOS[obj];
            if (!data) return;
            if (data.efecto && data.efecto.esDiscoUlti) discoIdx = idx;
            else normales.push({ obj, idx, data });
        });
    }
    const slots = [];
    for (let i = 0; i < 2; i++) {
        if (i < normales.length) {
            const { obj, idx, data } = normales[i];
            slots.push(_renderSlotObjeto(obj, idx, data, tipoUnidad, indiceUnidad, claseSpan, claseImg, tamano, tamanoImg, false));
        } else {
            slots.push(`<span class="${claseSpan} vacio" data-objeto-index="-1" data-objeto-nombre="" style="display:inline-flex;align-items:center;justify-content:center;width:${tamano}px;height:${tamano}px;background:rgba(0,0,0,0.15);border:2px solid rgba(42,58,90,0.3);border-radius:6px;font-size:0.5rem;color:#4a6a8a;box-sizing:border-box;">▢</span>`);
        }
    }
    if (discoIdx !== -1) {
        const obj = unidad.objetos[discoIdx];
        const data = OBJETOS[obj];
        if (data) slots.push(_renderSlotObjeto(obj, discoIdx, data, tipoUnidad, indiceUnidad, claseSpan, claseImg, tamano, tamanoImg, true));
    } else {
        slots.push(`<span class="${claseSpan} vacio slot-ulti" data-objeto-index="-1" data-objeto-nombre="" title="Slot de ULTI (Disco Definitivo)" style="display:inline-flex;align-items:center;justify-content:center;width:${tamano}px;height:${tamano}px;background:rgba(0,0,0,0.25);border:2px dashed rgba(251,191,36,0.25);border-radius:6px;font-size:${esBanquillo ? '0.55' : '0.6'}rem;color:rgba(251,191,36,0.35);box-sizing:border-box;">💿</span>`);
    }
    return slots.join('');
}

function intentarEngancharDrag(cell, tipo, indice, unidad) {
    if (!unidad || typeof engancharDrag !== 'function' || typeof puedeArrastrar !== 'function' || !puedeArrastrar(tipo, indice)) return;
    engancharDrag(cell, tipo, indice);
}

function renderizarTableroJugador() {
    const grid = document.getElementById("playerBoard");
    if (!grid) return;
    grid.innerHTML = "";
    grid.style.gridTemplateColumns = "repeat(4, 1fr)";
    grid.style.maxWidth = "720px";

        for (let i = 0; i < tablero.length; i++) {
        const u = tablero[i];
        const cell = document.createElement('div');
        cell.className = 'board-cell';
        cell.dataset.tipo = 'tablero';
        cell.dataset.indice = i;
        cell.dataset.coord = getCoordenadaCasilla(i, 'player');

        if (u) {
            cell.classList.add('has-unit', 'team-player');
            if (u.esZacian) cell.classList.add('cost-5');
            else if (u.costeOriginal) cell.classList.add('cost-' + u.costeOriginal);
            if (u.poisonStacks && u.poisonStacks.length > 0) cell.classList.add('casilla-veneno');
            if (u._quemado || u.burnDamage > 0) cell.classList.add('casilla-quemadura');

            let spriteClases = '';
            if (u.frozen) spriteClases += ' frozen';
            if (u._quemado || u.burnDamage > 0) spriteClases += ' burn';

            const tieneDiscoEnObjetos = u.objetos && u.objetos.some(o => { const obj = window.OBJETOS && window.OBJETOS[o]; return obj && obj.efecto && obj.efecto.esDiscoUlti; });
            if (tieneDiscoEnObjetos !== u.tieneDiscoUlti) {
                u.tieneDiscoUlti = tieneDiscoEnObjetos;
                if (!tieneDiscoEnObjetos) { u.ultiCarga = 0; u.ultiLista = false; u._ultiAvisada = false; }
            }

            const objetosHtml = renderObjetosEquipados(u, 'tablero', i, false);
            const objetosContenedor = objetosHtml ? `<div class="objetos-equipados" style="display:flex;gap:4px;justify-content:center;align-items:center;position:relative;width:100%;padding:2px 4px;z-index:3;min-height:26px;margin-top:6px;">${objetosHtml}</div>` : '';

                        cell.innerHTML = `
                ${renderSpriteHtml(u, spriteClases, 'player')}
                <span class="unit-name ${u.esShiny ? 'shiny-name' : ''}">${u.pokemon.nombre}</span>
                <div class="unit-traits-left">${renderTraitsHtml(u.pokemon)}</div>
                ${renderHPBar(u)}
                ${renderEnergyBar(u)}
                ${renderUltiBar(u)}
                ${objetosContenedor}
                ${renderEstrellasHtml(u.nivel)}
                ${renderBadgeFrontBack(u)}
                ${renderFrostStacks(u)}
                ${renderShockStacks(u)}
                ${renderEscudoRoto(u)}
                ${renderIconoLlamarada(u)}
            `;

            // 🆕 DOBLE CLICK para abrir la carta (evita conflictos con drag)
            cell.addEventListener('dblclick', function (e) {
                e.stopPropagation();
                if (combatiendo) return;
                if (e.target.closest('.objetos-equipados')) return;
                if (objetoSeleccionado) { equiparObjetoDesdeBaul(objetoSeleccionado.index, 'tablero', i); return; }
                if (tablero[i]) abrirCarta('tablero', i);
            });

            // ✨ HOVER: resaltar el rango de ataque al pasar el ratón
            cell.addEventListener('mouseenter', function () { resaltarRangoHover('tablero', i); });
            cell.addEventListener('mouseleave', function () { limpiarResaltadoRango(); });
        } else {
            cell.innerHTML = '<span style="font-size:1.2rem;opacity:0.15;">▢</span>';
            cell.style.cssText = 'font-size:0.8rem;color:#4a6a8a;background:transparent;border:2px solid #2a3a5a;box-shadow:none;';
            cell.addEventListener('click', function (e) { e.stopPropagation(); });
        }
                grid.appendChild(cell);
        intentarEngancharDrag(cell, 'tablero', i, u);

        // 🆕 FIX: volver a aplicar la zona activa si existe
        if (typeof _zonaActivaEn === 'function') {
            const coords = coordsDesdeIndice(i, 'player');
            const zona = _zonaActivaEn(coords._filaGlobal, coords._colGlobal);
            if (zona) {
                cell.classList.add('mov-zone-marcada', zona.clase);
                if (zona.parpadeo) {
                    cell.classList.add('mov-zone-parpadeo');
                }
            }
        }
    }
}

