/* ==================== js/ui/panelDatosCombate.js ==================== */
// ============================================================
// PANEL DE DATOS DE COMBATE - MODAL CENTRADO
// v4.1 - FIX: Ignorar valores de daño absurdos (>100.000) para
//        que las barras del jugador se vean correctamente.
//        FIX: Mínimo visual del 2% para que las barras no
//        desaparezcan cuando la diferencia de daño es enorme.
// ============================================================
// - Lee stats EN VIVO (window.statsCombateEnVivo) durante el combate.
// - Fallback a stats FINALES (window.postCombateData) al terminar.
// - Auto-refresh cada 500ms mientras el panel está abierto.
// - Cierra tienda y carta si están abiertas al abrir panel.
// ============================================================

let panelDatosCombateAbierto = false;
let panelDatosCombateFiltro = 'damage';
let panelDatosIntervalId = null;

// ============================================================
// ABRIR / CERRAR
// ============================================================

function abrirPanelDatosCombate() {
    const panel = document.getElementById('panelDatosCombate');
    if (!panel) {
        console.error('❌ #panelDatosCombate no existe en el DOM');
        return;
    }

    // Cerrar tienda si está abierta
    try {
        if (typeof tiendaAbierta !== 'undefined' && tiendaAbierta) {
            if (typeof cerrarTienda === 'function') {
                cerrarTienda();
            }
        }
    } catch (e) {}

    // Cerrar carta si está abierta
    try {
        if (typeof cartaAbierta !== 'undefined' && cartaAbierta) {
            if (typeof cerrarCarta === 'function') {
                cerrarCarta();
            }
        }
    } catch (e) {}

    panelDatosCombateAbierto = true;
    window.panelDatosCombateAbierto = true;

    // 🆕 Modal centrado: click fuera cierra
    panel.onclick = function(e) {
        if (e.target === panel) {
            cerrarPanelDatosCombate();
        }
    };

    panel.style.display = 'flex';
    panel.style.animation = 'none';
    void panel.offsetWidth;

    renderizarPanelDatosCombate();
    iniciarAutoRefreshPanelDatos();

    if (typeof playButtonSound === 'function') playButtonSound();
}

function cerrarPanelDatosCombate() {
    const panel = document.getElementById('panelDatosCombate');
    if (!panel) return;

    panelDatosCombateAbierto = false;
    window.panelDatosCombateAbierto = false;
    panel.style.display = 'none';
    panel.onclick = null;

    detenerAutoRefreshPanelDatos();
}

function togglePanelDatosCombate() {
    if (panelDatosCombateAbierto) {
        cerrarPanelDatosCombate();
    } else {
        abrirPanelDatosCombate();
    }
}

// ============================================================
// AUTO-REFRESH
// ============================================================

function iniciarAutoRefreshPanelDatos() {
    if (panelDatosIntervalId) return;
    panelDatosIntervalId = setInterval(() => {
        if (panelDatosCombateAbierto) {
            renderizarPanelDatosCombate();
        } else {
            clearInterval(panelDatosIntervalId);
            panelDatosIntervalId = null;
        }
    }, 500);
}

function detenerAutoRefreshPanelDatos() {
    if (panelDatosIntervalId) {
        clearInterval(panelDatosIntervalId);
        panelDatosIntervalId = null;
    }
}

// ============================================================
// RENDERIZAR
// ============================================================

function renderizarPanelDatosCombate() {
    let data = null;

    // Prioridad: stats en vivo durante el combate
    if (window.statsCombateEnVivo && window.statsCombateEnVivo.activo) {
        data = {
            statsJugadores: window.statsCombateEnVivo.jugadores || [],
            statsRivales: window.statsCombateEnVivo.rivales || []
        };
    }
    // Fallback: stats finales
    else if (window.postCombateData) {
        data = window.postCombateData;
    }

    if (!data) {
        const listaJ = document.getElementById('panelDatosListaJugador');
        const listaE = document.getElementById('panelDatosListaEnemigo');
        if (listaJ) listaJ.innerHTML = '<div style="text-align:center;color:#6b8aaa;font-size:0.7rem;padding:20px 0;">Sin datos todavía</div>';
        if (listaE) listaE.innerHTML = '<div style="text-align:center;color:#6b8aaa;font-size:0.7rem;padding:20px 0;">Sin datos todavía</div>';
        const totalJEl = document.getElementById('panelDatosTotalJugador');
        const totalEEl = document.getElementById('panelDatosTotalEnemigo');
        if (totalJEl) totalJEl.textContent = 'Total: 0';
        if (totalEEl) totalEEl.textContent = 'Total: 0';
        return;
    }

        // ===== Avatares + nombres =====
    // 🆕 FIX: si estamos en la SIGUIENTE ronda (ya hay postCombateData
    // pero el combate nuevo aún no ha empezado), mostramos el rival
    // ANTERIOR (el que acaba de pelear), no el nuevo.
    //
    // - Durante el combate: window.statsCombateEnVivo.activo === true
    //   → usar window.rivalActual (el rival en curso).
    // - Después del combate, antes del siguiente:
    //   → usar window.rivalAnterior (el rival que acaba de pelear).
    const enCombateActivo = !!(window.statsCombateEnVivo && window.statsCombateEnVivo.activo);
    const rivalActual = enCombateActivo
        ? window.rivalActual
        : (window.rivalAnterior || window.rivalActual);

    // 👥 En 2P se resuelven ambos lados (activo/inactivo) con nombre+avatar propios.
    let nombreMostrar = (typeof window.nombreJugador !== 'undefined' && window.nombreJugador)
        ? window.nombreJugador : "Entrenador";
    let avatarMostrar = (typeof window.avatarJugador !== 'undefined' && window.avatarJugador)
        ? window.avatarJugador : "rojo";
    let carpetaPlayer = 'jugador';

        let nombreEnemigo = rivalActual ? rivalActual.nombre : "Rival";
    let avatarEnemigo = rivalActual ? rivalActual.avatar : null;
    let carpetaEnemigo = 'rivales';

    // 🆕 Si es un monstruo PvE, no tiene avatar de rivales.
    if (rivalActual && rivalActual.esMonstruo) {
        avatarEnemigo = null;
        nombreEnemigo = rivalActual.nombre + ' (PvE)';
    }

    // 🌐 Online 1v1: el rival es el Jugador 2 (tu amigo), no la IA
    if (window._modoOnline && !(rivalActual && rivalActual.esMonstruo)) {
        nombreEnemigo = (window._amigo && window._amigo.name) ? window._amigo.name : 'Jugador 2';
        avatarEnemigo = (window._amigo && window._amigo.avatar) ? window._amigo.avatar : 'azul';
        carpetaEnemigo = 'jugador';
    }

    // 👥 2P: lados FIJOS — J1 siempre a la izquierda, J2 a la derecha
    // (independientemente de quién tenga el turno activo).
    let ladosFijos2P = false;
    if (window.modoDosJugadores) {
        const nombreJ1 = (window.nombreJugador || 'Jugador 1');
        const avatarJ1 = (window.avatarJugador || 'rojo');
        const nombreJ2 = (window.nombreJugador2 || 'Jugador 2');
        const avatarJ2 = (window.avatarJugador2 || 'azul');

        nombreMostrar = nombreJ1;
        avatarMostrar = avatarJ1;
        carpetaPlayer = 'jugador';

        nombreEnemigo = nombreJ2;
        avatarEnemigo = avatarJ2;
        carpetaEnemigo = 'jugador';

        // Los datos vienen de un combate concreto: si en ese combate el lado
        // "jugador" era J2 (quien abrió la ronda), los intercambiamos para que
        // J1 quede SIEMPRE a la izquierda y J2 a la derecha.
        ladosFijos2P = (window._ultimoCombateJugadorEsJ2 === true);
    }

    const nombreJugadorEl = document.getElementById('panelDatosNombreJugador');
    if (nombreJugadorEl) nombreJugadorEl.textContent = nombreMostrar;

    const nombreEnemigoEl = document.getElementById('panelDatosNombreEnemigo');
    if (nombreEnemigoEl) nombreEnemigoEl.textContent = nombreEnemigo;

    const avatarJugadorEl = document.getElementById('panelDatosAvatarJugador');
    if (avatarJugadorEl) {
        const srcJugador = `assets/avatars/${carpetaPlayer}/${avatarMostrar}.webp`;
        if (!avatarJugadorEl.querySelector('img')) {
            avatarJugadorEl.innerHTML = '';
            const img = document.createElement('img');
            img.src = srcJugador;
            img.alt = nombreMostrar;
            img.onerror = function () {
                this.style.display = 'none';
                avatarJugadorEl.textContent = '🧢';
            };
            avatarJugadorEl.appendChild(img);
        } else {
            const imgActual = avatarJugadorEl.querySelector('img');
            if (imgActual && !imgActual.src.includes(avatarMostrar)) {
                imgActual.src = srcJugador;
            }
        }
    }

    const avatarEnemigoEl = document.getElementById('panelDatosAvatarEnemigo');
    if (avatarEnemigoEl) {
        if (avatarEnemigo) {
            const srcEnemigo = `assets/avatars/${carpetaEnemigo}/${avatarEnemigo}.webp`;
            if (!avatarEnemigoEl.querySelector('img')) {
                avatarEnemigoEl.innerHTML = '';
                const img = document.createElement('img');
                img.src = srcEnemigo;
                img.alt = nombreEnemigo;
                img.onerror = function () {
                    this.style.display = 'none';
                    avatarEnemigoEl.textContent = '👤';
                };
                avatarEnemigoEl.appendChild(img);
            } else {
                const imgActual = avatarEnemigoEl.querySelector('img');
                if (imgActual && !imgActual.src.includes(avatarEnemigo)) {
                    imgActual.src = srcEnemigo;
                }
            }
        } else {
            avatarEnemigoEl.innerHTML = '';
            avatarEnemigoEl.textContent = '👤';
        }
    }

    // ===== Título del filtro =====
    const tituloEl = document.getElementById('panelDatosTituloFiltro');
    const titulos = {
        damage: 'Daño infligido',
        received: 'Daño recibido',
        heal: 'Curaciones'
    };
    if (tituloEl) tituloEl.textContent = titulos[panelDatosCombateFiltro] || '';

    // ===== Listas =====
    let statsJugadores = (data.statsJugadores || []).slice();
    let statsRivales = (data.statsRivales || []).slice();

    // 👥 2P con lados fijos: si J2 es el activo, espejamos los datos para que
    // coincidan con J1 (izquierda) / J2 (derecha).
    if (ladosFijos2P) {
        const tmp = statsJugadores;
        statsJugadores = statsRivales;
        statsRivales = tmp;
    }

    function ordenarPorFiltro(lista) {
        if (panelDatosCombateFiltro === 'damage') {
            lista.sort((a, b) => (b.damageDealt || 0) - (a.damageDealt || 0));
        } else if (panelDatosCombateFiltro === 'received') {
            lista.sort((a, b) => (b.damageTaken || 0) - (a.damageTaken || 0));
        } else if (panelDatosCombateFiltro === 'heal') {
            lista.sort((a, b) => (b.healingDone || 0) - (a.healingDone || 0));
        }
        return lista;
    }

    ordenarPorFiltro(statsJugadores);
    ordenarPorFiltro(statsRivales);

    const todos = [...statsJugadores, ...statsRivales];
    let maxValor = 1;
    
    // 🆕 FIX v4.1: Ignorar valores absurdos (>100.000) para calcular el máximo
    for (let s of todos) {
        let v = 0;
        if (panelDatosCombateFiltro === 'damage') v = s.damageDealt || 0;
        else if (panelDatosCombateFiltro === 'received') v = s.damageTaken || 0;
        else if (panelDatosCombateFiltro === 'heal') v = s.healingDone || 0;
        
        if (v > maxValor && v < 100000) {
            maxValor = v;
        }
    }

    renderizarListaPanel(statsJugadores, 'panelDatosListaJugador', maxValor);
    renderizarListaPanel(statsRivales, 'panelDatosListaEnemigo', maxValor);

    function sumaTotal(lista) {
        let total = 0;
        for (let s of lista) {
            if (panelDatosCombateFiltro === 'damage') total += (s.damageDealt || 0);
            else if (panelDatosCombateFiltro === 'received') total += (s.damageTaken || 0);
            else if (panelDatosCombateFiltro === 'heal') total += (s.healingDone || 0);
        }
        return Math.round(total);
    }

    const totalJEl = document.getElementById('panelDatosTotalJugador');
    const totalEEl = document.getElementById('panelDatosTotalEnemigo');
    if (totalJEl) totalJEl.textContent = `Total: ${sumaTotal(statsJugadores)}`;
    if (totalEEl) totalEEl.textContent = `Total: ${sumaTotal(statsRivales)}`;
}

// ============================================================
// RENDERIZAR LISTA
// ============================================================

function renderizarListaPanel(lista, contenedorId, maxValor) {
    const cont = document.getElementById(contenedorId);
    if (!cont) return;

    if (lista.length === 0) {
        cont.innerHTML = '<div style="text-align:center;color:#6b8aaa;font-size:0.6rem;padding:10px 0;">Sin datos</div>';
        return;
    }

    let html = '';
    for (let s of lista) {
        let valor = 0;
        let claseBarra = 'damage';

        if (panelDatosCombateFiltro === 'damage') {
            valor = s.damageDealt || 0;
            if (s.tipoAtaque === 'especial') {
                claseBarra = 'damage-especial';
            } else {
                claseBarra = 'damage';
            }
        } else if (panelDatosCombateFiltro === 'received') {
            valor = s.damageTaken || 0;
            claseBarra = 'received';
        } else if (panelDatosCombateFiltro === 'heal') {
            valor = s.healingDone || 0;
            claseBarra = 'heal';
        }

        let porcentaje = maxValor > 0 ? Math.min(100, (valor / maxValor) * 100) : 0;
        
        // 🆕 FIX v4.1: Mínimo visual del 2% si el valor es mayor que 0
        // para que las barras no desaparezcan en comparaciones extremas.
        if (valor > 0 && porcentaje < 2) {
            porcentaje = 2;
        }
        
        // Si el valor es mayor a 100.000, lo limitamos visualmente al 100%
        // (aunque el número de texto seguirá mostrando el valor real)
        if (porcentaje > 100) porcentaje = 100;

        const spriteUrl = typeof getSpriteUrl === 'function'
            ? getSpriteUrl(s.spriteId || s.id, s.nombre)
            : '';

        html += `
            <div class="panel-datos-item">
                <div class="sprite">
                    <img src="${spriteUrl}" alt="${s.nombre}" onerror="this.style.display='none'">
                </div>
                <div class="info">
                    <div class="fila-superior">
                        <span class="valor">${Math.round(valor)}</span>
                    </div>
                    <div class="barra-container">
                        <div class="barra-fill ${claseBarra}" style="width:${porcentaje}%;"></div>
                    </div>
                </div>
            </div>
        `;
    }

    cont.innerHTML = html;
}

// ============================================================
// FILTROS
// ============================================================

function conectarFiltrosPanelDatos() {
    document.querySelectorAll('.panel-datos-filtro').forEach(btn => {
        btn.addEventListener('click', function () {
            const filtro = this.dataset.filtro;
            if (!filtro) return;

            document.querySelectorAll('.panel-datos-filtro').forEach(b => b.classList.remove('activo'));
            this.classList.add('activo');

            panelDatosCombateFiltro = filtro;
            renderizarPanelDatosCombate();
        });
    });
}

// ============================================================
// INICIALIZAR
// ============================================================

function initPanelDatosCombate() {
    try {
        const btnCerrar = document.getElementById('btnCerrarPanelDatos');
        if (btnCerrar) {
            btnCerrar.addEventListener('click', cerrarPanelDatosCombate);
        }

        conectarFiltrosPanelDatos();

        document.addEventListener('keydown', function (e) {
            if (e.key === 'Escape' && panelDatosCombateAbierto) {
                cerrarPanelDatosCombate();
            }
        });

        console.log('✅ panelDatosCombate.js inicializado correctamente');
    } catch (e) {
        console.error('❌ Error en initPanelDatosCombate:', e);
    }
}

// ============================================================
// 🔴 EXPONER GLOBALMENTE
// ============================================================

try {
    window.abrirPanelDatosCombate = abrirPanelDatosCombate;
    window.cerrarPanelDatosCombate = cerrarPanelDatosCombate;
    window.togglePanelDatosCombate = togglePanelDatosCombate;
    window.renderizarPanelDatosCombate = renderizarPanelDatosCombate;
    window.iniciarAutoRefreshPanelDatos = iniciarAutoRefreshPanelDatos;
    window.detenerAutoRefreshPanelDatos = detenerAutoRefreshPanelDatos;
    window.initPanelDatosCombate = initPanelDatosCombate;

    // Usar getters/setters para que panelDatosCombateAbierto esté sincronizado
    Object.defineProperty(window, 'panelDatosCombateAbierto', {
        get: function() { return panelDatosCombateAbierto; },
        set: function(v) { panelDatosCombateAbierto = v; },
        configurable: true
    });

    console.log('✅ panelDatosCombate.js: funciones expuestas globalmente');
} catch (e) {
    console.error('❌ Error al exponer funciones globalmente:', e);
}

// ============================================================
// INICIALIZACIÓN
// ============================================================

if (document.readyState === 'complete' || document.readyState === 'interactive') {
    setTimeout(initPanelDatosCombate, 0);
} else {
    document.addEventListener('DOMContentLoaded', initPanelDatosCombate);
}
;

/* ==================== js/ui/dragDrop.js ==================== */
// ============================================================
// DRAG & DROP ESTILO SOLITARIO - v19 (FIX drag de objetos)
// ============================================================
// v19:
//   - FIX: el pointerdown sobre el CONTENEDOR de objetos equipados
//     (.objetos-equipados) ya NO arrastra el Pokémon. Antes, si
//     pulsabas en el hueco/padding entre iconos, el evento burbujeaba
//     a la celda y dragDrop.js arrastraba la unidad.
//   - FIX: se ignoran también los pointerdown dentro de
//     .objetos-equipados aunque el target sea el contenedor.
//
// v18:
//   - SHINY en el fantasma del drag
//   - El sprite de la celda origen mira a la DERECHA durante el drag
// ============================================================

(function () {
    'use strict';

    const AZUL       = '#67bed9';
    const AZUL_RGB   = '103, 190, 217';
    const BEIGE      = '#e1d0ab';
    const BEIGE_RGB  = '225, 208, 171';
    const ROJO       = '#ef4444';
    const ROJO_RGB   = '239, 68, 68';

    const RANGO_CUBRE_TODO = 11;

    const dragState = {
        activo: false,
        tipoOrigen: null,
        indiceOrigen: null,
        unidad: null,
        celdaOrigen: null,
        fantasma: null,
        offsetX: 0,
        offsetY: 0,
        startX: 0,
        startY: 0,
        umbralSuperado: false,
        pointerId: null,
        coloresAplicados: false,
        indiceHover: null,
    };

    const UMBRAL_DRAG = 6;

    // ============================================================
    // HELPERS
    // ============================================================

    function _spriteMiraDerechaSafe(spriteId) {
        if (typeof window._spriteMiraDerecha === 'function') {
            try {
                return window._spriteMiraDerecha(spriteId);
            } catch (e) {
                return false;
            }
        }
        return false;
    }

    function _getSpriteScaleSafe(spriteId) {
        if (typeof getSpriteScale === 'function') {
            try { return getSpriteScale(spriteId); } catch (e) {}
        }
        return 1;
    }

    function _getSpriteOffsetXSafe(spriteId) {
        if (typeof getSpriteOffsetX === 'function') {
            try { return getSpriteOffsetX(spriteId); } catch (e) {}
        }
        return '0px';
    }

    function puedeArrastrar(tipo, indice) {
        if (typeof combatiendo !== 'undefined' && combatiendo) {
            return tipo === 'banquillo';
        }
        if (tipo === 'enemigo' || tipo === 'enemigoBanquillo') {
            return !!window.modoCreativo;
        }
        return tipo === 'tablero' || tipo === 'banquillo';
    }

    function obtenerUnidadDe(tipo, indice) {
        if (tipo === 'tablero') return tablero[indice] || null;
        if (tipo === 'banquillo') return banquillo[indice] || null;
        if (tipo === 'enemigo') return enemyBoard[indice] || null;
        if (tipo === 'enemigoBanquillo') return enemyBanquillo[indice] || null;
        return null;
    }

    function esDestinoValido(tipoOrigen, tipoDestino) {
        const origenJugador = tipoOrigen === 'tablero' || tipoOrigen === 'banquillo';
        const destinoJugador = tipoDestino === 'tablero' || tipoDestino === 'banquillo';
        const origenEnemigo = tipoOrigen === 'enemigo' || tipoOrigen === 'enemigoBanquillo';
        const destinoEnemigo = tipoDestino === 'enemigo' || tipoDestino === 'enemigoBanquillo';

        if ((origenJugador && destinoEnemigo) || (origenEnemigo && destinoJugador)) {
            return false;
        }
        if (destinoEnemigo && !window.modoCreativo) {
            return false;
        }
        return true;
    }

    function bloquearClicksGlobales(ms) {
        if (document.body.dataset.dragBlockClicks === '1') return;
        document.body.dataset.dragBlockClicks = '1';

        const blocker = function (e) {
            e.stopPropagation();
            e.preventDefault();
            if (e.stopImmediatePropagation) e.stopImmediatePropagation();
        };

        document.addEventListener('click', blocker, true);
        document.addEventListener('pointerup', blocker, true);
        document.addEventListener('mouseup', blocker, true);
        document.addEventListener('pointerdown', blocker, true);

        setTimeout(() => {
            document.removeEventListener('click', blocker, true);
            document.removeEventListener('pointerup', blocker, true);
            document.removeEventListener('mouseup', blocker, true);
            document.removeEventListener('pointerdown', blocker, true);
            delete document.body.dataset.dragBlockClicks;
        }, ms);
    }

    window.bloquearClicksGlobales = bloquearClicksGlobales;

    function aplicarColoresDeSeleccion(tipoOrigen, indiceOrigen, unidad, indiceHover, esHover) {
        if (indiceHover === undefined) indiceHover = null;
        if (esHover === undefined) esHover = false;

        limpiarColoresDeSeleccion();

        const indiceBase = (indiceHover !== null) ? indiceHover : indiceOrigen;

        if (tipoOrigen === 'tablero') {
            let rango = 1;
            if (typeof obtenerRangoAtaque === 'function') {
                rango = obtenerRangoAtaque(unidad);
            }

            const rangoCubreTodo = (rango >= RANGO_CUBRE_TODO);

            document.querySelectorAll('#playerBoard .board-cell').forEach((cell, i) => {
                if (i === indiceBase) return;

                let enRango = rangoCubreTodo;
                if (!rangoCubreTodo && typeof estaEnRango === 'function') {
                    enRango = estaEnRango(indiceBase, i, rango);
                }

                if (enRango) {
                    cell.style.setProperty('border', '3px solid ' + BEIGE, 'important');
                    cell.style.setProperty('box-shadow',
                        '0 0 25px rgba(' + BEIGE_RGB + ', 0.5), inset 0 0 25px rgba(' + BEIGE_RGB + ', 0.12)',
                        'important');
                } else {
                    cell.style.setProperty('border', '3px solid ' + AZUL, 'important');
                    cell.style.setProperty('box-shadow',
                        '0 0 25px rgba(' + AZUL_RGB + ', 0.4), inset 0 0 25px rgba(' + AZUL_RGB + ', 0.10)',
                        'important');
                }
            });

            document.querySelectorAll('#enemigoBoard .board-cell').forEach((cell, i) => {
                let enRango = rangoCubreTodo;
                if (!rangoCubreTodo && typeof estaEnRangoEntreTableros === 'function') {
                    enRango = estaEnRangoEntreTableros(indiceBase, i, rango);
                }

                if (enRango) {
                    cell.style.setProperty('border', '3px solid ' + BEIGE, 'important');
                    cell.style.setProperty('box-shadow',
                        '0 0 25px rgba(' + BEIGE_RGB + ', 0.5), inset 0 0 25px rgba(' + BEIGE_RGB + ', 0.12)',
                        'important');
                } else {
                    cell.style.removeProperty('border');
                    cell.style.removeProperty('box-shadow');
                }
            });

            // 🖱️ Al pasar el ratón (hover) NO se marcan las casillas del banco;
            // solo al ARRASTRAR se resalta el banco como posible destino.
            if (!esHover) {
                document.querySelectorAll('#banquilloGrid .bank-cell').forEach(cell => {
                    cell.style.setProperty('border', '3px solid ' + AZUL, 'important');
                    cell.style.setProperty('box-shadow',
                        '0 0 20px rgba(' + AZUL_RGB + ', 0.3), inset 0 0 20px rgba(' + AZUL_RGB + ', 0.08)',
                        'important');
                });
            }
        }

        if (tipoOrigen === 'banquillo') {
            document.querySelectorAll('#playerBoard .board-cell').forEach(cell => {
                cell.style.setProperty('border', '3px solid ' + AZUL, 'important');
                cell.style.setProperty('box-shadow',
                    '0 0 25px rgba(' + AZUL_RGB + ', 0.5), inset 0 0 25px rgba(' + AZUL_RGB + ', 0.12)',
                    'important');
            });
            document.querySelectorAll('#banquilloGrid .bank-cell').forEach(cell => {
                cell.style.setProperty('border', '3px solid ' + AZUL, 'important');
                cell.style.setProperty('box-shadow',
                    '0 0 20px rgba(' + AZUL_RGB + ', 0.3), inset 0 0 20px rgba(' + AZUL_RGB + ', 0.08)',
                    'important');
            });
            document.querySelectorAll('#enemigoBoard .board-cell, #enemyBanquilloGrid .bank-cell').forEach(cell => {
                cell.style.removeProperty('border');
                cell.style.removeProperty('box-shadow');
            });
        }

        if (tipoOrigen === 'enemigo') {
            document.querySelectorAll('#enemigoBoard .board-cell').forEach((cell, i) => {
                if (i === indiceBase) return;
                cell.style.setProperty('border', '3px solid ' + ROJO, 'important');
                cell.style.setProperty('box-shadow',
                    '0 0 25px rgba(' + ROJO_RGB + ', 0.4), inset 0 0 25px rgba(' + ROJO_RGB + ', 0.10)',
                    'important');
            });
            document.querySelectorAll('#enemyBanquilloGrid .bank-cell').forEach(cell => {
                cell.style.setProperty('border', '3px solid ' + ROJO, 'important');
                cell.style.setProperty('box-shadow',
                    '0 0 20px rgba(' + ROJO_RGB + ', 0.3), inset 0 0 20px rgba(' + ROJO_RGB + ', 0.08)',
                    'important');
            });
            document.querySelectorAll('#playerBoard .board-cell, #banquilloGrid .bank-cell').forEach(cell => {
                cell.style.removeProperty('border');
                cell.style.removeProperty('box-shadow');
                cell.style.removeProperty('background');
            });
        }

        if (tipoOrigen === 'enemigoBanquillo') {
            document.querySelectorAll('#enemigoBoard .board-cell').forEach(cell => {
                cell.style.setProperty('border', '3px solid ' + ROJO, 'important');
                cell.style.setProperty('box-shadow',
                    '0 0 25px rgba(' + ROJO_RGB + ', 0.5), inset 0 0 25px rgba(' + ROJO_RGB + ', 0.12)',
                    'important');
            });
            document.querySelectorAll('#enemyBanquilloGrid .bank-cell').forEach(cell => {
                cell.style.setProperty('border', '3px solid ' + ROJO, 'important');
                cell.style.setProperty('box-shadow',
                    '0 0 20px rgba(' + ROJO_RGB + ', 0.3), inset 0 0 20px rgba(' + ROJO_RGB + ', 0.08)',
                    'important');
            });
        }

        dragState.coloresAplicados = true;
    }

    function limpiarColoresDeSeleccion() {
        document.querySelectorAll(
            '#playerBoard .board-cell, #enemigoBoard .board-cell, ' +
            '#banquilloGrid .bank-cell, #enemyBanquilloGrid .bank-cell'
        ).forEach(cell => {
            cell.style.removeProperty('border');
            cell.style.removeProperty('box-shadow');
        });
        dragState.coloresAplicados = false;
    }

    function posicionarBotonVenderDrag() {
        const actionBar = document.querySelector('.action-bar');
        if (!actionBar) return;

        const rect = actionBar.getBoundingClientRect();
        if (rect.width <= 0 || rect.height <= 0) return;

        const separacion = 6;

        const btn = document.getElementById('btnVenderDrag');
        if (btn && btn.style.display !== 'none') {
            const anchoBtn = btn.offsetWidth || 90;
            const altoBtn  = btn.offsetHeight || 54;
            let left = rect.left - anchoBtn - separacion;
            let top;
            if (left < 8) {
                left = Math.max(8, rect.left);
                top = Math.max(8, rect.top - altoBtn - 8);
            } else {
                top = rect.top + (rect.height - altoBtn) / 2;
            }
            btn.style.left = left + 'px';
            btn.style.top  = top + 'px';
        }

        // 🆕 Botón vender duplicado (a la derecha de la barra de acciones)
        const btn2 = document.getElementById('btnVenderDrag2');
        if (btn2 && btn2.style.display !== 'none') {
            const anchoBtn2 = btn2.offsetWidth || 90;
            const altoBtn2  = btn2.offsetHeight || 54;
            btn2.style.left = (rect.right + separacion) + 'px';
            btn2.style.top  = (rect.top + (rect.height - altoBtn2) / 2) + 'px';
        }
    }

    function mostrarBotonVenderDrag(tipoOrigen, unidad) {
        const btn = document.getElementById('btnVenderDrag');
        const btn2 = document.getElementById('btnVenderDrag2');
        if (!btn) return;

        const esJugador = tipoOrigen === 'tablero' || tipoOrigen === 'banquillo';
        const esVendible = esJugador && unidad && !unidad.esZacian;

        if (!esVendible) {
            btn.style.display = 'none';
            if (btn2) btn2.style.display = 'none';
            return;
        }

        const costeBase = unidad.costeOriginal || (unidad.pokemon && unidad.pokemon.coste) || 1;
        let multiplicador = 1;
        if (unidad.nivel === 2) multiplicador = 3;
        else if (unidad.nivel === 3) multiplicador = 9;

        const precio = costeBase * multiplicador;

        const precioEl = document.getElementById('venderDragPrecio');
        if (precioEl) precioEl.textContent = precio;
        const precioEl2 = document.getElementById('venderDragPrecio2');
        if (precioEl2) precioEl2.textContent = precio;

        btn.style.display = 'flex';
        btn.classList.remove('drag-hover');
        btn.classList.remove('drag-invalido');
        if (btn2) {
            btn2.style.display = 'flex';
            btn2.classList.remove('drag-hover');
            btn2.classList.remove('drag-invalido');
        }

        posicionarBotonVenderDrag();
    }

    function ocultarBotonVenderDrag() {
        const btn = document.getElementById('btnVenderDrag');
        const btn2 = document.getElementById('btnVenderDrag2');
        if (btn) {
            btn.style.display = 'none';
            btn.classList.remove('drag-hover');
            btn.classList.remove('drag-invalido');
        }
        if (btn2) {
            btn2.style.display = 'none';
            btn2.classList.remove('drag-hover');
            btn2.classList.remove('drag-invalido');
        }
    }

    function getBotonVenderSobre(e) {
        const ids = ['btnVenderDrag', 'btnVenderDrag2'];
        for (const id of ids) {
            const btn = document.getElementById(id);
            if (!btn || btn.style.display === 'none') continue;
            const rect = btn.getBoundingClientRect();
            if (e.clientX >= rect.left && e.clientX <= rect.right &&
                e.clientY >= rect.top && e.clientY <= rect.bottom) {
                return btn;
            }
        }
        return null;
    }

    // ============================================================
    // crearFantasma
    // ============================================================

    function crearFantasma(unidad, e) {
        const celdaOrigen = dragState.celdaOrigen;

        let anchoFantasma = 90;
        let altoFantasma = 105;

        if (celdaOrigen) {
            const rect = celdaOrigen.getBoundingClientRect();
            anchoFantasma = Math.max(80, Math.min(180, rect.width * 1.05));
            altoFantasma  = Math.max(90, Math.min(200, rect.height * 1.05));
        }

        const costeOriginal = unidad.costeOriginal || (unidad.pokemon && unidad.pokemon.coste) || 1;
        const claseCoste = unidad.esZacian ? 'cost-5' : ('cost-' + costeOriginal);

        const ghost = document.createElement('div');
        ghost.className = 'drag-ghost ' + claseCoste;

        ghost.style.width = anchoFantasma + 'px';
        ghost.style.height = altoFantasma + 'px';

        const spriteId = unidad.spriteIdAlternativo || (unidad.pokemon && unidad.pokemon.spriteId) || 0;

        const esShinyGhost = unidad.esShiny === true;

        const spriteUrl = (typeof getSpriteUrl === 'function')
            ? getSpriteUrl(spriteId, unidad.pokemon.nombre, esShinyGhost)
            : '';

        const escalaGhost = _getSpriteScaleSafe(spriteId);
        const offsetXGhost = _getSpriteOffsetXSafe(spriteId);

        const miraDerechaGhost = _spriteMiraDerechaSafe(spriteId);
        const flipGhost = miraDerechaGhost ? 1 : -1;

        const transformGhost = `translateX(${offsetXGhost}) scaleX(${flipGhost}) scale(${escalaGhost})`;

        let estrellasHtml = '';
        if (unidad.nivel >= 1 && typeof getEstrellasUrl === 'function') {
            estrellasHtml = '<img class="ghost-estrellas" src="' + getEstrellasUrl(unidad.nivel) + '" alt="' + unidad.nivel + '★" draggable="false">';
        }

        let traitsHtml = '';
        if (unidad.pokemon.tipos && unidad.pokemon.tipos.length > 0 && typeof getIconoTipo === 'function') {
            traitsHtml += unidad.pokemon.tipos.map(t => '<span class="ghost-trait">' + getIconoTipo(t) + '</span>').join('');
        }
        if (unidad.pokemon.clase && typeof getIconoClase === 'function') {
            traitsHtml += '<span class="ghost-trait">' + getIconoClase(unidad.pokemon.clase) + '</span>';
        }

        const claseShinyGhost = esShinyGhost ? ' shiny' : '';
        const sufijoShiny = esShinyGhost ? ' ✨' : '';

        ghost.innerHTML =
            '<div class="ghost-traits-top">' + traitsHtml + '</div>' +
            estrellasHtml +
            '<img class="ghost-sprite' + claseShinyGhost + '" src="' + spriteUrl + '" alt="' + unidad.pokemon.nombre + sufijoShiny + '" draggable="false" style="transform: ' + transformGhost + ' !important; -webkit-transform: ' + transformGhost + ' !important; --sprite-flip: ' + flipGhost + '; --sprite-scale: ' + escalaGhost + '; --sprite-offset-x: ' + offsetXGhost + ';" onerror="this.style.display=\'none\'">' +
            '<span class="ghost-name">' + unidad.pokemon.nombre + sufijoShiny + '</span>';

        document.body.appendChild(ghost);

        dragState.offsetX = ghost.offsetWidth / 2;
        dragState.offsetY = ghost.offsetHeight / 2;
        ghost.style.left = (e.clientX - dragState.offsetX) + 'px';
        ghost.style.top = (e.clientY - dragState.offsetY) + 'px';

        dragState.fantasma = ghost;

        document.body.classList.add('dragging-active');

        if (dragState.celdaOrigen) {
            const spriteOrigen = dragState.celdaOrigen.querySelector('.unit-sprite');
            if (spriteOrigen) {
                const spriteIdOrigen = unidad.spriteIdAlternativo || (unidad.pokemon && unidad.pokemon.spriteId) || 0;
                const miraDerechaOrigen = _spriteMiraDerechaSafe(spriteIdOrigen);
                const flipOrigen = miraDerechaOrigen ? 1 : -1;
                const offsetXOrigen = _getSpriteOffsetXSafe(spriteIdOrigen);
                const escalaOrigen = _getSpriteScaleSafe(spriteIdOrigen);

                spriteOrigen.style.setProperty('--sprite-drag-flip', flipOrigen);
                spriteOrigen.style.setProperty('--sprite-drag-offset-x', offsetXOrigen);
                spriteOrigen.style.setProperty('--sprite-drag-scale', escalaOrigen);
                spriteOrigen.classList.add('sprite-drag-derecha');
            }
        }

        mostrarBotonVenderDrag(dragState.tipoOrigen, unidad);
    }

    function resaltarCeldaDestino(e) {
        document.querySelectorAll('.drag-over-valida, .drag-over-invalida').forEach(c => {
            c.classList.remove('drag-over-valida');
            c.classList.remove('drag-over-invalida');
        });

        if (dragState.fantasma) dragState.fantasma.style.display = 'none';
        const el = document.elementFromPoint(e.clientX, e.clientY);
        if (dragState.fantasma) dragState.fantasma.style.display = '';

        const cell = el && el.closest('.board-cell, .bank-cell');

        if (!cell) {
            if (dragState.tipoOrigen === 'tablero' && dragState.indiceHover !== null) {
                dragState.indiceHover = null;
                aplicarColoresDeSeleccion(
                    dragState.tipoOrigen,
                    dragState.indiceOrigen,
                    dragState.unidad,
                    null
                );
            }
            return;
        }

        const tipoDestino = cell.dataset.tipo;
        const indiceDestino = parseInt(cell.dataset.indice, 10);

        if (isNaN(indiceDestino)) return;

        if (tipoDestino === 'tablero' && dragState.tipoOrigen === 'tablero') {
            if (dragState.indiceHover !== indiceDestino) {
                dragState.indiceHover = indiceDestino;
                aplicarColoresDeSeleccion(
                    dragState.tipoOrigen,
                    dragState.indiceOrigen,
                    dragState.unidad,
                    indiceDestino
                );
            }
        }

        if (tipoDestino === dragState.tipoOrigen && indiceDestino === dragState.indiceOrigen) {
            return;
        }

        if (esDestinoValido(dragState.tipoOrigen, tipoDestino)) {
            cell.classList.add('drag-over-valida');
        } else {
            cell.classList.add('drag-over-invalida');
        }
    }

    function onPointerDown(e, tipo, indice, cell) {
        if (e.button !== undefined && e.button !== 0) return;

        // ============================================================
        // 🆕 FIX v19: ignorar pointerdown sobre CUALQUIER cosa dentro
        // de .objetos-equipados (iconos, huecos, padding del contenedor).
        // Antes solo se ignoraba si el target era el icono exacto,
        // así que pulsar en el hueco entre iconos arrastraba el Pokémon.
        // ============================================================
        if (e.target && typeof e.target.closest === 'function' &&
            e.target.closest('.objetos-equipados, .objeto-equipado-tablero, .objeto-equipado-banquillo')) {
            return;
        }

        if (typeof objetoSeleccionado !== 'undefined' && objetoSeleccionado) return;

        const unidad = obtenerUnidadDe(tipo, indice);
        if (!unidad) return;

        dragState.activo = true;
        dragState.tipoOrigen = tipo;
        dragState.indiceOrigen = indice;
        dragState.unidad = unidad;
        dragState.celdaOrigen = cell;
        dragState.startX = e.clientX;
        dragState.startY = e.clientY;
        dragState.umbralSuperado = false;
        dragState.pointerId = e.pointerId;
        dragState.coloresAplicados = false;
        dragState.indiceHover = null;

        window.addEventListener('pointermove', onPointerMove);
        window.addEventListener('pointerup', onPointerUp);
        window.addEventListener('pointercancel', onPointerUp);
    }

    function onPointerMove(e) {
        if (!dragState.activo) return;
        if (dragState.pointerId !== null && e.pointerId !== dragState.pointerId) return;

        const dx = e.clientX - dragState.startX;
        const dy = e.clientY - dragState.startY;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (!dragState.umbralSuperado && dist < UMBRAL_DRAG) return;

        if (!dragState.umbralSuperado) {
            dragState.umbralSuperado = true;
            crearFantasma(dragState.unidad, e);
            if (dragState.celdaOrigen) {
                dragState.celdaOrigen.classList.add('drag-origen');
            }
            aplicarColoresDeSeleccion(
                dragState.tipoOrigen,
                dragState.indiceOrigen,
                dragState.unidad,
                null
            );
            e.preventDefault();
        }

        if (dragState.fantasma) {
            dragState.fantasma.style.left = (e.clientX - dragState.offsetX) + 'px';
            dragState.fantasma.style.top = (e.clientY - dragState.offsetY) + 'px';
        }

        const btnVenderSobre = getBotonVenderSobre(e);

        if (btnVenderSobre) {
            btnVenderSobre.classList.add('drag-hover');
            const otroId = btnVenderSobre.id === 'btnVenderDrag' ? 'btnVenderDrag2' : 'btnVenderDrag';
            const otro = document.getElementById(otroId);
            if (otro) otro.classList.remove('drag-hover');
            document.querySelectorAll('.drag-over-valida, .drag-over-invalida').forEach(c => {
                c.classList.remove('drag-over-valida');
                c.classList.remove('drag-over-invalida');
            });
            if (dragState.coloresAplicados && dragState.tipoOrigen === 'tablero') {
                if (dragState.indiceHover !== null) {
                    dragState.indiceHover = null;
                    aplicarColoresDeSeleccion(
                        dragState.tipoOrigen,
                        dragState.indiceOrigen,
                        dragState.unidad,
                        null
                    );
                }
            }
        } else {
            const btnVender = document.getElementById('btnVenderDrag');
            const btnVender2 = document.getElementById('btnVenderDrag2');
            if (btnVender) btnVender.classList.remove('drag-hover');
            if (btnVender2) btnVender2.classList.remove('drag-hover');
            resaltarCeldaDestino(e);
        }
    }

    function onPointerUp(e) {
        if (!dragState.activo) return;

        window.removeEventListener('pointermove', onPointerMove);
        window.removeEventListener('pointerup', onPointerUp);
        window.removeEventListener('pointercancel', onPointerUp);

        const superoUmbral = dragState.umbralSuperado;

        if (superoUmbral) {
            bloquearClicksGlobales(250);
        }

        if (dragState.fantasma) dragState.fantasma.remove();
        if (dragState.celdaOrigen) dragState.celdaOrigen.classList.remove('drag-origen');
        document.querySelectorAll('.drag-over-valida, .drag-over-invalida').forEach(c => {
            c.classList.remove('drag-over-valida');
            c.classList.remove('drag-over-invalida');
        });

        if (dragState.coloresAplicados) {
            limpiarColoresDeSeleccion();
        }

        document.body.classList.remove('dragging-active');

        if (!superoUmbral) {
            resetEstado();
            return;
        }

        if (getBotonVenderSobre(e)) {
            const tipoOrigen = dragState.tipoOrigen;
            const indiceOrigen = dragState.indiceOrigen;

            if (tipoOrigen === 'tablero' || tipoOrigen === 'banquillo') {
                const unidad = obtenerUnidadDe(tipoOrigen, indiceOrigen);
                if (unidad && !unidad.esZacian && typeof vender === 'function') {
                    ocultarBotonVenderDrag();
                    document.body.classList.remove('dragging-active');

                    try {
                        vender(tipoOrigen, indiceOrigen);
                    } catch (err) {
                        console.error('❌ Error al vender por drag:', err);
                    }

                    resetEstado();
                    return;
                }
            }
        }

        const elDestino = document.elementFromPoint(e.clientX, e.clientY);
        const cellDestino = elDestino ? elDestino.closest('.board-cell, .bank-cell') : null;

        if (cellDestino) {
            const tipoDestino = cellDestino.dataset.tipo;
            const indiceDestino = parseInt(cellDestino.dataset.indice, 10);

            if (!isNaN(indiceDestino) &&
                esDestinoValido(dragState.tipoOrigen, tipoDestino) &&
                !(tipoDestino === dragState.tipoOrigen && indiceDestino === dragState.indiceOrigen)) {

                const tipoOrigen = dragState.tipoOrigen;
                const indiceOrigen = dragState.indiceOrigen;

                try {
                    if (typeof moverUnidad === 'function') {
                        moverUnidad(tipoOrigen, indiceOrigen, tipoDestino, indiceDestino);

                        setTimeout(() => {
                            const celdaNueva = document.querySelector(
                                '.board-cell[data-tipo="' + tipoDestino + '"][data-indice="' + indiceDestino + '"], ' +
                                '.bank-cell[data-tipo="' + tipoDestino + '"][data-indice="' + indiceDestino + '"]'
                            );
                            if (celdaNueva) {
                                celdaNueva.classList.add('drag-dropping');
                                setTimeout(() => celdaNueva.classList.remove('drag-dropping'), 300);
                            }
                        }, 10);
                    }
                } catch (err) {
                    console.error('❌ Error al soltar en drag:', err);
                }
            }
        }

        resetEstado();
    }

    function resetEstado() {
        if (dragState.celdaOrigen) {
            const spriteOrigen = dragState.celdaOrigen.querySelector('.unit-sprite');
            if (spriteOrigen) {
                spriteOrigen.classList.remove('sprite-drag-derecha');
                spriteOrigen.style.removeProperty('--sprite-drag-flip');
                spriteOrigen.style.removeProperty('--sprite-drag-offset-x');
                spriteOrigen.style.removeProperty('--sprite-drag-scale');
            }
        }

        dragState.activo = false;
        dragState.tipoOrigen = null;
        dragState.indiceOrigen = null;
        dragState.unidad = null;
        dragState.celdaOrigen = null;
        dragState.fantasma = null;
        dragState.offsetX = 0;
        dragState.offsetY = 0;
        dragState.startX = 0;
        dragState.startY = 0;
        dragState.umbralSuperado = false;
        dragState.pointerId = null;
        dragState.coloresAplicados = false;
        dragState.indiceHover = null;
        document.body.classList.remove('dragging-active');

        ocultarBotonVenderDrag();
    }

    function engancharDrag(cell, tipo, indice) {
        if (!cell) return;
        if (cell.dataset.dragEnganchado === '1') return;
        cell.dataset.dragEnganchado = '1';

        cell.addEventListener('pointerdown', function (e) {
            onPointerDown(e, tipo, indice, cell);
        });
    }

    function initDragDrop() {
        console.log('🎴 DragDrop estilo Solitario inicializado (v19 - FIX drag de objetos)');

        document.addEventListener('dragstart', function (e) {
            const dentroDeCelda = e.target.closest('.board-cell, .bank-cell, .drag-ghost');
            if (dentroDeCelda) {
                e.preventDefault();
                return false;
            }
        }, true);

        document.addEventListener('dragover', function (e) {
            const dentroDeCelda = e.target.closest('.board-cell, .bank-cell');
            if (dentroDeCelda) {
                e.preventDefault();
            }
        }, true);

        document.addEventListener('drop', function (e) {
            const dentroDeCelda = e.target.closest('.board-cell, .bank-cell');
            if (dentroDeCelda) {
                e.preventDefault();
            }
        }, true);

        document.addEventListener('selectstart', function (e) {
            const dentroDeCelda = e.target.closest('.board-cell, .bank-cell, .drag-ghost');
            if (dentroDeCelda) {
                e.preventDefault();
                return false;
            }
        }, true);

        const btnVender = document.getElementById('btnVenderDrag');
        if (btnVender) {
            btnVender.addEventListener('pointerdown', function (e) {
                e.stopPropagation();
            });
            btnVender.addEventListener('click', function (e) {
                e.stopPropagation();
                e.preventDefault();
            });
        }

        window.addEventListener('resize', function () {
            posicionarBotonVenderDrag();
        });

        window.addEventListener('scroll', function () {
            posicionarBotonVenderDrag();
        }, { passive: true });
    }

    window.initDragDrop = initDragDrop;
    window.puedeArrastrar = puedeArrastrar;
    window.engancharDrag = engancharDrag;
    window.ocultarBotonVenderDrag = ocultarBotonVenderDrag;
    window.posicionarBotonVenderDrag = posicionarBotonVenderDrag;
    // Reutilizados por el resaltado al pasar el ratón (hover sobre un Pokémon).
    window.aplicarColoresDeSeleccion = aplicarColoresDeSeleccion;
    window.limpiarColoresDeSeleccion = limpiarColoresDeSeleccion;
    window.estaArrastrando = function () { return dragState.activo; };

    console.log('✅ dragDrop.js cargado (v19 - FIX drag de objetos)');
})();
;

/* ==================== js/ui/dragObjetos.js ==================== */
// ============================================================
// DRAG & DROP DE OBJETOS - v3 (FIX índice DOM vs índice real)
// ============================================================
// v3:
//   - FIX: refrescarDragObjetosEquipados ahora lee el nombre e
//     índice REALES del dataset del icono (data-objeto-nombre,
//     data-objeto-index) en vez de usar el índice del DOM.
//     Antes, con huecos (1 objeto normal + disco), el índice
//     del DOM no coincidía con unidad.objetos[] y el disco
//     quedaba sin enganchar. Al pulsarlo, el pointerdown
//     burbujeaba a la celda y dragDrop.js arrastraba el Pokémon.
//   - FIX: solo se enganchan iconos con :not(.vacio) y
//     :not(.slot-ulti.vacio) para no crear listeners inútiles.
//   - FIX: no se llama e.preventDefault() en el pointerdown
//     del icono (rompía el click de desequipar en algunos casos).
//   - FIX: guard adicional con closest('.objetos-equipados') en
//     initDragObjetos() para bloquear el drag nativo.
//
// v2:
//   - Guards `e.target.closest` en initDragObjetos()
//   - Selector de lado (jugador/enemigo) en creativePanel
// ============================================================

(function () {
    'use strict';

    // ------------------------------------------------------------
    // ESTADO DEL DRAG DE OBJETO
    // ------------------------------------------------------------
    const dragObjState = {
        activo: false,
        nombre: null,
        lado: null,
        origen: null,
        indexBaul: null,
        tipoUnidadOrigen: null,
        indiceUnidadOrigen: null,
        indexObjetoEquipado: null,
        slotOrigen: null,
        fantasma: null,
        offsetX: 0,
        offsetY: 0,
        startX: 0,
        startY: 0,
        umbralSuperado: false,
        pointerId: null,
    };

    const UMBRAL_DRAG = 6;

    // ------------------------------------------------------------
    // OBTENER LA LISTA DE BAÚL SEGÚN LADO
    // ------------------------------------------------------------
    function getBaul(lado) {
        if (lado === 'jugador') {
            return (typeof baulObjetos !== 'undefined') ? baulObjetos : [];
        } else {
            return (typeof enemyBaulObjetos !== 'undefined') ? enemyBaulObjetos : [];
        }
    }

    // ------------------------------------------------------------
    // ¿EL OBJETO ES COMPATIBLE CON ESTA UNIDAD?
    // ------------------------------------------------------------
    function puedeEquiparObjeto(unidad, nombreObjeto) {
        if (!unidad || !unidad.pokemon) return false;

        if (unidad.esZacian || unidad.noEquiparObjetos) return false;
        if (unidad.objetos && unidad.objetos.includes(nombreObjeto)) return false;

        const objeto = (typeof OBJETOS !== 'undefined') ? OBJETOS[nombreObjeto] : null;
        if (!objeto) return false;

        const esDisco = objeto.efecto && objeto.efecto.esDiscoUlti;
        const objetosNormales = (unidad.objetos || []).filter(o => {
            const od = OBJETOS[o];
            return !(od && od.efecto && od.efecto.esDiscoUlti);
        });
        const discosEquipados = (unidad.objetos || []).filter(o => {
            const od = OBJETOS[o];
            return od && od.efecto && od.efecto.esDiscoUlti;
        });

        if (esDisco) {
            if (unidad.nivel < 2) return false;
            if (discosEquipados.length >= 1) return false;
        } else {
            if (objetosNormales.length >= 2) return false;
        }

        if (objeto.requerido) {
            let tieneTipo = false;
            if (unidad.pokemon.tipos && Array.isArray(unidad.pokemon.tipos)) {
                for (let tipo of unidad.pokemon.tipos) {
                    if (tipo === objeto.requerido) {
                        tieneTipo = true;
                        break;
                    }
                }
            }
            if (!tieneTipo) return false;
        }

        return true;
    }

    // ------------------------------------------------------------
    // ¿ES DESTINO VÁLIDO PARA EL OBJETO?
    // ------------------------------------------------------------
    function esDestinoObjetoValido(unidad, nombreObjeto, ladoOrigen, tipoDestino) {
        if (!unidad) return false;

        const origenJugador = ladoOrigen === 'jugador';
        const destinoJugador = tipoDestino === 'tablero' || tipoDestino === 'banquillo';
        const destinoEnemigo = tipoDestino === 'enemigo' || tipoDestino === 'enemigoBanquillo';

        if (origenJugador && destinoEnemigo) return false;
        if (!origenJugador && destinoJugador) return false;

        return puedeEquiparObjeto(unidad, nombreObjeto);
    }

    // ------------------------------------------------------------
    // OBTENER UNIDAD DE UNA CELDA
    // ------------------------------------------------------------
    function obtenerUnidadDeCelda(tipo, indice) {
        if (tipo === 'tablero') return tablero[indice] || null;
        if (tipo === 'banquillo') return banquillo[indice] || null;
        if (tipo === 'enemigo') return enemyBoard[indice] || null;
        if (tipo === 'enemigoBanquillo') return enemyBanquillo[indice] || null;
        return null;
    }

    // ------------------------------------------------------------
    // ¿ESTÁ EL CURSOR SOBRE EL BAÚL?
    // ------------------------------------------------------------
    function estaCursorSobreBaul(e, lado) {
        const gridId = (lado === 'jugador') ? 'objetosVerticalGrid' : 'objetosVerticalGridEnemigo';
        const grid = document.getElementById(gridId);
        if (!grid) return false;

        const rect = grid.getBoundingClientRect();
        return (
            e.clientX >= rect.left - 10 &&
            e.clientX <= rect.right + 10 &&
            e.clientY >= rect.top - 10 &&
            e.clientY <= rect.bottom + 10
        );
    }

    // ------------------------------------------------------------
    // CREAR FANTASMA DEL OBJETO
    // ------------------------------------------------------------
    function crearFantasmaObjeto(nombreObjeto, e) {
        const ghost = document.createElement('div');
        ghost.className = 'drag-objeto-ghost';

        const objeto = (typeof OBJETOS !== 'undefined') ? OBJETOS[nombreObjeto] : null;

        let iconoHtml = '';
        if (objeto && objeto.emoji && objeto.emoji.includes('.png')) {
            iconoHtml = `<img class="ghost-objeto-icon" src="${objeto.emoji}" alt="${nombreObjeto}" draggable="false" onerror="this.style.display='none'">`;
        } else {
            iconoHtml = `<span class="ghost-objeto-icon-emoji">${(objeto && objeto.emoji) || '📦'}</span>`;
        }

        ghost.innerHTML = `
            ${iconoHtml}
            <span class="ghost-objeto-nombre">${nombreObjeto}</span>
        `;

        document.body.appendChild(ghost);

        dragObjState.offsetX = ghost.offsetWidth / 2;
        dragObjState.offsetY = ghost.offsetHeight / 2;
        ghost.style.left = (e.clientX - dragObjState.offsetX) + 'px';
        ghost.style.top = (e.clientY - dragObjState.offsetY) + 'px';

        dragObjState.fantasma = ghost;

        document.body.classList.add('dragging-objeto-active');
    }

    // ------------------------------------------------------------
    // PINTAR UNIDADES COMPATIBLES / INCOMPATIBLES + BAÚL
    // ------------------------------------------------------------
    function aplicarColoresObjeto(nombreObjeto, lado) {
        limpiarColoresObjeto();

        const selectorJugador = '#playerBoard .board-cell, #banquilloGrid .bank-cell';
        const selectorEnemigo = '#enemigoBoard .board-cell, #enemyBanquilloGrid .bank-cell';
        const selector = (lado === 'jugador') ? selectorJugador : selectorEnemigo;

        document.querySelectorAll(selector).forEach(cell => {
            const tipo = cell.dataset.tipo;
            const indice = parseInt(cell.dataset.indice, 10);
            if (isNaN(indice)) return;

            const unidad = obtenerUnidadDeCelda(tipo, indice);
            if (!unidad) return;

            if (dragObjState.origen === 'unidad' &&
                dragObjState.tipoUnidadOrigen === tipo &&
                dragObjState.indiceUnidadOrigen === indice) {
                return;
            }

            if (puedeEquiparObjeto(unidad, nombreObjeto)) {
                cell.classList.add('drag-objeto-valido');
            } else {
                cell.classList.add('drag-objeto-invalido');
            }
        });

        const gridId = (lado === 'jugador') ? 'objetosVerticalGrid' : 'objetosVerticalGridEnemigo';
        const gridBaul = document.getElementById(gridId);
        if (gridBaul) {
            gridBaul.classList.add('drag-objeto-baul-valido');
        }
    }

    function limpiarColoresObjeto() {
        document.querySelectorAll('.drag-objeto-valido, .drag-objeto-invalido').forEach(c => {
            c.classList.remove('drag-objeto-valido');
            c.classList.remove('drag-objeto-invalido');
        });

        document.querySelectorAll('.drag-objeto-baul-valido, .drag-objeto-baul-hover').forEach(g => {
            g.classList.remove('drag-objeto-baul-valido');
            g.classList.remove('drag-objeto-baul-hover');
        });
    }

    // ------------------------------------------------------------
    // RESALTAR CELDA / BAÚL BAJO EL CURSOR
    // ------------------------------------------------------------
    function resaltarCeldaDestinoObjeto(e, nombreObjeto, lado) {
        document.querySelectorAll('.drag-objeto-hover').forEach(c => c.classList.remove('drag-objeto-hover'));
        document.querySelectorAll('.drag-objeto-baul-hover').forEach(g => g.classList.remove('drag-objeto-baul-hover'));

        if (dragObjState.fantasma) dragObjState.fantasma.style.display = 'none';
        const el = document.elementFromPoint(e.clientX, e.clientY);
        if (dragObjState.fantasma) dragObjState.fantasma.style.display = '';

        if (estaCursorSobreBaul(e, lado)) {
            const gridId = (lado === 'jugador') ? 'objetosVerticalGrid' : 'objetosVerticalGridEnemigo';
            const gridBaul = document.getElementById(gridId);
            if (gridBaul) gridBaul.classList.add('drag-objeto-baul-hover');
            return;
        }

        const cell = el && typeof el.closest === 'function' ? el.closest('.board-cell, .bank-cell') : null;
        if (!cell) return;

        const tipo = cell.dataset.tipo;
        const indice = parseInt(cell.dataset.indice, 10);
        if (isNaN(indice)) return;

        const unidad = obtenerUnidadDeCelda(tipo, indice);
        if (!unidad) return;

        if (dragObjState.origen === 'unidad' &&
            dragObjState.tipoUnidadOrigen === tipo &&
            dragObjState.indiceUnidadOrigen === indice) {
            return;
        }

        if (esDestinoObjetoValido(unidad, nombreObjeto, lado, tipo)) {
            cell.classList.add('drag-objeto-hover');
        }
    }

    // ------------------------------------------------------------
    // INICIAR DRAG DE OBJETO DESDE EL BAÚL
    // ------------------------------------------------------------
    function onPointerDownObjetoDesdeBaul(e, nombre, lado, indexBaul, slot) {
        if (e.button !== undefined && e.button !== 0) return;

        if (typeof objetoSeleccionado !== 'undefined' && objetoSeleccionado) {
            objetoSeleccionado = null;
            if (typeof actualizarObjetosVerticales === 'function') actualizarObjetosVerticales();
            if (typeof actualizarObjetosVerticalesEnemigo === 'function') actualizarObjetosVerticalesEnemigo();
        }

        dragObjState.activo = true;
        dragObjState.nombre = nombre;
        dragObjState.lado = lado;
        dragObjState.origen = 'baul';
        dragObjState.indexBaul = indexBaul;
        dragObjState.tipoUnidadOrigen = null;
        dragObjState.indiceUnidadOrigen = null;
        dragObjState.indexObjetoEquipado = null;
        dragObjState.slotOrigen = slot;
        dragObjState.startX = e.clientX;
        dragObjState.startY = e.clientY;
        dragObjState.umbralSuperado = false;
        dragObjState.pointerId = e.pointerId;

        window.addEventListener('pointermove', onPointerMoveObjeto);
        window.addEventListener('pointerup', onPointerUpObjeto);
        window.addEventListener('pointercancel', onPointerUpObjeto);
    }

    // ------------------------------------------------------------
    // INICIAR DRAG DE OBJETO EQUIPADO
    // ------------------------------------------------------------
    function onPointerDownObjetoEquipado(e, nombre, lado, tipoUnidad, indiceUnidad, indexObjeto, slotIcono) {
        if (e.button !== undefined && e.button !== 0) return;

        if (typeof objetoSeleccionado !== 'undefined' && objetoSeleccionado) {
            objetoSeleccionado = null;
            if (typeof actualizarObjetosVerticales === 'function') actualizarObjetosVerticales();
            if (typeof actualizarObjetosVerticalesEnemigo === 'function') actualizarObjetosVerticalesEnemigo();
        }

        dragObjState.activo = true;
        dragObjState.nombre = nombre;
        dragObjState.lado = lado;
        dragObjState.origen = 'unidad';
        dragObjState.indexBaul = null;
        dragObjState.tipoUnidadOrigen = tipoUnidad;
        dragObjState.indiceUnidadOrigen = indiceUnidad;
        dragObjState.indexObjetoEquipado = indexObjeto;
        dragObjState.slotOrigen = slotIcono;
        dragObjState.startX = e.clientX;
        dragObjState.startY = e.clientY;
        dragObjState.umbralSuperado = false;
        dragObjState.pointerId = e.pointerId;

        window.addEventListener('pointermove', onPointerMoveObjeto);
        window.addEventListener('pointerup', onPointerUpObjeto);
        window.addEventListener('pointercancel', onPointerUpObjeto);
    }

    // ------------------------------------------------------------
    // MOVER
    // ------------------------------------------------------------
    function onPointerMoveObjeto(e) {
        if (!dragObjState.activo) return;
        if (dragObjState.pointerId !== null && e.pointerId !== dragObjState.pointerId) return;

        const dx = e.clientX - dragObjState.startX;
        const dy = e.clientY - dragObjState.startY;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (!dragObjState.umbralSuperado && dist < UMBRAL_DRAG) return;

        if (!dragObjState.umbralSuperado) {
            dragObjState.umbralSuperado = true;
            crearFantasmaObjeto(dragObjState.nombre, e);
            if (dragObjState.slotOrigen) {
                dragObjState.slotOrigen.classList.add('drag-objeto-origen');
            }
            aplicarColoresObjeto(dragObjState.nombre, dragObjState.lado);
            e.preventDefault();
        }

        if (dragObjState.fantasma) {
            dragObjState.fantasma.style.left = (e.clientX - dragObjState.offsetX) + 'px';
            dragObjState.fantasma.style.top = (e.clientY - dragObjState.offsetY) + 'px';
        }

        resaltarCeldaDestinoObjeto(e, dragObjState.nombre, dragObjState.lado);
    }

    // ------------------------------------------------------------
    // SOLTAR
    // ------------------------------------------------------------
    function onPointerUpObjeto(e) {
        if (!dragObjState.activo) return;

        window.removeEventListener('pointermove', onPointerMoveObjeto);
        window.removeEventListener('pointerup', onPointerUpObjeto);
        window.removeEventListener('pointercancel', onPointerUpObjeto);

        const superoUmbral = dragObjState.umbralSuperado;

        if (dragObjState.fantasma) dragObjState.fantasma.remove();
        if (dragObjState.slotOrigen) dragObjState.slotOrigen.classList.remove('drag-objeto-origen');
        document.querySelectorAll('.drag-objeto-hover').forEach(c => c.classList.remove('drag-objeto-hover'));
        document.querySelectorAll('.drag-objeto-baul-hover').forEach(g => g.classList.remove('drag-objeto-baul-hover'));
        limpiarColoresObjeto();

        document.body.classList.remove('dragging-objeto-active');

        if (!superoUmbral) {
            resetEstadoObjeto();
            return;
        }

        const nombre = dragObjState.nombre;
        const lado = dragObjState.lado;
        const origen = dragObjState.origen;
        const indexBaul = dragObjState.indexBaul;
        const tipoOrigen = dragObjState.tipoUnidadOrigen;
        const indiceOrigen = dragObjState.indiceUnidadOrigen;
        const indexObjetoEquipado = dragObjState.indexObjetoEquipado;

        // === ¿SOLTADO SOBRE EL BAÚL? ===
        if (estaCursorSobreBaul(e, lado)) {
            if (origen === 'unidad') {
                bloquearClickSiguiente();
                try {
                    devolverObjetoAlBaul(lado, tipoOrigen, indiceOrigen, indexObjetoEquipado);
                } catch (err) {
                    console.error('❌ Error al devolver objeto al baúl:', err);
                }
            }
            resetEstadoObjeto();
            return;
        }

        // === ¿SOLTADO SOBRE UNA UNIDAD? ===
        const elDestino = document.elementFromPoint(e.clientX, e.clientY);
        const cellDestino = elDestino && typeof elDestino.closest === 'function'
            ? elDestino.closest('.board-cell, .bank-cell')
            : null;

        if (cellDestino) {
            const tipoDestino = cellDestino.dataset.tipo;
            const indiceDestino = parseInt(cellDestino.dataset.indice, 10);

            if (!isNaN(indiceDestino)) {
                const unidadDestino = obtenerUnidadDeCelda(tipoDestino, indiceDestino);

                const esMismaUnidad = (origen === 'unidad' &&
                                       tipoOrigen === tipoDestino &&
                                       indiceOrigen === indiceDestino);

                if (unidadDestino && !esMismaUnidad &&
                    esDestinoObjetoValido(unidadDestino, nombre, lado, tipoDestino)) {

                    bloquearClickSiguiente();

                    try {
                        if (origen === 'baul') {
                            if (lado === 'jugador') {
                                if (typeof equiparObjetoDesdeBaul === 'function') {
                                    equiparObjetoDesdeBaul(indexBaul, tipoDestino, indiceDestino);
                                }
                            } else {
                                if (typeof equiparObjetoAEnemigo === 'function') {
                                    equiparObjetoAEnemigo(indexBaul, tipoDestino, indiceDestino);
                                }
                            }
                        } else {
                            transferirObjetoEntreUnidades(
                                lado,
                                tipoOrigen, indiceOrigen, indexObjetoEquipado,
                                tipoDestino, indiceDestino
                            );
                        }
                    } catch (err) {
                        console.error('❌ Error al soltar objeto:', err);
                    }
                }
            }
        }

        resetEstadoObjeto();
    }

    // ------------------------------------------------------------
    // TRANSFERIR OBJETO ENTRE UNIDADES
    // ------------------------------------------------------------
    function transferirObjetoEntreUnidades(lado, tipoOrigen, indiceOrigen, indexObjeto, tipoDestino, indiceDestino) {
        const unidadOrigen = obtenerUnidadDeCelda(tipoOrigen, indiceOrigen);
        const unidadDestino = obtenerUnidadDeCelda(tipoDestino, indiceDestino);

        if (!unidadOrigen || !unidadDestino) return;
        if (!unidadOrigen.objetos || indexObjeto >= unidadOrigen.objetos.length) return;

        const nombreObjeto = unidadOrigen.objetos[indexObjeto];

        if (!puedeEquiparObjeto(unidadDestino, nombreObjeto)) {
            console.warn('⚠️ Destino no compatible, cancelando transferencia');
            return;
        }

        unidadOrigen.objetos.splice(indexObjeto, 1);
        if (typeof recalcularEfectosObjetos === 'function') {
            recalcularEfectosObjetos(unidadOrigen);
        } else if (typeof unidadOrigen.actualizarStats === 'function') {
            unidadOrigen.actualizarStats();
        }

        if (typeof aplicarObjeto === 'function') {
            aplicarObjeto(unidadDestino, nombreObjeto);
        }

        if (typeof addConsoleMessage === 'function') {
            addConsoleMessage(`📦 ${nombreObjeto} transferido de ${unidadOrigen.pokemon.nombre} → ${unidadDestino.pokemon.nombre}`, 'move');
        }

        if (typeof playUISound === 'function') {
            playUISound('click.mp3', 0.2);
        }

        if (typeof aplicarSinergias === 'function') aplicarSinergias();
        if (lado === 'enemigo' && typeof aplicarSinergiasEnemigo === 'function') aplicarSinergiasEnemigo();
        if (typeof renderizar === 'function') renderizar();
    }

    // ------------------------------------------------------------
    // DEVOLVER OBJETO AL BAÚL (desde unidad)
    // ------------------------------------------------------------
    function devolverObjetoAlBaul(lado, tipoUnidad, indiceUnidad, indexObjeto) {
        const unidad = obtenerUnidadDeCelda(tipoUnidad, indiceUnidad);
        if (!unidad) return;
        if (!unidad.objetos || indexObjeto >= unidad.objetos.length) return;

        const baul = getBaul(lado);
        const maxBaul = (typeof CONFIG !== 'undefined' && CONFIG.MAX_BAUL) ? CONFIG.MAX_BAUL : 8;

        if (baul.length >= maxBaul) {
            if (typeof addConsoleMessage === 'function') {
                addConsoleMessage(`❌ Baúl lleno! No se puede devolver el objeto.`, 'error');
            }
            return;
        }

        const nombreObjeto = unidad.objetos[indexObjeto];

        unidad.objetos.splice(indexObjeto, 1);
        if (typeof recalcularEfectosObjetos === 'function') {
            recalcularEfectosObjetos(unidad);
        } else if (typeof unidad.actualizarStats === 'function') {
            unidad.actualizarStats();
        }

        baul.push(nombreObjeto);

        if (typeof addConsoleMessage === 'function') {
            addConsoleMessage(`🔄 ${nombreObjeto} devuelto al baúl desde ${unidad.pokemon.nombre}`, 'move');
        }

        if (typeof playUISound === 'function') {
            playUISound('click.mp3', 0.2);
        }

        if (typeof aplicarSinergias === 'function') aplicarSinergias();
        if (lado === 'enemigo' && typeof aplicarSinergiasEnemigo === 'function') aplicarSinergiasEnemigo();
        if (typeof actualizarBadgeBaul === 'function') actualizarBadgeBaul();
        if (typeof actualizarObjetosVerticales === 'function') actualizarObjetosVerticales();
        if (typeof actualizarObjetosVerticalesEnemigo === 'function') actualizarObjetosVerticalesEnemigo();
        if (typeof renderizar === 'function') renderizar();
    }

    // ------------------------------------------------------------
    // EVITAR CLICK DESPUÉS DE DRAG
    // ------------------------------------------------------------
    function bloquearClickSiguiente() {
        const handler = function (e) {
            e.stopPropagation();
            e.preventDefault();
            window.removeEventListener('click', handler, true);
        };
        window.addEventListener('click', handler, true);
        setTimeout(() => window.removeEventListener('click', handler, true), 350);
    }

    // ------------------------------------------------------------
    // RESET
    // ------------------------------------------------------------
    function resetEstadoObjeto() {
        dragObjState.activo = false;
        dragObjState.nombre = null;
        dragObjState.lado = null;
        dragObjState.origen = null;
        dragObjState.indexBaul = null;
        dragObjState.tipoUnidadOrigen = null;
        dragObjState.indiceUnidadOrigen = null;
        dragObjState.indexObjetoEquipado = null;
        dragObjState.slotOrigen = null;
        dragObjState.fantasma = null;
        dragObjState.offsetX = 0;
        dragObjState.offsetY = 0;
        dragObjState.startX = 0;
        dragObjState.startY = 0;
        dragObjState.umbralSuperado = false;
        dragObjState.pointerId = null;
        document.body.classList.remove('dragging-objeto-active');
    }

    // ------------------------------------------------------------
    // ENGANCHAR DRAG A UN SLOT DEL BAÚL
    // ------------------------------------------------------------
    function engancharDragObjeto(slot, nombre, lado, indexBaul) {
        if (!slot) return;
        if (slot.dataset.dragObjetoEnganchado === '1') return;
        slot.dataset.dragObjetoEnganchado = '1';

        slot.addEventListener('pointerdown', function (e) {
            if (!nombre) return;
            onPointerDownObjetoDesdeBaul(e, nombre, lado, indexBaul, slot);
        });
    }

    // ------------------------------------------------------------
    // ENGANCHAR DRAG A UN ICONO DE OBJETO EQUIPADO
    // ------------------------------------------------------------
    function engancharDragObjetoEquipado(icono, nombre, lado, tipoUnidad, indiceUnidad, indexObjeto) {
        if (!icono) return;
        if (icono.dataset.dragObjetoEqEnganchado === '1') return;
        icono.dataset.dragObjetoEqEnganchado = '1';

        icono.addEventListener('pointerdown', function (e) {
            // 🛡️ Evitar que el drag de la UNIDAD se dispare al pulsar el objeto
            e.stopPropagation();
            if (e.stopImmediatePropagation) e.stopImmediatePropagation();
            // ❌ v3: NO llamar e.preventDefault() aquí. Rompía el click
            // de desequipar en algunos navegadores.

            if (!nombre) return;
            onPointerDownObjetoEquipado(e, nombre, lado, tipoUnidad, indiceUnidad, indexObjeto, icono);
        });
    }

    // ============================================================
    // 📦 REFRESCAR DRAGS DE OBJETOS EQUIPADOS
    // ============================================================
    // v3: lee el nombre e índice REALES del dataset del icono.
    //     Antes usaba el índice del DOM, que no coincidía con
    //     unidad.objetos[] cuando había huecos (1 normal + disco).
    // ============================================================
    function _refrescarUnaCelda(cell, tipoCelda, indice) {
        const unidad = obtenerUnidadDeCelda(tipoCelda, indice);
        if (!unidad || !unidad.objetos || unidad.objetos.length === 0) return;

        // Solo iconos con datos reales de objeto (no vacíos, no slot-ulti vacío)
        const selectorIconos = tipoCelda === 'tablero' || tipoCelda === 'enemigo'
            ? '.objeto-equipado-tablero:not(.vacio)'
            : '.objeto-equipado-banquillo:not(.vacio)';

        cell.querySelectorAll(selectorIconos).forEach((icono) => {
            // Saltar el slot de ULTI vacío
            if (icono.classList.contains('slot-ulti') && icono.classList.contains('vacio')) return;

            const nombre = icono.dataset.objetoNombre;
            const objIdxRaw = icono.dataset.objetoIndex;
            const objIdx = (objIdxRaw !== undefined) ? parseInt(objIdxRaw, 10) : -1;

            // Si el dataset no tiene la info, intentar sacarla por fallback
            // (por compatibilidad con renders antiguos sin data-attributes)
            if (!nombre || isNaN(objIdx) || objIdx < 0) {
                return;
            }

            // Verificar que el objeto realmente existe en la unidad
            if (!unidad.objetos[objIdx] || unidad.objetos[objIdx] !== nombre) {
                // El índice no cuadra: buscar por nombre la primera coincidencia
                const idxReal = unidad.objetos.indexOf(nombre);
                if (idxReal === -1) return;
                icono.removeAttribute('onclick');
                icono.style.cursor = 'grab';
                engancharDragObjetoEquipado(icono, nombre, 
                    (tipoCelda === 'enemigo' || tipoCelda === 'enemigoBanquillo') ? 'enemigo' : 'jugador',
                    tipoCelda, indice, idxReal);
                return;
            }

            icono.removeAttribute('onclick');
            icono.style.cursor = 'grab';

            engancharDragObjetoEquipado(icono, nombre,
                (tipoCelda === 'enemigo' || tipoCelda === 'enemigoBanquillo') ? 'enemigo' : 'jugador',
                tipoCelda, indice, objIdx);
        });
    }

    function refrescarDragObjetosEquipados() {
        // --- Tablero jugador ---
        document.querySelectorAll('#playerBoard .board-cell').forEach(cell => {
            const idx = parseInt(cell.dataset.indice, 10);
            if (isNaN(idx)) return;
            _refrescarUnaCelda(cell, 'tablero', idx);
        });

        // --- Banquillo jugador ---
        document.querySelectorAll('#banquilloGrid .bank-cell').forEach(cell => {
            const idx = parseInt(cell.dataset.indice, 10);
            if (isNaN(idx)) return;
            _refrescarUnaCelda(cell, 'banquillo', idx);
        });

        // --- Tablero enemigo (solo modo creativo) ---
        document.querySelectorAll('#enemigoBoard .board-cell').forEach(cell => {
            const idx = parseInt(cell.dataset.indice, 10);
            if (isNaN(idx)) return;
            _refrescarUnaCelda(cell, 'enemigo', idx);
        });

        // --- Banquillo enemigo (solo modo creativo) ---
        document.querySelectorAll('#enemyBanquilloGrid .bank-cell').forEach(cell => {
            const idx = parseInt(cell.dataset.indice, 10);
            if (isNaN(idx)) return;
            _refrescarUnaCelda(cell, 'enemigoBanquillo', idx);
        });
    }

    // ------------------------------------------------------------
    // INIT
    // ------------------------------------------------------------
    function initDragObjetos() {
        console.log('📦 DragDrop de Objetos inicializado (v3 - FIX índice real)');

        document.addEventListener('dragstart', function (e) {
            if (!e.target || typeof e.target.closest !== 'function') return;

            if (e.target.closest('.objeto-slot-vertical, .drag-objeto-ghost, .objetos-equipados, .objeto-equipado-tablero, .objeto-equipado-banquillo')) {
                e.preventDefault();
                return false;
            }
        }, true);

        document.addEventListener('selectstart', function (e) {
            if (!e.target || typeof e.target.closest !== 'function') return;

            if (e.target.closest('.objeto-slot-vertical, .drag-objeto-ghost, .objetos-equipados, .objeto-equipado-tablero, .objeto-equipado-banquillo')) {
                e.preventDefault();
                return false;
            }
        }, true);
    }

    // ------------------------------------------------------------
    // EXPONER GLOBALMENTE
    // ------------------------------------------------------------
    window.initDragObjetos = initDragObjetos;
    window.engancharDragObjeto = engancharDragObjeto;
    window.engancharDragObjetoEquipado = engancharDragObjetoEquipado;
    window.refrescarDragObjetosEquipados = refrescarDragObjetosEquipados;

    console.log('✅ dragObjetos.js cargado (v3 - FIX índice real de objetos)');
})();
;

/* ==================== js/ui/ajustes.js ==================== */
// ============================================================
// UI - AJUSTES (⚙️)
// ============================================================
// Modal de ajustes con:
//   - Slider de volumen de música
//   - Slider de volumen de efectos
//   - Botón "Volver al menú principal"
//
// Los volúmenes se aplican en tiempo real y se guardan en
// localStorage para que persistan entre partidas.
// ============================================================

// ============================================================
// ESTADO
// ============================================================
let ajustesAbiertos = false;

// Valores por defecto
const VOLUMEN_MUSICA_DEFAULT = 50;
const VOLUMEN_EFECTOS_DEFAULT = 50;

// ============================================================
// INICIALIZAR
// ============================================================
function initAjustes() {
    console.log('⚙️ Inicializando ajustes...');

    const overlay = document.getElementById('ajustesOverlay');
    const btnAjustes = document.getElementById('btnAjustes');
    const btnCerrar = document.getElementById('btnCerrarAjustes');
    const btnVolverMenu = document.getElementById('btnVolverMenuAjustes');
    const sliderMusica = document.getElementById('sliderVolumenMusica');
    const sliderEfectos = document.getElementById('sliderVolumenEfectos');
    const valorMusica = document.getElementById('valorVolumenMusica');
    const valorEfectos = document.getElementById('valorVolumenEfectos');

    if (!overlay || !btnAjustes || !sliderMusica || !sliderEfectos) {
        console.warn('⚠️ ajustes.js: faltan elementos en el DOM');
        return;
    }

    // ============================================================
    // Cargar volúmenes guardados
    // ============================================================
    let volMusica = VOLUMEN_MUSICA_DEFAULT;
    let volEfectos = VOLUMEN_EFECTOS_DEFAULT;

    try {
        const m = localStorage.getItem('volumenMusica');
        if (m !== null && !isNaN(parseFloat(m))) volMusica = parseFloat(m);
        const e = localStorage.getItem('volumenEfectos');
        if (e !== null && !isNaN(parseFloat(e))) volEfectos = parseFloat(e);
    } catch (err) {}

    sliderMusica.value = volMusica;
    sliderEfectos.value = volEfectos;
    valorMusica.textContent = volMusica + '%';
    valorEfectos.textContent = volEfectos + '%';

    // Aplicar al audio
    aplicarVolumenMusica(volMusica);
    aplicarVolumenEfectos(volEfectos);

    // ============================================================
    // Abrir / cerrar
    // ============================================================
    btnAjustes.addEventListener('click', function (e) {
        e.stopPropagation();
        abrirAjustes();
    });

    if (btnCerrar) {
        btnCerrar.addEventListener('click', function (e) {
            e.stopPropagation();
            cerrarAjustes();
        });
    }

    // Click fuera del modal cierra
    overlay.addEventListener('click', function (e) {
        if (e.target === overlay) {
            cerrarAjustes();
        }
    });

    // ESC cierra
    document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape' && ajustesAbiertos) {
            cerrarAjustes();
            e.preventDefault();
        }
    });

    // ============================================================
    // Sliders
    // ============================================================
    sliderMusica.addEventListener('input', function () {
        const val = parseInt(this.value, 10);
        valorMusica.textContent = val + '%';
        aplicarVolumenMusica(val);
        try { localStorage.setItem('volumenMusica', val); } catch (err) {}
    });

    sliderEfectos.addEventListener('input', function () {
        const val = parseInt(this.value, 10);
        valorEfectos.textContent = val + '%';
        aplicarVolumenEfectos(val);
        try { localStorage.setItem('volumenEfectos', val); } catch (err) {}
    });

    // ============================================================
    // Volver al menú principal
    // ============================================================
    if (btnVolverMenu) {
        btnVolverMenu.addEventListener('click', function (e) {
            e.stopPropagation();
            volverAlMenuDesdeAjustes();
        });
    }

    console.log('✅ Ajustes inicializados');
}

// ============================================================
// ABRIR / CERRAR
// ============================================================
function abrirAjustes() {
    const overlay = document.getElementById('ajustesOverlay');
    if (!overlay) return;

    // Cerrar otros modales si están abiertos
    if (typeof tiendaAbierta !== 'undefined' && tiendaAbierta) {
        if (typeof cerrarTienda === 'function') cerrarTienda();
    }
    if (typeof cartaAbierta !== 'undefined' && cartaAbierta) {
        if (typeof cerrarCarta === 'function') cerrarCarta();
    }
    if (typeof panelDatosCombateAbierto !== 'undefined' && panelDatosCombateAbierto) {
        if (typeof cerrarPanelDatosCombate === 'function') cerrarPanelDatosCombate();
    }
    if (typeof cartaSinergiaAbierta !== 'undefined' && cartaSinergiaAbierta) {
        if (typeof cerrarCartaSinergia === 'function') cerrarCartaSinergia();
    }

    ajustesAbiertos = true;
    overlay.style.display = 'flex';

    if (typeof playButtonSound === 'function') playButtonSound();
}

function cerrarAjustes() {
    const overlay = document.getElementById('ajustesOverlay');
    if (!overlay) return;
    ajustesAbiertos = false;
    overlay.style.display = 'none';
}

// ============================================================
// APLICAR VOLÚMENES
// ============================================================
// La música de preparación (fondoPreparacionAudio) está en main.js
// Los efectos (uiAudioCache, combateAudioActual, etc.) también.
// Aquí tocamos las variables globales que existan.

function aplicarVolumenMusica(porcentaje) {
    // 🆕 Factor de escala: el slider marca más de lo que suena
    //    Slider 50% → volumen real 0.20 (igual que antes al 20%)
    //    Slider 100% → volumen real 0.40
    const FACTOR_MUSICA = 0.4;
    const volSlider = Math.max(0, Math.min(1, porcentaje / 100));
    const vol = volSlider * FACTOR_MUSICA;

    // Música de preparación
    if (typeof fondoPreparacionAudio !== 'undefined' && fondoPreparacionAudio) {
        fondoPreparacionAudio.volume = vol;
    }

    // Música de evolución (si suena)
    if (typeof _evolucionAudioActual !== 'undefined' && _evolucionAudioActual) {
        _evolucionAudioActual.volume = vol * 0.9;
    }

    // 🆕 Música de combate (combate.mp3)
    //    Aquí el factor 0.18 ya está incluido en el volumen base
    if (typeof combateAudioActual !== 'undefined' && combateAudioActual) {
        combateAudioActual.volume = vol * 0.9;
    }

    // 🆕 También el audio cacheado de combate.mp3
    if (typeof uiAudioCache !== 'undefined' && uiAudioCache) {
        const urlCombate = (typeof CONFIG !== 'undefined' && CONFIG.UI_SOUND_URL)
            ? CONFIG.UI_SOUND_URL + 'combate.mp3'
            : null;
        if (urlCombate && uiAudioCache[urlCombate]) {
            uiAudioCache[urlCombate].volume = vol * 0.9;
        }
    }

    // Guardar el volumen real (no el del slider) para futuros audios
    window._volumenMusicaActual = vol;
    window._volumenMusicaSlider = volSlider;
}

function aplicarVolumenEfectos(porcentaje) {
    const vol = Math.max(0, Math.min(1, porcentaje / 100));

        // Audios de UI ya cacheados
    if (typeof uiAudioCache !== 'undefined' && uiAudioCache) {
        // 🆕 Excluir combate.mp3 (lo controla el slider de música)
        const urlCombate = (typeof CONFIG !== 'undefined' && CONFIG.UI_SOUND_URL)
            ? CONFIG.UI_SOUND_URL + 'combate.mp3'
            : null;

        for (let url in uiAudioCache) {
            if (url === urlCombate) continue;  // 🆕 saltar la música de combate

            if (uiAudioCache[url] && uiAudioCache[url].volume !== undefined) {
                if (uiAudioCache[url].volume > 0) {
                    uiAudioCache[url].volume = vol;
                }
            }
        }
    }

        // Audios de movimientos cacheados
    if (typeof movimientoAudioCache !== 'undefined' && movimientoAudioCache) {
        for (let url in movimientoAudioCache) {
            if (movimientoAudioCache[url] && movimientoAudioCache[url].volume !== undefined) {
                if (movimientoAudioCache[url].volume > 0) {
                    movimientoAudioCache[url].volume = vol * 0.4;
                }
            }
        }
    }

    // Guardar el volumen para futuros audios de efectos
    window._volumenEfectosActual = vol;
}

// ============================================================
// VOLVER AL MENÚ PRINCIPAL (Vista de Tarjetas)
// ============================================================
function volverAlMenuDesdeAjustes() {
    if (!confirm('¿Seguro que quieres volver al menú principal? Perderás el progreso de la partida actual.')) {
        return;
    }

    cerrarAjustes();

    const menu = document.getElementById('menuPrincipal');
    const juego = document.getElementById('juegoContainer');

    if (menu) menu.style.display = 'flex';
    if (juego) juego.style.display = 'none';

    // 🆕 Forzar la vista de MENÚ PRINCIPAL (tarjetas), no la de selección
    const vistaMenu = document.getElementById('vistaMenu');
    const vistaSeleccion = document.getElementById('vistaSeleccion');
    if (vistaMenu) vistaMenu.classList.add('activa');
    if (vistaSeleccion) vistaSeleccion.classList.remove('activa');

    if (typeof detenerCronometroPartida === 'function') {
        detenerCronometroPartida();
    }

    if (typeof reiniciarJuego === 'function') {
        reiniciarJuego();
    }

    // 🗺️ Restaurar el fondo del menú a un mapa desbloqueado
    if (window.LogrosUI && typeof LogrosUI.actualizarMapSelector === 'function') {
        LogrosUI.actualizarMapSelector();
    }

    if (typeof resetMusicaPreparacion === 'function') {
    resetMusicaPreparacion();
} else if (typeof pausarFondoPreparacion === 'function') {
    pausarFondoPreparacion();
}
}

// ============================================================
// EXPONER GLOBALMENTE
// ============================================================
window.initAjustes = initAjustes;
window.abrirAjustes = abrirAjustes;
window.cerrarAjustes = cerrarAjustes;
window.aplicarVolumenMusica = aplicarVolumenMusica;
window.aplicarVolumenEfectos = aplicarVolumenEfectos;

// ============================================================
// AUTO-INIT
// ============================================================
if (document.readyState === 'complete' || document.readyState === 'interactive') {
    setTimeout(initAjustes, 100);
} else {
    document.addEventListener('DOMContentLoaded', function () {
        setTimeout(initAjustes, 100);
    });
}

;

/* ==================== js/creative/creativePanel.js ==================== */
// ============================================================
// MODO CREATIVO - FASES A + B + C + D + LAYOUT MEJORADO
// + SELECTOR DE LADO PARA OBJETOS (JUGADOR / ENEMIGO)
// ============================================================

let panelCreativoAbierto = false;
let filtroCreative = {
    pokemonJugador: { texto: '', tipo: 'todos', coste: 'todos' },
    pokemonEnemigo: { texto: '', tipo: 'todos', coste: 'todos' },
    objetos: { texto: '', tipo: 'todos' }
};

// ⬅️ NUEVO: lado activo para objetos ('jugador' o 'enemigo')
let ladoObjetosActivo = 'jugador';

// ============================================================
// ABRIR / CERRAR PANEL
// ============================================================

function abrirPanelCreativo() {
    if (!window.modoCreativo) {
        addConsoleMessage('❌ El modo creativo no está activado', 'error');
        return;
    }
    
    let panel = document.getElementById('creativePanel');
    if (!panel) {
        panel = document.createElement('div');
        panel.id = 'creativePanel';
        panel.className = 'creative-panel';
        panel.innerHTML = construirHtmlPanel();
        document.body.appendChild(panel);
        conectarEventosPanel();
    }
    
    panel.style.display = 'flex';
    panelCreativoAbierto = true;
    renderizarContenidoPanel();
}

function cerrarPanelCreativo() {
    const panel = document.getElementById('creativePanel');
    if (panel) panel.style.display = 'none';
    panelCreativoAbierto = false;
}

function togglePanelCreativo() {
    if (panelCreativoAbierto) {
        cerrarPanelCreativo();
    } else {
        abrirPanelCreativo();
    }
}

// ============================================================
// HTML DEL PANEL
// ============================================================

function construirHtmlPanel() {
        return `
        <div class="creative-modal">
            <div class="creative-header">
                <span class="creative-titulo">🧪 MODO CREATIVO - Laboratorio</span>
                <button class="creative-cerrar" id="creativeBtnCerrar">✕</button>
            </div>

            <!-- 🆕 SELECTOR DE RIVAL PARA LA IA -->
            <div class="creative-tabs" style="margin-top: 10px;">
                <select id="creativeSelectRival" class="creative-select" style="width: 100%; max-width: 300px; margin: 0 auto; display: block;">
                    <option value="">🤖 Rival Aleatorio (por defecto)</option>
                </select>
            </div>

            <div class="creative-tabs">
                <button class="creative-tab active" data-tab="pokemon">🐾 Mi Pokémon</button>
                <button class="creative-tab" data-tab="enemigo">👹 Enemigo</button>
                <button class="creative-tab" data-tab="objetos">📦 Objetos</button>
            </div>

            <div class="creative-contenido" id="creativeContenido">
                <!-- El contenido se rellena por JS -->
            </div>

            <div class="creative-acciones">
                <div class="creative-acciones-titulo">⚡ ACCIONES RÁPIDAS</div>
                <div class="creative-acciones-grid">
                    <button class="creative-btn" id="creativeBtn3Estrellas">⭐ Poner 3★</button>
                    <button class="creative-btn" id="creativeBtnLimpiar">🧹 Limpiar todo</button>
                    <button class="creative-btn" id="creativeBtnOro">💰 +100 oro</button>
                    <button class="creative-btn" id="creativeBtnNivelMax">⬆️ Nivel máximo</button>
                    <button class="creative-btn" id="creativeBtnRonda">🎲 Ronda +1</button>
                    <button class="creative-btn" id="creativeBtnReset">🗑️ Reset completo</button>
                </div>
            </div>

            <div class="creative-footer">
                <button class="creative-btn-combatir" id="creativeBtnCombatir">▶️ COMBATIR</button>
            </div>
        </div>
    `;
}

// ============================================================
// CONECTAR EVENTOS DEL PANEL
// ============================================================

function conectarEventosPanel() {
    document.getElementById('creativeBtnCerrar')?.addEventListener('click', cerrarPanelCreativo);
    document.getElementById('creativeBtn3Estrellas')?.addEventListener('click', accionPoner3Estrellas);
    document.getElementById('creativeBtnLimpiar')?.addEventListener('click', accionLimpiarTodo);
    document.getElementById('creativeBtnOro')?.addEventListener('click', accionDarOro);
    document.getElementById('creativeBtnNivelMax')?.addEventListener('click', accionNivelMaximo);
    document.getElementById('creativeBtnRonda')?.addEventListener('click', accionAvanzarRonda);
    document.getElementById('creativeBtnReset')?.addEventListener('click', () => accionResetCompleto(false));
    document.getElementById('creativeBtnCombatir')?.addEventListener('click', accionCombatir);
    
        document.querySelectorAll('.creative-tab').forEach(tab => {
        tab.addEventListener('click', function() {
            document.querySelectorAll('.creative-tab').forEach(t => t.classList.remove('active'));
            this.classList.add('active');
            renderizarContenidoPanel();
        });
    });

    // 🆕 RELLENAR Y CONECTAR SELECTOR DE RIVALES
    const selectRival = document.getElementById('creativeSelectRival');
    if (selectRival && typeof window.RIVALES_INFO !== 'undefined') {
        window.RIVALES_INFO.forEach(rival => {
            const opt = document.createElement('option');
            opt.value = rival.nombre;
            opt.textContent = `🎭 ${rival.nombre} (${rival.estrategia.descripcion})`;
            selectRival.appendChild(opt);
        });

        if (window._rivalForzado) {
            selectRival.value = window._rivalForzado;
        }

        selectRival.addEventListener('change', function() {
            const nombreRival = this.value;
            if (!nombreRival) {
                window._rivalForzado = null;
                if (typeof addConsoleMessage === 'function') addConsoleMessage(`🎲 Rival aleatorio para el próximo combate`, 'info');
                return;
            }

                        const rivalData = window.RIVALES_INFO.find(r => r.nombre === nombreRival);
            if (rivalData) {
                window._rivalForzado = nombreRival;
                window.rivalActual = rivalData;
                
                // 1. ACTUALIZAR INTERFAZ (Nombre y Avatar)
                const enemyNameEl = document.getElementById("enemyName");
                const enemyAvatarEl = document.getElementById("enemyAvatar");
                
                if (enemyNameEl) enemyNameEl.textContent = rivalData.nombre;
                if (enemyAvatarEl) {
                    enemyAvatarEl.innerHTML = '';
                    const img = document.createElement('img');
                    img.src = `assets/avatars/rivales/${rivalData.avatar}.webp`;
                    img.alt = rivalData.nombre;
                    img.onerror = function() { this.style.display = 'none'; enemyAvatarEl.textContent = '👤'; };
                    enemyAvatarEl.appendChild(img);
                }

                // 2. REINICIAR EQUIPO ENEMIGO
                if (typeof enemyBoard !== 'undefined' && typeof enemyBanquillo !== 'undefined') {
                    for (let i = 0; i < enemyBoard.length; i++) enemyBoard[i] = null;
                    for (let i = 0; i < enemyBanquillo.length; i++) enemyBanquillo[i] = null;
                }

                // 3. APLICAR ESTRATEGIA Y TERRENO
                if (typeof enemyElegirEstrategia === 'function') enemyElegirEstrategia();
                if (typeof cambiarTerrenoPorRival === 'function') cambiarTerrenoPorRival(rivalData);

                // 4. GENERAR POKÉMON INICIAL PARA EL NUEVO RIVAL
                if (typeof elegirPokemonInicialEnemigo === 'function' && typeof Unidad !== 'undefined') {
                    let pokemonEnemigo = elegirPokemonInicialEnemigo();
                    if (pokemonEnemigo && typeof consumirDelPool === 'function') {
                        if (consumirDelPool(pokemonEnemigo.id)) {
                            const rolEnemigo = typeof rolColocacionDesdePokemonData === 'function' 
                                ? rolColocacionDesdePokemonData(pokemonEnemigo) 
                                : 'melee';
                            
                            const mejorPos = typeof obtenerIndiceColocacionInicial === 'function' 
                                ? obtenerIndiceColocacionInicial('enemy', rolEnemigo, 0) 
                                : 0;

                            const nuevaUnidad = new Unidad(pokemonEnemigo, 1, pokemonEnemigo.id, pokemonEnemigo.coste);
                            nuevaUnidad.equipo = 'enemy';
                            enemyBoard[mejorPos] = nuevaUnidad;
                            
                            // Quitar de la tienda enemiga si por lo que sea estaba ahí
                            if (typeof enemyTienda !== 'undefined') {
                                let idxTienda = enemyTienda.findIndex(p => p && p.id === pokemonEnemigo.id);
                                if (idxTienda !== -1) enemyTienda.splice(idxTienda, 1);
                            }

                            if (typeof addConsoleMessage === 'function') {
                                addConsoleMessage(`🎁 ${rivalData.nombre} empieza con ${pokemonEnemigo.nombre}`, 'enemy');
                            }
                        }
                    }
                }
                
                // 5. REFRESCAR EL TABLERO VISUALMENTE
                if (typeof renderizar === 'function') renderizar();

                if (typeof addConsoleMessage === 'function') {
                    addConsoleMessage(`🎭 Rival seleccionado: ${nombreRival} (${rivalData.estrategia.descripcion})`, 'enemy');
                }
            }
        });
    }
}

// ============================================================
// RENDERIZAR CONTENIDO SEGÚN LA PESTAÑA ACTIVA
// ============================================================

function renderizarContenidoPanel() {
    const contenedor = document.getElementById('creativeContenido');
    if (!contenedor) return;
    
    const tabActiva = document.querySelector('.creative-tab.active')?.dataset.tab || 'pokemon';
    
    if (tabActiva === 'pokemon') {
        contenedor.innerHTML = construirCatalogoPokemon('jugador');
        conectarEventosCatalogo('jugador');
    } else if (tabActiva === 'enemigo') {
        contenedor.innerHTML = construirCatalogoPokemon('enemigo');
        conectarEventosCatalogo('enemigo');
    } else if (tabActiva === 'objetos') {
        contenedor.innerHTML = construirCatalogoObjetos();
        conectarEventosCatalogoObjetos();
    }
}

// ============================================================
// CATÁLOGO DE POKÉMON (jugador o enemigo)
// ============================================================

function construirCatalogoPokemon(destino) {
    const filtro = filtroCreative[destino === 'jugador' ? 'pokemonJugador' : 'pokemonEnemigo'];
    
    const todos = (typeof TODOS_POKEMONS !== 'undefined' && TODOS_POKEMONS.length > 0)
        ? TODOS_POKEMONS
        : (typeof POKEMONS !== 'undefined' ? POKEMONS : []);
    
    let lista = todos.filter(p => {
        if (filtro.texto && !p.nombre.toLowerCase().includes(filtro.texto.toLowerCase())) return false;
        if (filtro.coste !== 'todos' && p.coste !== parseInt(filtro.coste)) return false;
        if (filtro.tipo !== 'todos') {
            const coincideTipo = p.tipos && p.tipos.some(t => t === filtro.tipo);
            const coincideClase = p.clase === filtro.tipo;
            if (!coincideTipo && !coincideClase) return false;
        }
        return true;
    });
    
    lista.sort((a, b) => {
        if ((a.coste || 0) !== (b.coste || 0)) return (a.coste || 0) - (b.coste || 0);
        return a.nombre.localeCompare(b.nombre);
    });
    
    const listaActual = destino === 'jugador' ? tablero : enemyBoard;
    const banquilloActual = destino === 'jugador' ? banquillo : enemyBanquillo;
    const maxUnidades = destino === 'jugador' 
        ? (typeof maxUnidadesTablero === 'function' ? maxUnidadesTablero() : 6)
        : (typeof maxEnemyUnits === 'function' ? maxEnemyUnits() : 6);
    
    // 🆕 Sinergias ordenadas alfabéticamente (ignorando tildes)
    const TIPOS_ORDENADOS = ['Fuego','Agua','Planta','Eléctrico','Psíquico','Siniestro','Hada','Fantasma','Lucha','Veneno','Hielo','Dragón','Roca','Normal','Volador','Acero','Eevee']
        .slice()
        .sort((a, b) => a.localeCompare(b, 'es', { sensitivity: 'base' }));
    
    const CLASES_ORDENADAS = ['Equilibrado','Atacante','At. Especial','Movimiento','Ágil','Defensa','Auxiliar']
        .slice()
        .sort((a, b) => a.localeCompare(b, 'es', { sensitivity: 'base' }));
    
    let html = `
        <div class="creative-catalogo-header">
            <input type="text" class="creative-input" id="creativeBuscar-${destino}" 
                   placeholder="🔍 Buscar Pokémon..." 
                   value="${filtro.texto}">
            <select class="creative-select" id="creativeTipo-${destino}">
                <option value="todos">⚔️ Todas las sinergias</option>
                <optgroup label="Tipos">
                    ${TIPOS_ORDENADOS.map(t => 
                        `<option value="${t}" ${filtro.tipo === t ? 'selected' : ''}>${t}</option>`
                    ).join('')}
                </optgroup>
                <optgroup label="Clases">
                    ${CLASES_ORDENADAS.map(c => 
                        `<option value="${c}" ${filtro.tipo === c ? 'selected' : ''}>${c}</option>`
                    ).join('')}
                </optgroup>
            </select>
            <select class="creative-select" id="creativeCoste-${destino}">
                <option value="todos">💰 Todos los costes</option>
                ${[1,2,3,4,5].map(c => 
                    `<option value="${c}" ${filtro.coste == c ? 'selected' : ''}>⭐ Coste ${c}</option>`
                ).join('')}
            </select>
        </div>
        
        <div class="creative-estado">
            <span>📍 Tablero: <strong>${listaActual.filter(u => u).length}/${maxUnidades}</strong></span>
            <span>🎒 Banco: <strong>${banquilloActual.filter(u => u).length}/${CONFIG.BANQUILLO_MAXIMO}</strong></span>
            <span>📊 Resultados: <strong>${lista.length}</strong></span>
        </div>
        
        <div class="creative-grid" id="creativeGrid-${destino}">
    `;
    
    if (lista.length === 0) {
        html += `<div class="creative-vacio">No hay Pokémon que coincidan con los filtros</div>`;
    } else {
        for (let p of lista) {
            const spriteId = p.spriteId || p.id;
            const spriteUrl = typeof getSpriteUrl === 'function' 
                ? getSpriteUrl(spriteId, p.nombre) 
                : '';
            const escalaSprite = typeof getSpriteScale === 'function' ? getSpriteScale(spriteId) : 1;
            const offsetXSprite = typeof getSpriteOffsetX === 'function' ? getSpriteOffsetX(spriteId) : '0px';
            const coste = p.coste || 1;
            
            let tiposHtml = '';
            if (p.tipos) {
                tiposHtml = p.tipos.map(t => {
                    const icon = typeof getIconoTipo === 'function' ? getIconoTipo(t) : t;
                    return `<span class="creative-tipo-icon" title="${t}">${icon}</span>`;
                }).join('');
            }
            if (p.clase) {
                const icon = typeof getIconoClase === 'function' ? getIconoClase(p.clase) : p.clase;
                tiposHtml += `<span class="creative-tipo-icon" title="${p.clase}">${icon}</span>`;
            }
            
            html += `
                <div class="creative-card cost-${coste}" data-nombre="${p.nombre}" data-destino="${destino}">
                    <div class="creative-card-tipos">${tiposHtml}</div>
                    <div class="creative-card-coste">💰 ${coste}</div>
                    <img class="creative-card-sprite" src="${spriteUrl}" alt="${p.nombre}" style="--sprite-scale: ${escalaSprite}; --sprite-offset-x: ${offsetXSprite}" onerror="this.style.display='none'">
                    <div class="creative-card-nombre">${p.nombre}</div>
                </div>
            `;
        }
    }
    
    html += `</div>`;
    return html;
}

function conectarEventosCatalogo(destino) {
    const filtroKey = destino === 'jugador' ? 'pokemonJugador' : 'pokemonEnemigo';
    const input = document.getElementById(`creativeBuscar-${destino}`);
    const selectTipo = document.getElementById(`creativeTipo-${destino}`);
    const selectCoste = document.getElementById(`creativeCoste-${destino}`);
    const grid = document.getElementById(`creativeGrid-${destino}`);
    
    if (input) {
        input.addEventListener('input', function() {
            filtroCreative[filtroKey].texto = this.value;
            renderizarContenidoPanel();
        });
    }
    if (selectTipo) {
        selectTipo.addEventListener('change', function() {
            filtroCreative[filtroKey].tipo = this.value;
            renderizarContenidoPanel();
        });
    }
    if (selectCoste) {
        selectCoste.addEventListener('change', function() {
            filtroCreative[filtroKey].coste = this.value;
            renderizarContenidoPanel();
        });
    }
    
    if (grid) {
        grid.querySelectorAll('.creative-card').forEach(card => {
            card.addEventListener('click', function() {
                const nombre = this.dataset.nombre;
                creativeAñadirPokemon(nombre, destino);
            });
        });
    }
}

// ============================================================
// AÑADIR POKÉMON AL TABLERO
// ============================================================

function creativeAñadirPokemon(nombrePokemon, destino) {
    if (combatiendo) {
        addConsoleMessage('⛔ No puedes añadir Pokémon durante el combate', 'error');
        return;
    }
    
    const data = (typeof TODOS_POKEMONS !== 'undefined' ? TODOS_POKEMONS : POKEMONS)
        .find(p => p.nombre === nombrePokemon);
    
    if (!data) {
        addConsoleMessage(`❌ No se encontró ${nombrePokemon}`, 'error');
        return;
    }
    
    const listaTablero = destino === 'jugador' ? tablero : enemyBoard;
    const listaBanquillo = destino === 'jugador' ? banquillo : enemyBanquillo;
    const maxUnidades = destino === 'jugador' 
        ? (typeof maxUnidadesTablero === 'function' ? maxUnidadesTablero() : 6)
        : (typeof maxEnemyUnits === 'function' ? maxEnemyUnits() : 6);
    
    let hueco = -1;
    const ocupadasTablero = listaTablero.filter(u => u).length;
    
    if (ocupadasTablero < maxUnidades) {
        hueco = listaTablero.findIndex(x => x === null);
    }
    
        // 🆕 FIX: si el Pokémon es una evolución (base: false), forzar nivel 2★
    // para evitar que las fusiones salten niveles (Charmeleon 1★ → Charizard 2★).
    // Los Pokémon base siguen entrando a 1★ como antes.
    const esEvolucion = (data.base === false);
    const nivelInicial = esEvolucion ? 2 : 1;

    if (hueco === -1) {
        hueco = listaBanquillo.findIndex(x => x === null);
        if (hueco === -1) {
            addConsoleMessage(`❌ No hay espacio en tablero ni banquillo`, 'error');
            return;
        }
        const unidad = new Unidad(data, nivelInicial, data.id, data.coste);
        unidad.equipo = destino === 'jugador' ? 'player' : 'enemy';
        if (nivelInicial >= 2) {
            unidad.movSecundarioDesbloqueado = true;
        }
        listaBanquillo[hueco] = unidad;
        addConsoleMessage(`✅ ${nombrePokemon} ${nivelInicial}★ añadido al banquillo (${destino})`, 'success');
    } else {
        const unidad = new Unidad(data, nivelInicial, data.id, data.coste);
        unidad.equipo = destino === 'jugador' ? 'player' : 'enemy';
        if (nivelInicial >= 2) {
            unidad.movSecundarioDesbloqueado = true;
        }
        listaTablero[hueco] = unidad;
        addConsoleMessage(`✅ ${nombrePokemon} ${nivelInicial}★ añadido al tablero (${destino})`, 'success');
    }
    
    if (destino === 'jugador') {
        if (typeof aplicarSinergias === 'function') aplicarSinergias();
    } else {
        if (typeof aplicarSinergiasEnemigo === 'function') aplicarSinergiasEnemigo();
    }
    
    if (typeof renderizar === 'function') renderizar();
    renderizarContenidoPanel();
}

// ============================================================
// CATÁLOGO DE OBJETOS - CON SELECTOR DE LADO
// ============================================================

function construirCatalogoObjetos() {
    const filtro = filtroCreative.objetos;
    const todos = (typeof OBJETOS !== 'undefined') ? Object.keys(OBJETOS) : [];
    
    let lista = todos.filter(nombre => {
        if (filtro.texto && !nombre.toLowerCase().includes(filtro.texto.toLowerCase())) return false;
        if (filtro.tipo !== 'todos') {
            const obj = OBJETOS[nombre];
            if (filtro.tipo === 'chips' && !nombre.startsWith('Chip')) return false;
            if (filtro.tipo === 'normales' && nombre.startsWith('Chip')) return false;
            if (filtro.tipo === 'unico' && !obj.unico) return false;
        }
        return true;
    });
    
    lista.sort((a, b) => a.localeCompare(b));
    
    // ⬅️ Info de ambos baúles
    const baulJugadorCount = (typeof baulObjetos !== 'undefined') ? baulObjetos.length : 0;
    const baulEnemigoCount = (typeof enemyBaulObjetos !== 'undefined') ? enemyBaulObjetos.length : 0;
    const maxBaul = CONFIG.MAX_BAUL || 8;
    
    let html = `
        <div class="creative-catalogo-header">
            <input type="text" class="creative-input" id="creativeBuscar-objetos" 
                   placeholder="🔍 Buscar objeto..." 
                   value="${filtro.texto}">
            <select class="creative-select" id="creativeTipo-objetos">
                <option value="todos">📦 Todos los objetos</option>
                <option value="normales" ${filtro.tipo === 'normales' ? 'selected' : ''}>🎁 Objetos normales</option>
                <option value="chips" ${filtro.tipo === 'chips' ? 'selected' : ''}>🧩 Chips de tipo</option>
                <option value="unico" ${filtro.tipo === 'unico' ? 'selected' : ''}>⭐ Únicos</option>
            </select>
        </div>
        
        <!-- ⬅️ SELECTOR DE LADO -->
        <div class="creative-lado-selector">
            <div class="creative-lado-titulo">🎯 ¿A quién le das el objeto?</div>
            <div class="creative-lado-botones">
                <button class="creative-lado-btn ${ladoObjetosActivo === 'jugador' ? 'active jugador' : ''}" 
                        data-lado="jugador">
                    🛡️ JUGADOR
                    <span class="creative-lado-contador">${baulJugadorCount}/${maxBaul}</span>
                </button>
                <button class="creative-lado-btn ${ladoObjetosActivo === 'enemigo' ? 'active enemigo' : ''}" 
                        data-lado="enemigo">
                    🗡️ ENEMIGO
                    <span class="creative-lado-contador">${baulEnemigoCount}/${maxBaul}</span>
                </button>
            </div>
        </div>
        
        <div class="creative-estado">
            <span>🛡️ Baúl jugador: <strong>${baulJugadorCount}/${maxBaul}</strong></span>
            <span>🗡️ Baúl enemigo: <strong>${baulEnemigoCount}/${maxBaul}</strong></span>
            <span>📊 Resultados: <strong>${lista.length}</strong></span>
        </div>
        
        <div class="creative-grid creative-grid-objetos" id="creativeGrid-objetos">
    `;
    
    if (lista.length === 0) {
        html += `<div class="creative-vacio">No hay objetos que coincidan con los filtros</div>`;
    } else {
        for (let nombre of lista) {
            const obj = OBJETOS[nombre];
            
            let iconoHtml = '';
            if (obj.emoji && obj.emoji.includes('.png')) {
                iconoHtml = `<img src="${obj.emoji}" class="creative-objeto-icon" alt="${nombre}" onerror="this.style.display='none'">`;
            } else {
                iconoHtml = `<span class="creative-objeto-emoji">${obj.emoji || '📦'}</span>`;
            }
            
            // ⬅️ Clase según el lado activo
            const ladoClass = ladoObjetosActivo === 'jugador' ? 'lado-jugador' : 'lado-enemigo';
            
            html += `
                <div class="creative-objeto-card ${ladoClass}" data-nombre="${nombre}" title="${obj.descripcion || ''}">
                    ${iconoHtml}
                    <div class="creative-objeto-nombre">${nombre}</div>
                </div>
            `;
        }
    }
    
    html += `</div>`;
    return html;
}

function conectarEventosCatalogoObjetos() {
    const input = document.getElementById('creativeBuscar-objetos');
    const selectTipo = document.getElementById('creativeTipo-objetos');
    const grid = document.getElementById('creativeGrid-objetos');
    
    // ⬅️ Botones del selector de lado
    document.querySelectorAll('.creative-lado-btn').forEach(btn => {
        btn.addEventListener('click', function() {
            ladoObjetosActivo = this.dataset.lado;
            addConsoleMessage(`🎯 Objetos ahora van al baúl: ${ladoObjetosActivo.toUpperCase()}`, 'info');
            renderizarContenidoPanel();
        });
    });
    
    if (input) {
        input.addEventListener('input', function() {
            filtroCreative.objetos.texto = this.value;
            renderizarContenidoPanel();
        });
    }
    if (selectTipo) {
        selectTipo.addEventListener('change', function() {
            filtroCreative.objetos.tipo = this.value;
            renderizarContenidoPanel();
        });
    }
    
    if (grid) {
        grid.querySelectorAll('.creative-objeto-card').forEach(card => {
            card.addEventListener('click', function() {
                const nombre = this.dataset.nombre;
                creativeAñadirObjeto(nombre, ladoObjetosActivo);
            });
        });
    }
}

// ============================================================
// AÑADIR OBJETO AL BAÚL (jugador o enemigo)
// ============================================================

function creativeAñadirObjeto(nombreObjeto, lado) {
    if (combatiendo) {
        addConsoleMessage('⛔ No puedes añadir objetos durante el combate', 'error');
        return;
    }
    
    const maxBaul = CONFIG.MAX_BAUL || 8;
    
    if (lado === 'jugador') {
        if (typeof baulObjetos === 'undefined') {
            addConsoleMessage('❌ baulObjetos no está definido', 'error');
            return;
        }
        if (baulObjetos.length >= maxBaul) {
            addConsoleMessage(`❌ Baúl del jugador lleno (${maxBaul} objetos máximo)`, 'error');
            return;
        }
        baulObjetos.push(nombreObjeto);
        addConsoleMessage(`✅ ${nombreObjeto} → Baúl JUGADOR`, 'success');
        
        if (typeof actualizarBadgeBaul === 'function') actualizarBadgeBaul();
        if (typeof actualizarObjetosVerticales === 'function') actualizarObjetosVerticales();
    } else {
        if (typeof enemyBaulObjetos === 'undefined') {
            addConsoleMessage('❌ enemyBaulObjetos no está definido', 'error');
            return;
        }
        if (enemyBaulObjetos.length >= maxBaul) {
            addConsoleMessage(`❌ Baúl del enemigo lleno (${maxBaul} objetos máximo)`, 'error');
            return;
        }
        enemyBaulObjetos.push(nombreObjeto);
        addConsoleMessage(`✅ ${nombreObjeto} → Baúl ENEMIGO`, 'success');
        
        if (typeof actualizarObjetosVerticalesEnemigo === 'function') actualizarObjetosVerticalesEnemigo();
    }
    
    if (typeof renderizar === 'function') renderizar();
    renderizarContenidoPanel();
}

// ============================================================
// ACCIONES RÁPIDAS
// ============================================================

function accionPoner3Estrellas() {
    if (combatiendo) {
        addConsoleMessage('⛔ No puedes hacer esto durante el combate', 'error');
        return;
    }
    
    let count = 0;
    
    function procesarLista(lista) {
        for (let i = 0; i < lista.length; i++) {
            if (lista[i] && !lista[i].esZacian) {
                let unidadActual = lista[i];
                for (let n = unidadActual.nivel; n < 3; n++) {
                    const evolucion = unidadActual.pokemon.evolucion;
                    if (evolucion) {
                        const evolData = getPokemonPorNombre(evolucion);
                        if (evolData) {
                            const nueva = new Unidad(evolData, n + 1, unidadActual.baseId, unidadActual.costeOriginal);
                            nueva.objetos = [...(unidadActual.objetos || [])];
                            nueva.equipo = unidadActual.equipo;
                            lista[i] = nueva;
                            unidadActual = nueva;
                        } else {
                            unidadActual.nivel = n + 1;
                            unidadActual.actualizarStats();
                        }
                    } else {
                        unidadActual.nivel = n + 1;
                        unidadActual.actualizarStats();
                    }
                }
                count++;
            }
        }
    }
    
    procesarLista(tablero);
    procesarLista(banquillo);
    procesarLista(enemyBoard);
    procesarLista(enemyBanquillo);
    
    aplicarSinergias();
    aplicarSinergiasEnemigo();
    renderizar();
    renderizarContenidoPanel();
    addConsoleMessage(`⭐ ${count} unidades puestas a 3★`, 'success');
}

function accionLimpiarTodo() {
    if (combatiendo) {
        addConsoleMessage('⛔ No puedes hacer esto durante el combate', 'error');
        return;
    }
    
    for (let i = 0; i < tablero.length; i++) {
        if (tablero[i] && !tablero[i].esZacian) tablero[i] = null;
    }
    for (let i = 0; i < banquillo.length; i++) banquillo[i] = null;
    for (let i = 0; i < enemyBoard.length; i++) {
        if (enemyBoard[i] && !enemyBoard[i].esZacian) enemyBoard[i] = null;
    }
    for (let i = 0; i < enemyBanquillo.length; i++) enemyBanquillo[i] = null;
    
    aplicarSinergias();
    aplicarSinergiasEnemigo();
    renderizar();
    renderizarContenidoPanel();
    addConsoleMessage('🧹 Tableros limpiados', 'success');
}

function accionDarOro() {
    oro += 100;
    if (typeof enemyGold !== 'undefined') enemyGold += 100;
    
    actualizarInfoJugador();
    actualizarInfoEnemigo();
    renderizarContenidoPanel();
    addConsoleMessage(`💰 +100 oro (total: ${oro})`, 'success');
}

function accionNivelMaximo() {
    nivelJugador = CONFIG.NIVEL_MAXIMO;
    if (typeof enemyLevel !== 'undefined') enemyLevel = CONFIG.NIVEL_MAXIMO;
    experiencia = 0;
    
    actualizarInfoJugador();
    actualizarInfoEnemigo();
    renderizarContenidoPanel();
    addConsoleMessage(`⬆️ Nivel máximo (${nivelJugador})`, 'success');
}

function accionAvanzarRonda() {
    fase++;
    ronda = fase;
    document.getElementById('faseStats').innerHTML = `Ronda ${fase}`;
    
    if (!tiendaBloqueada) {
        generarTienda();
    }
    generarTiendaEnemigo();
    
    renderizar();
    renderizarContenidoPanel();
    addConsoleMessage(`🎲 Ronda avanzada a ${fase}`, 'success');
}

function accionResetCompleto(forzar = false) {
    const sinConfirmar = (forzar === true);
    if (!sinConfirmar && !confirm('¿Resetear TODO el estado del juego? (tableros, oro, nivel, ronda)')) return;
    if (typeof combatiendo !== 'undefined' && combatiendo) {
        addConsoleMessage('⏳ Espera a que termine el combate para resetear', 'info');
        return;
    }

    oro = 100;
    nivelJugador = 1;
    experiencia = 0;
    fase = 1;
    ronda = 1;
    vidaJugador = 50;
    racha = 0;
    victorias = 0;

    if (typeof enemyGold !== 'undefined') enemyGold = 100;
    if (typeof enemyLevel !== 'undefined') enemyLevel = 1;
    if (typeof enemyHealth !== 'undefined') enemyHealth = 50;
    if (typeof enemyWinStreak !== 'undefined') enemyWinStreak = 0;
    if (typeof enemyLossStreak !== 'undefined') enemyLossStreak = 0;
    if (typeof primerCombateRealizado !== 'undefined') primerCombateRealizado = false;
    if (typeof enemyPrimerCombateRealizado !== 'undefined') enemyPrimerCombateRealizado = false;

    // Devolver objetos al baúl antes de limpiar (incluye Zacian/Articuno)
    for (let i = 0; i < tablero.length; i++) {
        if (tablero[i] && !tablero[i].esZacian && !tablero[i].esArticuno) {
            if (typeof autoDevolverObjetosAlBaul === 'function') autoDevolverObjetosAlBaul(tablero[i], 'jugador');
        }
        tablero[i] = null;
    }
    for (let i = 0; i < banquillo.length; i++) {
        if (banquillo[i] && !banquillo[i].esZacian && !banquillo[i].esArticuno) {
            if (typeof autoDevolverObjetosAlBaul === 'function') autoDevolverObjetosAlBaul(banquillo[i], 'jugador');
        }
        banquillo[i] = null;
    }
    for (let i = 0; i < enemyBoard.length; i++) {
        if (enemyBoard[i] && !enemyBoard[i].esZacian && !enemyBoard[i].esArticuno) {
            if (typeof autoDevolverObjetosAlBaul === 'function') autoDevolverObjetosAlBaul(enemyBoard[i], 'enemigo');
        }
        enemyBoard[i] = null;
    }
    for (let i = 0; i < enemyBanquillo.length; i++) {
        if (enemyBanquillo[i] && !enemyBanquillo[i].esZacian && !enemyBanquillo[i].esArticuno) {
            if (typeof autoDevolverObjetosAlBaul === 'function') autoDevolverObjetosAlBaul(enemyBanquillo[i], 'enemigo');
        }
        enemyBanquillo[i] = null;
    }

    baulObjetos = [];
    if (typeof enemyBaulObjetos !== 'undefined') enemyBaulObjetos = [];
    tienda = [];
    if (typeof enemyTienda !== 'undefined') enemyTienda = [];
    if (typeof objetosEnTienda !== 'undefined') objetosEnTienda = [];
    if (typeof enemyObjetosEnTienda !== 'undefined') enemyObjetosEnTienda = [];
    if (typeof tiendaRonda2Comprada !== 'undefined') tiendaRonda2Comprada = false;
    if (typeof objetoCompradoEstaRonda !== 'undefined') objetoCompradoEstaRonda = false;
    if (typeof enemyObjetoCompradoEstaRonda !== 'undefined') enemyObjetoCompradoEstaRonda = false;

    window._ultimaVictoriaJugador = undefined;
    window._ultimoDanoRecibidoJugador = 0;
    window._ultimoRivalCombatido = null;
    window.fearAuraStacks = 0;
    window.enemyFearAuraStacks = 0;

    // Limpiar invocaciones especiales
    if (typeof zacianUnidad !== 'undefined') zacianUnidad = null;
    if (typeof articunoUnidad !== 'undefined') articunoUnidad = null;
    if (typeof zacianNivel !== 'undefined') zacianNivel = 0;
    if (typeof articunoActivado !== 'undefined') articunoActivado = false;
    if (typeof articunoVisible !== 'undefined') articunoVisible = false;
    window.zacianEnemigoUnidad = null;
    window.articunoEnemigoUnidad = null;
    const zc = document.getElementById('zacianContainer');
    if (zc) zc.style.display = 'none';
    const ac = document.getElementById('articunoContainer');
    if (ac) ac.style.display = 'none';

    // Quitar restos visuales del último combate
    const cov = document.getElementById('combatOverlay');
    if (cov) { cov.style.display = 'none'; cov.className = 'combat-overlay'; }
    const post = document.getElementById('postCombateOverlay');
    if (post) { post.classList.remove('visible'); post.style.display = 'none'; }
    document.body.classList.remove('celebrando', 'combatiendo');
    document.querySelectorAll('.board-cell.muerto').forEach(cell => { cell.style.display = ''; });

    aplicarSinergias();
    aplicarSinergiasEnemigo();
    renderizar();
    renderizarContenidoPanel();
    if (typeof actualizarInfoJugador === 'function') actualizarInfoJugador();
    if (typeof actualizarInfoEnemigo === 'function') actualizarInfoEnemigo();
    if (typeof actualizarContadorRondaVisual === 'function') actualizarContadorRondaVisual();
    addConsoleMessage('🗑️ Sandbox reiniciado: tableros, oro, objetos y nivel a cero.', 'success');
}

// 🧪 Botón RESET del sandbox: sin confirm para poder repetir rápido.
window.resetSandbox = function() { accionResetCompleto(true); };


function accionCombatir() {
    if (combatiendo) {
        addConsoleMessage('⛔ Ya hay un combate en curso', 'error');
        return;
    }
    
    if (tablero.filter(u => u).length === 0) {
        addConsoleMessage('❌ No tienes Pokémon en el tablero', 'error');
        return;
    }
    
    cerrarPanelCreativo();
    setTimeout(() => {
        if (typeof combatir === 'function') combatir();
    }, 300);
}

// ============================================================
// INICIALIZAR MODO CREATIVO
// ============================================================

function initModoCreativo() {
    console.log('🧪 Inicializando modo creativo...');
    
    window.modoCreativo = true;

    // 🧪 Mostrar el botón RESET solo en sandbox
    const btnResetSandbox = document.getElementById('btnResetSandbox');
    if (btnResetSandbox) btnResetSandbox.style.display = 'inline-flex';

    // 🧪 En creativo el ranking del torneo no pinta nada
    const rankingCreativo = document.getElementById('rankingTorneo');
    if (rankingCreativo) rankingCreativo.style.display = 'none';

            // 🆕 FIX: forzar el terreno creativo al entrar en Modo Creativo.
    // Usamos la función centralizada para que quede coherente.
    if (typeof window.aplicarTerrenoActual === 'function') {
        window.aplicarTerrenoActual(window.rivalActual);
    } else {
        document.body.style.setProperty('--terreno-actual', `url('../assets/backgrounds/terreno-creativo.webp')`);
    }
    console.log('🎨 Terreno forzado a creativo (Modo Creativo)');
    
    abrirPanelCreativo();
    
    document.addEventListener('keydown', function(e) {
        if (e.key === 'F1' && window.modoCreativo) {
            e.preventDefault();
            togglePanelCreativo();
        }
    });
    
    addConsoleMessage('🧪 MODO CREATIVO ACTIVADO - Pulsa F1 para abrir el panel', 'success');
}

