/* ==================== js/ui/previewSubirNivel.js ==================== */
// ============================================================
// UI - PREVIEW DE SUBIDA DE NIVEL
// ============================================================
// Muestra, a la izquierda del +4 EXP, un botón con los iconos
// de lo que desbloqueas al subir de nivel:
//   - ⚪ Pokéball: si la siguiente subida da un slot extra
//   - 💿 Disco Definitivo: si la siguiente subida da un Disco
//   - ⭐ Estrella: si ya estás en nivel máximo
//   - ⬆️ Neutro: si no da nada relevante
//
// También se encarga de:
//   - Poner la clase .nivel-maximo al wrapper al llegar a nivel 8
//   - Deshabilitar el +4 XP al llegar a nivel 8
// ============================================================

(function () {
    'use strict';

    const TABLA_MAX_UNIDADES = {
        1: 1, 2: 2, 3: 3, 4: 4, 5: 4, 6: 5, 7: 6, 8: 6
    };

    let _tooltipActivo = null;
    let _nivelAnteriorVisto = -1;

    // ============================================================
    // Calcular qué se desbloquea al pasar del nivel actual al siguiente
    // ============================================================
    function calcularRecompensaSubida() {
        const nivelActual = (typeof nivelJugador !== 'undefined') ? Number(nivelJugador) : 1;
        const nivelMax = (typeof CONFIG !== 'undefined' && CONFIG.NIVEL_MAXIMO) ? CONFIG.NIVEL_MAXIMO : 8;
        const nivelSiguiente = Math.min(nivelActual + 1, nivelMax);

        if (nivelActual >= nivelMax) {
            return {
                esMaximo: true,
                daSlot: false,
                daDisco: false,
                slotsActuales: TABLA_MAX_UNIDADES[nivelActual] || 1,
                slotsSiguientes: TABLA_MAX_UNIDADES[nivelActual] || 1,
                nivelActual,
                nivelSiguiente
            };
        }

        const slotsActuales = TABLA_MAX_UNIDADES[nivelActual] || 1;
        const slotsSiguientes = TABLA_MAX_UNIDADES[nivelSiguiente] || 1;

        return {
            esMaximo: false,
            daSlot: slotsSiguientes > slotsActuales,
            daDisco: (nivelSiguiente === 5 || nivelSiguiente === 8),
            slotsActuales,
            slotsSiguientes,
            nivelActual,
            nivelSiguiente
        };
    }

    // ============================================================
    // Construir HTML de iconos del botón
    // ============================================================
    function construirIconosHTML(info) {
        if (info.esMaximo) return '<span class="preview-emoji" title="Nivel máximo">⭐</span>';

        const partes = [];
        if (info.daSlot) partes.push('<span class="preview-pokeball" title="+1 slot en el tablero"></span>');
        if (info.daDisco) partes.push('<span class="preview-disco" title="+1 Disco Definitivo">💿</span>');

        if (partes.length === 0) {
            return '<span class="preview-emoji" title="Subir de nivel">⬆️</span>';
        }
        return partes.join('');
    }

    // ============================================================
    // Construir HTML del tooltip flotante
    // ============================================================
    function construirTooltipHTML(info) {
        if (info.esMaximo) {
            return `
                <div class="tooltip-titulo">⭐ Nivel máximo</div>
                <div class="tooltip-linea"><span class="icono">🏆</span><span>Ya estás en el nivel máximo (${info.nivelActual}).</span></div>
            `;
        }

        let html = `<div class="tooltip-titulo">⬆️ Nivel ${info.nivelActual} → ${info.nivelSiguiente}</div>`;

        if (info.daSlot) {
            html += `<div class="tooltip-linea destacada"><span class="icono">⚪</span><span>+1 slot en el tablero (${info.slotsActuales} → ${info.slotsSiguientes})</span></div>`;
        } else {
            html += `<div class="tooltip-linea"><span class="icono">🛡️</span><span>Slots de tablero: ${info.slotsActuales} (sin cambios)</span></div>`;
        }

        if (info.daDisco) {
            html += `<div class="tooltip-linea destacada-dorada"><span class="icono">💿</span><span>+1 Disco Definitivo (desbloquea ULTI)</span></div>`;
        }

        return html;
    }

    // ============================================================
    // Actualizar iconos + tooltip del botón preview
    // ============================================================
    function actualizarBotonPreview() {
        const btn = document.getElementById('btnPreviewSubirNivel');
        const contenedor = document.getElementById('previewIconosSubirNivel');
        if (!btn || !contenedor) return;

        const info = calcularRecompensaSubida();

        contenedor.innerHTML = construirIconosHTML(info);
        btn.classList.toggle('sin-recompensa', !info.daSlot && !info.daDisco && !info.esMaximo);

        if (info.esMaximo) {
            btn.title = 'Nivel máximo alcanzado';
        } else {
            const partes = [];
            if (info.daSlot) partes.push('+1 slot en el tablero');
            if (info.daDisco) partes.push('+1 Disco Definitivo');
            if (partes.length === 0) partes.push('Subir de nivel');
            btn.title = `Subir a nivel ${info.nivelSiguiente}: ${partes.join(' + ')}`;
        }

        if (_tooltipActivo && _tooltipActivo.classList.contains('visible')) {
            const contenido = _tooltipActivo.querySelector('.tooltip-contenido');
            if (contenido) contenido.innerHTML = construirTooltipHTML(info);
        }
    }

    // ============================================================
    // Deshabilitar +4 XP al llegar a nivel máximo
    // ============================================================
    function actualizarBotonExpNivelMaximo() {
        const btn = document.getElementById('btnAdelantarNivel');
        if (!btn) return;

        const nivelActual = (typeof nivelJugador !== 'undefined') ? Number(nivelJugador) : 1;
        const nivelMax = (typeof CONFIG !== 'undefined' && CONFIG.NIVEL_MAXIMO) ? CONFIG.NIVEL_MAXIMO : 8;

        if (nivelActual >= nivelMax) {
            btn.disabled = true;
            btn.classList.add('btn-exp-max');
            btn.title = 'Nivel máximo alcanzado';
        } else {
            btn.disabled = false;
            btn.classList.remove('btn-exp-max');
            btn.title = '+4 EXP';
        }
    }

    // ============================================================
    // Clase .nivel-maximo al wrapper (barra visible, textos ocultos)
    // ============================================================
    function actualizarEstadoNivelMaximo() {
        const wrapper = document.querySelector('.nivel-exp-wrapper');
        if (wrapper) {
            const nivelActual = (typeof nivelJugador !== 'undefined') ? Number(nivelJugador) : 1;
            const nivelMax = (typeof CONFIG !== 'undefined' && CONFIG.NIVEL_MAXIMO) ? CONFIG.NIVEL_MAXIMO : 8;

            if (nivelActual >= nivelMax) {
                wrapper.classList.add('nivel-maximo');
            } else {
                wrapper.classList.remove('nivel-maximo');
            }
        }
        actualizarBotonExpNivelMaximo();
    }

    // ============================================================
    // Tooltip flotante
    // ============================================================
    function crearTooltip() {
        if (_tooltipActivo) return _tooltipActivo;
        const tip = document.createElement('div');
        tip.className = 'preview-tooltip-float';
        tip.innerHTML = '<div class="tooltip-contenido"></div>';
        document.body.appendChild(tip);
        _tooltipActivo = tip;
        return tip;
    }

    function posicionarTooltip(btn) {
        const tip = crearTooltip();
        const rect = btn.getBoundingClientRect();
        const tipRect = tip.getBoundingClientRect();

        let top = rect.top - tipRect.height - 10;
        let left = rect.left + rect.width / 2 - tipRect.width / 2;

        if (top < 8) top = rect.bottom + 10;
        if (left < 8) left = 8;
        if (left + tipRect.width > window.innerWidth - 8) {
            left = window.innerWidth - tipRect.width - 8;
        }

        tip.style.top = top + 'px';
        tip.style.left = left + 'px';
    }

    function mostrarTooltip(btn) {
        const tip = crearTooltip();
        const info = calcularRecompensaSubida();
        const contenido = tip.querySelector('.tooltip-contenido');
        if (contenido) contenido.innerHTML = construirTooltipHTML(info);

        tip.style.visibility = 'hidden';
        tip.classList.add('visible');
        tip.style.visibility = '';
        posicionarTooltip(btn);
    }

    function ocultarTooltip() {
        if (_tooltipActivo) _tooltipActivo.classList.remove('visible');
    }

    // ============================================================
    // Init
    // ============================================================
    function initPreviewSubirNivel() {
        const btn = document.getElementById('btnPreviewSubirNivel');
        if (!btn) {
            setTimeout(initPreviewSubirNivel, 200);
            return;
        }

        if (btn.dataset.previewEnganchado !== '1') {
            btn.dataset.previewEnganchado = '1';
            btn.addEventListener('mouseenter', () => mostrarTooltip(btn));
            btn.addEventListener('mouseleave', ocultarTooltip);
            btn.addEventListener('focus', () => mostrarTooltip(btn));
            btn.addEventListener('blur', ocultarTooltip);
            btn.addEventListener('click', (e) => { e.preventDefault(); e.stopPropagation(); });
            window.addEventListener('resize', () => {
                if (_tooltipActivo && _tooltipActivo.classList.contains('visible')) {
                    posicionarTooltip(btn);
                }
            });
        }

        actualizarEstadoNivelMaximo();
        actualizarBotonPreview();

        if (window._previewSubirNivelIntervalId) {
            clearInterval(window._previewSubirNivelIntervalId);
        }

        window._previewSubirNivelIntervalId = setInterval(() => {
            const nivelActual = (typeof nivelJugador !== 'undefined') ? Number(nivelJugador) : 1;
            if (nivelActual !== _nivelAnteriorVisto) {
                _nivelAnteriorVisto = nivelActual;
                actualizarEstadoNivelMaximo();
                actualizarBotonPreview();
            }
        }, 500);

        console.log('✅ previewSubirNivel.js: botón de preview inicializado');
    }

    window.initPreviewSubirNivel = initPreviewSubirNivel;
    window.actualizarBotonPreviewSubirNivel = actualizarBotonPreview;
    window.calcularRecompensaSubida = calcularRecompensaSubida;

    if (document.readyState === 'complete' || document.readyState === 'interactive') {
        setTimeout(initPreviewSubirNivel, 250);
    } else {
        document.addEventListener('DOMContentLoaded', () => {
            setTimeout(initPreviewSubirNivel, 250);
        });
    }

    console.log('✅ previewSubirNivel.js cargado');
})();
;

/* ==================== js/ui/wakeLock.js ==================== */
// ============================================================
// 🔆 MANTENER LA PANTALLA ENCENDIDA (móvil)
// ============================================================
// Una web no puede evitar el bloqueo de pantalla por sí sola: el sistema
// apaga la pantalla por inactividad. La Screen Wake Lock API sí lo permite
// (Chrome/Edge Android 84+, Safari iOS 16.4+, siempre en HTTPS).
//
// - Se activa al pulsar JUGAR (o al primer toque dentro de la partida).
// - Si el navegador la suelta (pestaña oculta, cambio de app), se vuelve a
//   pedir al volver a la página.
// - Al salir/recargar se libera sola (pagehide).
// ============================================================
(function () {
    let sentinel = null;
    let activo = false;
    let pidiendo = false;
    let avisoMostrado = false;

    function soportado() {
        return !!(navigator.wakeLock && typeof navigator.wakeLock.request === 'function');
    }

    async function pedir() {
        if (!activo || pidiendo) return;
        if (document.visibilityState !== 'visible') return;
        if (sentinel) return;
        if (!soportado()) {
            if (!avisoMostrado) {
                console.log('🔆 Este navegador no soporta Wake Lock: la pantalla puede apagarse sola.');
                avisoMostrado = true;
            }
            return;
        }
        pidiendo = true;
        try {
            sentinel = await navigator.wakeLock.request('screen');
            sentinel.addEventListener('release', function () { sentinel = null; });
            if (window.DEBUG) console.log('🔆 Pantalla siempre encendida (Wake Lock activo)');
        } catch (e) {
            if (!avisoMostrado) {
                console.log('🔆 No se pudo mantener la pantalla encendida: ' + (e && e.message ? e.message : e));
                avisoMostrado = true;
            }
        } finally {
            pidiendo = false;
        }
    }

    window.activarPantallaSiempre = function () {
        activo = true;
        pedir();
    };

    window.desactivarPantallaSiempre = function () {
        activo = false;
        if (sentinel) {
            try { sentinel.release(); } catch (e) { }
            sentinel = null;
        }
    };

    // Al volver a la pestaña, el navegador puede haber liberado el bloqueo.
    document.addEventListener('visibilitychange', function () {
        if (document.visibilityState === 'visible') pedir();
    });

    // Primer toque dentro del juego (cubre también el modo online, que no
    // pasa por el botón JUGAR).
    document.addEventListener('pointerdown', function () {
        var juego = document.getElementById('juegoContainer');
        if (!juego || juego.offsetParent === null) return;
        if (!activo) activo = true;
        if (!sentinel) pedir();
    }, { passive: true });

    // Al cerrar/recargar.
    window.addEventListener('pagehide', function () {
        if (sentinel) {
            try { sentinel.release(); } catch (e) { }
            sentinel = null;
        }
    });

    // Para depurar desde la consola
    window._wakeLockInfo = function () {
        return { soportado: soportado(), activo: activo, sentinel: !!sentinel };
    };
})();

;

/* ==================== js/ui/fullscreen.js ==================== */
// ============================================================
// ⛶ PANTALLA COMPLETA EN MÓVIL
// ============================================================
// - En Android/Chrome se pide la Fullscreen API al pulsar JUGAR (gesto
//   de usuario) y se bloquea la orientación en horizontal.
// - En iPhone Safari la API no existe: se muestra un aviso para añadir
//   la web a la pantalla de inicio (ahí arranca sin barras del navegador).
// - Botón manual en Ajustes por si se sale con el gesto del sistema.
// ============================================================
(function () {
    const UA = navigator.userAgent || '';
    const esTactil = () =>
        (navigator.maxTouchPoints || 0) > 0 ||
        (window.matchMedia && matchMedia('(pointer: coarse)').matches) ||
        /Android|iPhone|iPad|iPod|Mobile/i.test(UA);

    const esiOS = /iPhone|iPad|iPod/i.test(UA) && !window.MSStream;
    const enApp = () =>
        (window.matchMedia && matchMedia('(display-mode: fullscreen), (display-mode: standalone)').matches) ||
        window.navigator.standalone === true;

    let avisoIOSMostrado = false;

    function toast(texto, ms) {
        try {
            const el = document.createElement('div');
            el.textContent = texto;
            el.style.cssText = [
                'position:fixed', 'left:50%', 'bottom:18px', 'transform:translateX(-50%)',
                'max-width:min(92vw,520px)', 'background:rgba(8,14,28,.96)',
                'border:1.5px solid rgba(77,212,247,.55)', 'color:#e6f6ff',
                'padding:10px 16px', 'border-radius:12px', 'font:600 13px/1.35 Inter,sans-serif',
                'z-index:100050', 'box-shadow:0 8px 30px rgba(0,0,0,.6)', 'text-align:center',
                'pointer-events:none'
            ].join(';');
            document.body.appendChild(el);
            setTimeout(() => { try { el.remove(); } catch (e) { } }, ms || 6500);
        } catch (e) { }
    }

    async function pedir() {
        window._fsIntentos = (window._fsIntentos || 0) + 1;
        if (document.fullscreenElement || enApp()) return true;

        const el = document.documentElement;
        const fn = el.requestFullscreen || el.webkitRequestFullscreen;

        if (!fn) {
            // iPhone/iPad antiguos: no hay API de pantalla completa para la web
            if (esiOS && !avisoIOSMostrado) {
                avisoIOSMostrado = true;
                toast('📱 Para jugar a pantalla completa en iPhone: Compartir → Añadir a pantalla de inicio', 8000);
            }
            return false;
        }

        try {
            const res = fn.call(el, { navigationUI: 'hide' });
            if (res && res.then) await res;
        } catch (e) {
            window._fsLastError = e && e.message ? e.message : String(e);
            return false;
        }

        // Bloquear horizontal (solo funciona tras fullscreen; Android/Chrome)
        try {
            if (screen.orientation && screen.orientation.lock) {
                await screen.orientation.lock('landscape');
            }
        } catch (e) { }

        return true;
    }

    function salir() {
        if (!document.fullscreenElement) return;
        try {
            const p = document.exitFullscreen && document.exitFullscreen();
            if (p && p.catch) p.catch(() => { });
        } catch (e) { }
    }

    function alternar() {
        if (document.fullscreenElement) salir();
        else pedir();
    }

    function actualizarBoton() {
        const b = document.getElementById('btnPantallaCompleta');
        if (!b) return;
        b.textContent = document.fullscreenElement
            ? '⛶ Salir de pantalla completa'
            : '⛶ Pantalla completa';
    }

    window.pantallaCompleta = { pedir, salir, alternar, esTactil, enApp };
    window.activarPantallaCompleta = function () {
        if (esTactil()) pedir();
    };

    document.addEventListener('fullscreenchange', actualizarBoton);
    document.addEventListener('webkitfullscreenchange', actualizarBoton);

    document.addEventListener('DOMContentLoaded', function () {
        const b = document.getElementById('btnPantallaCompleta');
        if (b) {
            b.addEventListener('click', function (e) {
                e.preventDefault();
                alternar();
            });
        }
        actualizarBoton();
    });

    // PWA: permite 'Instalar app' en Android (icono + pantalla completa).
    // El SW no cachea nada; solo habilita la instalación.
    if ('serviceWorker' in navigator && /^https?:$/.test(location.protocol)) {
        window.addEventListener('load', function () {
            navigator.serviceWorker.register('sw.js').catch(function () { });
        });
    }

    // Modo online: no pasa por JUGAR, se activa con el primer toque dentro.
    document.addEventListener('pointerdown', function () {
        const juego = document.getElementById('juegoContainer');
        if (!juego || juego.offsetParent === null) return;
        if (!document.fullscreenElement && esTactil()) pedir();
    }, { passive: true });
})();

;

/* ==================== js/ui/rendimiento.js ==================== */
// ============================================================
// ⚡ MODO RENDIMIENTO (ajuste manual + por defecto en móvil)
// ============================================================
// Desactiva blur (backdrop-filter), sombras y filtros, y usa PNG
// estáticos en vez de GIF animados. Los GIF son la causa principal
// de tirones en móvil: 10 animaciones decodificando a la vez.
// En móvil viene activado por defecto; en PC, desactivado.
// ============================================================
(function () {
    const KEY = 'pktft_graficosLigeros';
    const BTN = 'btnGraficosLigeros';
    const UA = navigator.userAgent || '';

    function esMovil() {
        try {
            return (navigator.maxTouchPoints || 0) > 0 ||
                matchMedia('(pointer: coarse)').matches ||
                /Android|iPhone|iPad|iPod|Mobile/i.test(UA) ||
                innerWidth <= 1100;
        } catch (e) { return false; }
    }

    function leer() {
        try {
            const v = localStorage.getItem(KEY);
            return v === null ? null : v === '1';
        } catch (e) { return null; }
    }
    function guardar(on) {
        try { localStorage.setItem(KEY, on ? '1' : '0'); } catch (e) { }
    }
    function actualizarBoton(on) {
        const b = document.getElementById(BTN);
        if (!b) return;
        b.textContent = on ? '⚡ Modo rendimiento: ON' : '⚡ Modo rendimiento: OFF';
        b.title = 'Sin animaciones de sprites, blur ni sombras. Actívalo si notas tirones.';
    }
    function aplicar(on) {
        on = !!on;
        if (document.body) document.body.classList.toggle('graficos-ligeros', on);
        window.SPRITES_ESTATICOS = on;
        actualizarBoton(on);
    }

    // Vuelve a pintar las vistas actuales para que cambien GIF ↔ PNG.
    function refrescarSprites() {
        if (document.body.classList.contains('combatiendo')) return; // no a mitad de combate
        try {
            if (typeof renderizarTableroJugador === 'function') renderizarTableroJugador();
            if (typeof renderizarTableroEnemigo === 'function') renderizarTableroEnemigo();
            if (typeof renderizarBanquilloJugador === 'function') renderizarBanquilloJugador();
            if (typeof renderizarBanquilloEnemigo === 'function') renderizarBanquilloEnemigo();
            const ov = document.getElementById('tiendaOverlay');
            if (ov && ov.classList.contains('visible') && typeof renderizarTiendaIndependiente === 'function') {
                renderizarTiendaIndependiente(true);
            }
        } catch (e) { }
    }

    function init() {
        const pref = leer();
        const on = (pref === null) ? false : pref;
        aplicar(on);
        if (pref === null) guardar(on); // fija la preferencia inicial

        const b = document.getElementById(BTN);
        if (b) {
            b.addEventListener('click', function (e) {
                e.preventDefault();
                const nuevo = !document.body.classList.contains('graficos-ligeros');
                guardar(nuevo);
                aplicar(nuevo);
                refrescarSprites();
                if (typeof playUISound === 'function') playUISound('click.mp3', 0.08);
            });
        }
    }

    // Aplicar cuanto antes (el script va al final del body)
    if (document.body) {
        const pref = leer();
        aplicar(pref === null ? false : pref);
    }

    // ============================================================
    // 🎞️ SPrites estáticos SOLO durante el combate (móvil)
    // Mantiene las animaciones en tienda/banco/menú, pero evita que
    // 10 GIF animen a la vez mientras se pelea. Se restauran al acabar.
    // ============================================================
    function convertirASpriteEstatico(img) {
        const src = img.getAttribute('src') || '';
        if (!src || src.indexOf('/pokemon/') === -1 || src.indexOf('/static/') !== -1) return;
        if (!/\.gif(\?|$)/.test(src)) return;
        if (!img.dataset.srcAnimado) img.dataset.srcAnimado = src;
        // Si faltara el PNG estático, volver al GIF original
        img.onerror = function () { this.onerror = null; if (this.dataset.srcAnimado) this.src = this.dataset.srcAnimado; };
        img.src = src.replace('/pokemon/', '/pokemon/static/').replace(/\.gif(\?|$)/, '.png');
    }

    window.spritesCombate = {
        estaticos: function () {
            if (!esMovil() || window.SPRITES_ESTATICOS) return;
            try {
                // Todos los sprites del documento: incluye tablero, banco y los
                // que quedan ocultos en la tienda/carta (también consumen CPU).
                document.querySelectorAll('.unit-sprite').forEach(convertirASpriteEstatico);
            } catch (e) { }
        },
        restaurar: function () {
            try {
                const estatico = window.SPRITES_ESTATICOS;
                document.querySelectorAll('.unit-sprite[data-src-animado]').forEach(function (img) {
                    img.onerror = null;
                    // Si el modo rendimiento está ON, se queda el PNG estático.
                    if (!estatico) img.src = img.dataset.srcAnimado;
                    delete img.dataset.srcAnimado;
                });
            } catch (e) { }
        }
    };

    // Si el combate vuelve a pintar el tablero, convertir los sprites nuevos.
    try {
        new MutationObserver(function (muts) {
            if (!document.body.classList.contains('combatiendo')) return;
            if (!esMovil() || window.SPRITES_ESTATICOS) return;
            muts.forEach(function (m) {
                m.addedNodes.forEach(function (n) {
                    if (n.nodeType !== 1) return;
                    if (n.classList && n.classList.contains('unit-sprite')) convertirASpriteEstatico(n);
                    if (n.querySelectorAll) n.querySelectorAll('.unit-sprite').forEach(convertirASpriteEstatico);
                });
            });
        }).observe(document.body, { childList: true, subtree: true });
    } catch (e) { }

    document.addEventListener('DOMContentLoaded', init);

    window.modoRendimiento = {
        activar: function (v) { guardar(!!v); aplicar(!!v); refrescarSprites(); },
        estado: function () { return document.body.classList.contains('graficos-ligeros'); }
    };
})();

;

/* ==================== js/main/audio.js ==================== */
// ============================================================
// MAIN · AUDIO
// Extraído de js/main.js (sin cambios de lógica).
// ============================================================

function iniciarAudio() {
    if (audioContext) return;
    try {
        audioContext = new (window.AudioContext || window.webkitAudioContext)();
    } catch (e) {}
}

function playPokemonCry(pokemonId) {
    if (!audioContext) iniciarAudio();
    if (!audioContext) return;

    // Si el grito no existe (monstruos PvE), sintetizar uno corto en vez de
    // provocar un 404 en cada aparición. Lista en js/data/criasDisponibles.js.
    const crias = window.CRIAS_DISPONIBLES;
    if (crias && !crias.has(String(pokemonId))) {
        const n = parseInt(pokemonId, 10) || 300;
        playSound(300 + (n % 6) * 40, 0.12, 0.08);
        return;
    }

    try {
        const multEfectos = (typeof window._volumenEfectosActual === 'number') ? (window._volumenEfectosActual / 0.5) : 1;
        const volumenFinal = Math.max(0, Math.min(1, 0.3 * multEfectos));
        const cryUrl = CONFIG.CRY_BASE_URL + pokemonId + ".ogg";
        if (audioCache[cryUrl]) {
            const cachedAudio = audioCache[cryUrl];
            cachedAudio.currentTime = 0;
            cachedAudio.volume = volumenFinal;
            cachedAudio.play().catch(() => {});
            return;
        }
        const audio = new Audio(cryUrl);
        audio.volume = volumenFinal;
        audio.addEventListener('canplaythrough', function() { audioCache[cryUrl] = audio; });
        audio.play().catch(() => {});
    } catch (e) {}
}

function playSound(frecuencia, duracion, volumen = 0.08) {
    if (!audioContext) return;
    try {
        const osc = audioContext.createOscillator();
        const gain = audioContext.createGain();
        osc.connect(gain);
        gain.connect(audioContext.destination);
        osc.frequency.value = frecuencia;
        gain.gain.value = volumen;
        gain.gain.exponentialRampToValueAtTime(0.00001, audioContext.currentTime + duracion);
        osc.start();
        osc.stop(audioContext.currentTime + duracion);
    } catch (e) {}
}

function usarFallbackSonido(nombreArchivo) {
    const fallbacks = {
        'click.mp3': { freq: 880, dur: 0.08 },
        'sell.mp3': { freq: 659.25, dur: 0.08 },
        'levelup.mp3': { freq: 523, dur: 0.1 },
        'victoria-ronda.mp3': { freq: 1046, dur: 0.25 },
        'derrota-ronda.mp3': { freq: 220, dur: 0.4 },
        'combate.mp3': { freq: 392, dur: 0.6 }
    };
    const fallback = fallbacks[nombreArchivo];
    if (fallback) playSound(fallback.freq, fallback.dur, 0.08);
    else playSound(880, 0.1, 0.08);
}

function playUISound(nombreArchivo, volumen = 0.3) {
    if (typeof window._volumenEfectosActual === 'number') {
        volumen = volumen * (window._volumenEfectosActual / 0.5);
        if (volumen < 0) volumen = 0;
    }
    if (!audioContext) iniciarAudio();
    if (!audioContext) return;
    try {
        const url = CONFIG.UI_SOUND_URL + nombreArchivo;
        if (uiAudioCache[url]) {
            const audio = uiAudioCache[url];
            audio.currentTime = 0;
            audio.volume = volumen;
            audio.play().catch(() => usarFallbackSonido(nombreArchivo));
            return;
        }
        const audio = new Audio(url);
        audio.volume = volumen;
        audio.preload = 'auto';
        audio.addEventListener('canplaythrough', function() { uiAudioCache[url] = audio; }, { once: true });
        audio.addEventListener('error', function() { usarFallbackSonido(nombreArchivo); });
        audio.play().catch(() => usarFallbackSonido(nombreArchivo));
    } catch (e) {}
}

